/* Generated by tools/build.py from templates/*.json - do not edit by hand. */
window.SIGNOFF_TEMPLATES = [{"id":"schematic","title":"Schematic Review","short":"Schematic","version":2,"description":"Checks a schematic before layout or release: documentation, power, grounding, component ratings, connectivity, processors, interfaces, protection, safety, test and sourcing.","sections":[{"id":"s-gen","title":"General & Documentation","tags":[],"items":[{"id":"sg1","text":"Title block is complete on every sheet (project name, revision, date, author, approver)","hint":"Check every sheet, not just the first; a missing revision on one sheet makes printed sets ambiguous.","tags":[],"severity":"minor"},{"id":"sg2","text":"Revision history is up to date with all changes since the last release documented","hint":"Compare against the previous released PDF or a schematic diff; every ECO should appear.","tags":[],"severity":"minor"},{"id":"sg3","text":"Sheet numbers and total sheet count are correct","hint":"Hierarchical designs often get renumbered on export; check the PDF, not just the CAD view.","tags":[],"severity":"minor"},{"id":"sg4","text":"All referenced documents and datasheets are at the correct revision","hint":"Silicon errata and datasheet revisions can change pinouts, strap values or absolute maximums. Check the revision you designed against is the current one.","tags":[],"severity":"major"},{"id":"sg5","text":"Schematic follows the company drafting style guide","hint":"IPC-2612 is a useful baseline for diagramming documentation. Check symbol conventions, signal flow left to right, and readable net names.","tags":[],"severity":"minor"},{"id":"sch-gen-1","text":"A block diagram exists and matches the schematic hierarchy","hint":"Reviewers should be able to trace every block (power tree, interfaces, processors) from the block diagram to a sheet.","tags":[],"severity":"minor"},{"id":"sch-gen-2","text":"Design requirements (inputs, outputs, environment, interfaces) are written down and traceable to the schematic","hint":"Without a requirements list the review can only check internal consistency, not fitness for purpose.","tags":[],"severity":"major"},{"id":"sch-gen-3","text":"Design notes explain non-obvious choices (strap values, deliberate DNPs, rework options, calculations)","hint":"Put the reason next to the part; a future engineer will otherwise 'fix' a deliberate choice.","tags":[],"severity":"minor"},{"id":"sch-gen-4","text":"Fitted / not-fitted (DNP) and assembly-variant parts are clearly marked and match the BOM variants","hint":"Check each variant BOM against the schematic annotation; DNP errors are a common first-build fault.","tags":[],"severity":"major"}]},{"id":"s-pwr","title":"Power Architecture & Budget","tags":[],"items":[{"id":"sp1","text":"All power nets are correctly named and consistent across sheets","hint":"Look for near-duplicates such as 3V3, +3V3 and VCC_3V3 that the tool treats as separate nets.","tags":[],"severity":"major"},{"id":"sp2","text":"Every IC and polarized part is connected to a rail of the correct voltage and polarity","hint":"Walk each IC's supply pins against its datasheet recommended operating range, including I/O-bank and analog supplies.","tags":[],"severity":"critical"},{"id":"sp8","text":"Inrush current is limited on high-capacitance rails and hot-pluggable inputs","hint":"Estimate inrush from total downstream capacitance and source impedance; check it against fuse, connector and upstream supply limits.","tags":[],"severity":"major"},{"id":"sch-pwr-1","text":"A power tree diagram exists showing every rail, its source, converter type and load","hint":"The power tree is the quickest way to spot missing rails, wrong sources and overloaded regulators.","tags":[],"severity":"major"},{"id":"sch-pwr-2","text":"Power budget is calculated for each rail, with worst-case load below the regulator rating plus margin","hint":"Include start-up, peak and transient loads (radios transmitting, motors starting, FPGA configuration), not just typical current.","tags":[],"severity":"critical"},{"id":"sch-pwr-3","text":"Input supply range (min, nominal, max) is defined and every input-side part is rated for the maximum","hint":"Include tolerance of the source, cable drop and any transients the supply can produce, such as a hot-plugged adapter ringing.","tags":[],"severity":"major"},{"id":"sch-pwr-4","text":"Total input power and efficiency estimate fits the source capability (adapter, USB contract, PoE class, battery)","hint":"Sum the rail budgets through each converter's efficiency at the expected load.","tags":[],"severity":"major"},{"id":"sch-pwr-5","text":"Behavior on power-up, brown-out and power loss is defined for every rail","hint":"Consider what happens when the input sags slowly: regulators dropping out of regulation, MCUs running out of spec, flash writes corrupting.","tags":[],"severity":"major"},{"id":"sch-pwr-6","text":"No back-powering paths exist between rails or through I/O pins when a domain is off","hint":"Check for I/O pins driven into unpowered ICs, USB VBUS feeding back, and body diodes of load switches conducting in reverse.","tags":[],"severity":"major"},{"id":"sch-pwr-7","text":"Sleep / standby current budget is calculated and met, including leakage of always-on parts","hint":"Include pull-up currents, divider currents, regulator quiescent current, LED indicators and leakage through ESD parts.","tags":["low-power","battery"],"severity":"major"}]},{"id":"s-reg","title":"Regulators & Converters","tags":[],"items":[{"id":"sch-reg-1","text":"Each regulator's output voltage set point is calculated and matches the intended rail","hint":"Recalculate from the feedback divider and the datasheet reference voltage, including resistor tolerance and reference accuracy.","tags":[],"severity":"critical"},{"id":"sch-reg-2","text":"Regulator input voltage range covers the full supply range, including transients and dropout at minimum input","hint":"Check LDO dropout and buck maximum duty cycle at minimum input and maximum load.","tags":[],"severity":"critical"},{"id":"sch-reg-3","text":"Switching regulator inductor value, saturation current and RMS current rating suit the worst-case load","hint":"Saturation current should exceed peak inductor current at current limit, not just at full load.","tags":[],"severity":"major"},{"id":"sch-reg-4","text":"Converter input and output capacitors meet datasheet type, ESR and effective capacitance after DC bias","hint":"Ceramic capacitors can lose most of their capacitance at rated voltage; use the manufacturer's DC-bias curves.","tags":[],"severity":"major"},{"id":"sch-reg-5","text":"Loop compensation network is calculated and stable across load, input and temperature range","hint":"Use the vendor design tool or datasheet procedure; check phase margin with real output capacitance after derating.","tags":[],"severity":"major"},{"id":"sch-reg-6","text":"Soft-start time is set to limit inrush and meet any sequencing requirement","hint":"Too fast causes inrush trips; too slow can violate a processor's maximum ramp time.","tags":[],"severity":"major"},{"id":"sch-reg-7","text":"Enable, power-good and mode pins are tied or driven to a defined state","hint":"Floating enable or mode pins can cause random start-up or unexpected light-load mode.","tags":[],"severity":"major"},{"id":"sch-reg-8","text":"LDO power dissipation (Vin - Vout) x Iout is within the package's thermal capability","hint":"Check junction temperature at maximum ambient using the datasheet thermal resistance for the real copper area.","tags":[],"severity":"major"},{"id":"sch-reg-9","text":"Switching frequency is chosen to avoid sensitive bands (radio channels, audio, ADC sampling)","hint":"Consider harmonics as well as the fundamental; spread-spectrum or synchronization may help.","tags":[],"severity":"minor"}]},{"id":"s-gnd","title":"Grounding","tags":[],"items":[{"id":"sp5","text":"Ground nets are clearly defined (e.g. AGND, DGND, PGND, chassis) and separated only where there is a reason","hint":"Each separate ground net needs a documented purpose and a defined connection point.","tags":[],"severity":"major"},{"id":"sp6","text":"Ground connections are present on all ICs and connectors","hint":"Include exposed pads and thermal pads that the datasheet requires to be grounded.","tags":[],"severity":"critical"},{"id":"sa5","text":"Where ground nets are split, they are joined at exactly one intended point","hint":"A single solid ground plane is often preferred over splits; if grounds are split, check there is one deliberate tie (net tie or 0 ohm) and no accidental second path.","tags":[],"severity":"major"},{"id":"sch-gnd-1","text":"Return paths for high-current loads do not share a path with sensitive analog or sensing grounds","hint":"Annotate high-current returns so the layout engineer routes them separately (e.g. Kelvin connections).","tags":[],"severity":"major"},{"id":"sch-gnd-2","text":"Shield and cable-screen terminations are defined (chassis, ground, RC, or floating) with a reason","hint":"Decide this at schematic stage; changing it later usually needs a respin.","tags":[],"severity":"major"},{"id":"sch-gnd-3","text":"Ground references across board-to-board and cable interfaces have enough ground pins for the return current","hint":"Count ground pins against the signal and power pins; too few causes ground bounce and EMC problems.","tags":[],"severity":"major"}]},{"id":"s-dec","title":"Decoupling & Bulk Capacitance","tags":[],"items":[{"id":"sp3","text":"Every supply pin has decoupling per the datasheet recommendation","hint":"Verify capacitor values and note any placement requirement for the layout engineer; a common rule of thumb is one small ceramic per supply pin.","tags":[],"severity":"major"},{"id":"sp4","text":"Bulk capacitance is adequate for each power rail","hint":"Size it for load steps and source impedance; check effective capacitance after DC bias.","tags":[],"severity":"major"},{"id":"sch-dec-1","text":"Decoupling capacitor voltage rating and dielectric are suitable after DC-bias derating","hint":"Small 0402/0201 high-value ceramics can lose most of their capacitance at rated voltage.","tags":[],"severity":"major"},{"id":"sch-dec-2","text":"Total capacitance on each rail is within the regulator's stable range and the source's hot-plug limits","hint":"Excess capacitance can destabilize LDOs, upset soft-start, or exceed USB and hot-swap limits.","tags":[],"severity":"major"},{"id":"sch-dec-3","text":"Analog, PLL and reference supply pins have filtering per datasheet (ferrite, RC or dedicated LDO)","hint":"Check the ferrite or resistor does not drop too much voltage at the pin's maximum current.","tags":[],"severity":"major"},{"id":"sch-dec-4","text":"Ferrite-bead filters are checked for resonance with the downstream capacitance","hint":"An LC formed by a bead and ceramic capacitors can peak and amplify noise; add damping if needed.","tags":[],"severity":"major"},{"id":"sch-dec-5","text":"Power distribution network target impedance is analysed for high-current, fast-transient rails","hint":"Large FPGAs and SoCs often need a PDN analysis or the vendor's decoupling calculator rather than rules of thumb.","tags":["fpga","ddr","high-speed"],"severity":"major"}]},{"id":"s-cmp","title":"Component Selection, Ratings & Derating","tags":[],"items":[{"id":"sc1","text":"All component values (R, L, C) are correct per design calculations","hint":"Spot-check calculated values against the parts in the BOM, including unit prefixes (k vs M, n vs u).","tags":[],"severity":"critical"},{"id":"sc2","text":"Capacitor and passive voltage ratings have adequate margin per the derating policy","hint":"Use the company derating policy; 2x working voltage for ceramics is a common rule of thumb. Tantalum and electrolytic types have their own derating rules.","tags":[],"severity":"major"},{"id":"sc3","text":"Power ratings of resistors and inductors are sufficient with derating applied","hint":"Check pulse and surge ratings too, not only steady-state dissipation, for inrush, sense and snubber resistors.","tags":[],"severity":"major"},{"id":"sc4","text":"Component tolerances are acceptable for the application","hint":"Do a worst-case or tolerance stack-up on dividers, references, filters and timing circuits.","tags":[],"severity":"major"},{"id":"sc8","text":"Ferrite bead impedance and current ratings are verified for every use","hint":"Impedance drops with DC current; check the bead curve at the actual load current.","tags":[],"severity":"major"},{"id":"sch-cmp-1","text":"No part is operated beyond its absolute maximum ratings in any operating mode","hint":"Include start-up, shutdown, fault and transient conditions as well as normal operation.","tags":[],"severity":"critical"},{"id":"sch-cmp-2","text":"Semiconductor current, voltage and power ratings have margin per the derating policy","hint":"MOSFETs, diodes and transistors should be checked at maximum junction temperature, not 25 °C.","tags":[],"severity":"major"},{"id":"sch-cmp-3","text":"Every part's operating temperature range covers the product's environment","hint":"Commercial-grade parts may not cover outdoor, automotive or in-enclosure temperatures.","tags":[],"severity":"major"},{"id":"sch-cmp-4","text":"Automotive-qualified (AEC-Q) parts are used where required","hint":"Check each part number's qualification, not just the family; suffixes often distinguish grades.","tags":["automotive"],"severity":"major"},{"id":"sch-cmp-5","text":"Capacitor dielectric suits the function (C0G/NP0 for timing and filters, X7R/X5R for decoupling)","hint":"Class II dielectrics drift with voltage, temperature and age; they are unsuitable for precision timing or filters.","tags":[],"severity":"major"},{"id":"sch-cmp-6","text":"Capacitor ripple-current ratings are adequate in converters, motor drives and bulk positions","hint":"Calculate RMS ripple current and compare with the rating at operating temperature and frequency.","tags":[],"severity":"major"},{"id":"sch-cmp-7","text":"Ceramic capacitors in high-flex or high-voltage positions use flex-term or suitable package choices","hint":"Large ceramics near board edges, connectors or mounting holes are prone to flex cracking that can short rails.","tags":["harsh-env","automotive","high-current"],"severity":"major"}]},{"id":"s-net","title":"Connectivity & Net Integrity","tags":[],"items":[{"id":"sn1","text":"ERC (Electrical Rules Check) has been run with zero errors","hint":"Run ERC on the final schematic, not an earlier save; errors waived in the tool still count until justified.","tags":[],"severity":"major"},{"id":"sn2","text":"No pin is left unconnected unless the datasheet allows it and it is intentionally marked no-connect","hint":"Check unused inputs on logic, op-amps and comparators; floating CMOS inputs cause extra current and erratic behavior.","tags":[],"severity":"critical"},{"id":"sn3","text":"No-connect markers are placed on all unused pins intended to be left open","hint":"Explicit markers show the omission was deliberate and keep ERC clean.","tags":[],"severity":"minor"},{"id":"sn4","text":"Power pins (VCC, GND) of all ICs are explicitly connected - none hidden or implicit","hint":"Hidden power pins in library symbols can connect to the wrong net name; show them on the symbol.","tags":[],"severity":"critical"},{"id":"sn5","text":"Differential pair nets are correctly paired and labeled (e.g. USB_D+/USB_D-)","hint":"Use consistent _P/_N or +/- suffixes so layout tools recognize the pairs.","tags":[],"severity":"major"},{"id":"sn6","text":"Bus connections and wire junctions are unambiguous (no four-way junctions)","hint":"Use offset T-junctions so a dot is never missed or mis-printed.","tags":[],"severity":"minor"},{"id":"sn7","text":"Net labels are consistent and unique - no accidental shorts or opens from duplicate or misspelled labels","hint":"Review the netlist for nets with a single connection and for unexpectedly merged nets.","tags":[],"severity":"critical"},{"id":"sn8","text":"All connectors have correct pin count, pinout and mating connector called out","hint":"Check against the mating board or cable drawing, watching for pin-1 orientation and mirror-image errors.","tags":[],"severity":"critical"},{"id":"sch-net-1","text":"Every ERC warning is reviewed and either fixed or waived with a recorded reason","hint":"Unreviewed ERC warnings often hide single-pin nets and conflicting drivers.","tags":[],"severity":"major"},{"id":"sch-net-2","text":"Symbol pin numbers match the footprint and the datasheet pinout for every part","hint":"Pay special attention to new or self-made library parts, multi-package parts and SOT-23 transistors whose pinouts vary by vendor.","tags":[],"severity":"critical"},{"id":"sch-net-3","text":"Multi-part symbols have every unit placed, including power units","hint":"An unplaced unit of a quad op-amp or a power-only section leaves pins unconnected without an ERC error in some tools.","tags":[],"severity":"major"},{"id":"sch-net-4","text":"Signal direction (TX/RX, MOSI/MISO, CTS/RTS) is correct across every interface","hint":"Crossovers are a frequent first-build fault; label nets from the controller's point of view.","tags":[],"severity":"major"},{"id":"sch-net-5","text":"Netlist has been compared against the previous revision and every difference is intended","hint":"A netlist diff catches accidental edits that a visual review misses.","tags":[],"severity":"major"}]},{"id":"s-mcu","title":"Processor, MCU & FPGA","tags":[],"items":[{"id":"sch-mcu-1","text":"All processor supply pins, including analog, I/O-bank, core and backup domains, are connected per datasheet","hint":"Check against the datasheet pin table, not the symbol; some packages bond out extra supply pins.","tags":[],"severity":"critical"},{"id":"sch-mcu-2","text":"Boot-mode and configuration straps are set to the intended state","hint":"Consider leaving a way to override straps for development (jumper or test pad). Check strap pins that double as GPIOs are not pulled the wrong way by external loads at reset.","tags":[],"severity":"critical"},{"id":"sch-mcu-3","text":"Pin multiplexing is validated in the vendor pin tool, with no function conflicts","hint":"Export the pin assignment from the vendor tool and compare against the schematic net names.","tags":[],"severity":"critical"},{"id":"sch-mcu-4","text":"Peripheral pin choices respect alternate-function, timer and ADC-channel limits","hint":"Check that ADC inputs are on ADC-capable pins, PWM outputs on suitable timer channels and that 5 V-tolerant pins are used where needed.","tags":[],"severity":"major"},{"id":"sch-mcu-5","text":"Internal regulator pins (VCAP, VDDCORE etc.) have the capacitor value and type the datasheet specifies","hint":"Missing or wrong core regulator capacitors are a common cause of a board that will not start.","tags":[],"severity":"major"},{"id":"sch-mcu-6","text":"GPIO current per pin and per port is within datasheet limits","hint":"Directly driven LEDs, buzzers and relays can exceed total port current.","tags":[],"severity":"major"},{"id":"sch-mcu-7","text":"Pins that are high-impedance or toggling during reset do not cause unwanted actions on driven loads","hint":"Motor enables, heaters, relays and power switches need a defined safe state via pull resistors until firmware takes control.","tags":[],"severity":"major"},{"id":"sch-mcu-8","text":"External memory (flash, EEPROM) interface, voltage and boot source are compatible with the processor","hint":"Check boot ROM support for the chosen flash type, interface width and voltage.","tags":[],"severity":"major"},{"id":"sch-mcu-9","text":"FPGA configuration mode, configuration memory and done/init signals are connected per vendor guidance","hint":"Check mode pins, config memory size for the bitstream, and pull-ups on open-drain config signals.","tags":["fpga"],"severity":"major"},{"id":"sch-mcu-10","text":"FPGA I/O-bank voltages match the I/O standards assigned to each bank","hint":"Run the vendor pin planner with I/O standards set and check its report.","tags":["fpga"],"severity":"major"},{"id":"sch-mcu-11","text":"DDR memory interface pinout, termination and reference voltage follow the controller vendor's guidelines","hint":"Byte-lane swaps and bit swaps must follow the controller's rules; check VTT and VREF supplies.","tags":["ddr"],"severity":"critical"}]},{"id":"s-clk","title":"Clocks, Reset & Power Sequencing","tags":[],"items":[{"id":"sd4","text":"Clock sources and frequencies match MCU, FPGA and interface requirements","hint":"Check accuracy and jitter requirements of interfaces such as USB, Ethernet and radios, not just nominal frequency.","tags":[],"severity":"critical"},{"id":"sc7","text":"Crystal load capacitors are calculated from the crystal's specified load capacitance and stray capacitance","hint":"Use the crystal datasheet CL and an estimate of stray capacitance; check drive level and the oscillator's gain margin.","tags":[],"severity":"major"},{"id":"sd3","text":"Reset circuitry (supervisor IC or RC) is appropriate and reset polarity is correct","hint":"Check threshold relative to the minimum operating voltage of every part held in reset.","tags":[],"severity":"critical"},{"id":"sp7","text":"Power sequencing requirements are met (where applicable)","hint":"Check order, ramp time and maximum delay between rails against each datasheet, including power-down sequencing.","tags":[],"severity":"critical"},{"id":"sch-clk-1","text":"Clock fan-out, termination and drive strength suit each load","hint":"Check that one oscillator output is not driving too many loads or a long run without termination.","tags":[],"severity":"major"},{"id":"sch-clk-2","text":"Low-frequency (32.768 kHz) crystal is compatible with the oscillator's drive level and ESR limits","hint":"Low-power oscillators are very sensitive to crystal ESR and load capacitance; use the vendor's recommended crystal list.","tags":["low-power"],"severity":"major"},{"id":"sch-clk-3","text":"Reset is held until all supplies and clocks are stable","hint":"Check supervisor delay against the slowest rail and oscillator start-up time.","tags":[],"severity":"major"},{"id":"sch-clk-4","text":"Watchdog configuration (internal or external) is defined, including how it is disabled for debug","hint":"External watchdogs that cannot be disabled make debugging with breakpoints difficult.","tags":[],"severity":"major"},{"id":"sch-clk-5","text":"Enable and power-good chain implements the required sequence with no circular dependency","hint":"Trace each enable back to its source; a regulator enabled by a rail it powers will never start.","tags":[],"severity":"major"},{"id":"sch-clk-6","text":"Jitter budget for high-speed SerDes and data-converter clocks is met by the chosen reference","hint":"Compare the oscillator phase-noise or jitter spec with the SerDes or ADC requirement over the specified integration band.","tags":["high-speed","precision-analog","rf"],"severity":"major"}]},{"id":"s-ana","title":"Analog, Mixed-Signal & RF","tags":[],"items":[{"id":"sa1","text":"Op-amp feedback network values are verified for gain, bandwidth and stability","hint":"Check gain-bandwidth product against the closed-loop gain and signal bandwidth.","tags":[],"severity":"major"},{"id":"sa2","text":"Op-amp outputs do not drive an unsupported capacitive load directly","hint":"Use an isolation resistor or a part rated for the load; cable and ADC input capacitance count.","tags":[],"severity":"major"},{"id":"sa3","text":"ADC/DAC reference voltage source is stable and low-noise","hint":"Check reference accuracy, drift and its ability to supply the ADC's dynamic reference current.","tags":[],"severity":"major"},{"id":"sa4","text":"Anti-aliasing filters are present and correctly designed before ADC inputs","hint":"The filter should attenuate content above half the sample rate enough for the required accuracy.","tags":[],"severity":"major"},{"id":"sa6","text":"Sensitive analog signals are marked for separation from noisy digital and power circuits","hint":"Mark sensitive nets and add layout notes so they are kept away from switch nodes and clocks.","tags":[],"severity":"major"},{"id":"sch-ana-1","text":"Op-amp input and output common-mode ranges cover the actual signal swing on the chosen rails","hint":"Non rail-to-rail parts on single low supplies often clip near the rails.","tags":[],"severity":"major"},{"id":"sch-ana-2","text":"ADC driver can settle the ADC sampling capacitor within the acquisition time","hint":"Check the driver's bandwidth and the RC between driver and ADC per the ADC datasheet.","tags":[],"severity":"major"},{"id":"sch-ana-3","text":"Analog inputs are protected against overvoltage without degrading accuracy","hint":"Clamp diodes and series resistors add leakage and error; include them in the error budget.","tags":[],"severity":"major"},{"id":"sch-ana-4","text":"Error budget (offset, gain, noise, drift, resistor tolerance) meets the measurement accuracy requirement","hint":"A worst-case or RSS budget should exist for each precision measurement chain.","tags":["precision-analog"],"severity":"major"},{"id":"sch-ana-5","text":"Sensor excitation, bias and ratiometric referencing are defined","hint":"Ratiometric measurement removes reference error; check the excitation source and the ADC reference share a source where intended.","tags":["precision-analog"],"severity":"major"},{"id":"sch-ana-6","text":"Current-sense resistor and amplifier are sized for range, resolution and Kelvin connection","hint":"Mark the Kelvin sense connections on the schematic so layout does not share them with the current path.","tags":[],"severity":"major"},{"id":"sch-ana-7","text":"Audio path gain staging leaves headroom at every stage up to the codec or amplifier full-scale level","hint":"Check maximum signal at each stage against the supply and the codec full-scale level.","tags":["audio"],"severity":"major"},{"id":"sch-ana-8","text":"Audio outputs have DC blocking and pop/click suppression at power-up and power-down","hint":"Check coupling-capacitor charging behavior and the codec or amplifier mute sequence.","tags":["audio"],"severity":"major"},{"id":"sch-ana-9","text":"RF matching networks and antenna feed follow the radio vendor's reference design","hint":"Include tuning component placeholders (pi network) so the match can be adjusted after layout.","tags":["rf"],"severity":"major"},{"id":"sch-ana-10","text":"Radio module or RF IC supply decoupling and filtering follow the reference design","hint":"Radios are sensitive to supply ripple; check transmit current peaks against the regulator and bulk capacitance.","tags":["rf"],"severity":"major"}]},{"id":"s-dig","title":"Digital Interfaces & High-Speed","tags":[],"items":[{"id":"sd1","text":"Pull-up or pull-down resistors are present on all open-drain / open-collector outputs","hint":"Check interrupt, alert, fault and power-good lines as well as the obvious buses.","tags":[],"severity":"major"},{"id":"sd2","text":"Series termination resistors are included on high-speed lines where required","hint":"Typical candidates are clock lines, fast SPI and parallel buses with long runs.","tags":[],"severity":"major"},{"id":"sd5","text":"Logic voltage levels are compatible between every driver and receiver","hint":"Check VOH/VOL against VIH/VIL at the actual supply voltages, including 5 V-tolerance of inputs.","tags":[],"severity":"critical"},{"id":"sd6","text":"Level translators are included wherever mixed-voltage interfaces need them","hint":"Auto-direction translators misbehave with strong pull-ups or with push-pull and open-drain on the same line; check the part suits the bus.","tags":[],"severity":"major"},{"id":"sd8","text":"Each I2C bus has a single set of pull-ups sized for bus capacitance and speed","hint":"Pull-ups on modules and breakout boards add in parallel; size per the I2C specification's rise-time method.","tags":[],"severity":"major"},{"id":"sd9","text":"SPI chip-select lines are correctly connected with the right polarity and no shared-CS conflicts","hint":"Add pull-ups on chip selects so devices stay deselected while the controller is in reset.","tags":[],"severity":"major"},{"id":"sch-dig-1","text":"I2C addresses on each bus are unique, including address straps and module defaults","hint":"Make an address table per bus; address-select pins must not be left floating.","tags":[],"severity":"major"},{"id":"sch-dig-2","text":"USB data lines, VBUS sensing and CC/ID pins are connected per the USB connector type and role","hint":"USB-C needs CC resistors or a controller per its role; check VBUS detection and the ID or CC configuration.","tags":[],"severity":"major"},{"id":"sch-dig-3","text":"Ethernet PHY strapping, magnetics and termination follow the PHY reference design","hint":"Check center-tap connection (voltage-mode vs current-mode PHY) and the Bob Smith termination network.","tags":[],"severity":"major"},{"id":"sch-dig-4","text":"AC-coupling capacitors are present on high-speed serial links where the standard requires them, on the correct side","hint":"PCIe, SATA, DisplayPort and similar links specify which end the capacitors sit on.","tags":["high-speed"],"severity":"major"},{"id":"sch-dig-5","text":"High-speed differential pairs have impedance and length-matching requirements recorded for layout","hint":"Record target impedance and skew limits in schematic notes or net classes.","tags":["high-speed","ddr"],"severity":"major"},{"id":"sch-dig-6","text":"Polarity swaps and lane swaps on high-speed links are permitted by both ends","hint":"Some interfaces allow P/N inversion or lane reversal; others do not.","tags":["high-speed"],"severity":"major"},{"id":"sch-dig-7","text":"Display and touch interfaces (MIPI, LVDS, RGB, SPI) match the panel datasheet pinout and voltage","hint":"Check backlight driver current and voltage, panel power sequence and the FPC pinout orientation.","tags":["display"],"severity":"major"},{"id":"sch-dig-8","text":"Interrupt and wake-up lines are routed to wake-capable pins","hint":"Not all GPIOs can wake the processor from its deepest sleep mode.","tags":["low-power","battery"],"severity":"major"}]},{"id":"s-pro","title":"Protection, ESD & EMC","tags":[],"items":[{"id":"sp9","text":"ESD and transient protection is present at every external interface","hint":"List every connector, button and exposed conductive part and confirm each has protection.","tags":[],"severity":"critical"},{"id":"spr1","text":"Over-voltage protection is present on all external-facing inputs","hint":"Include miswiring to other supply voltages the product might plausibly see.","tags":[],"severity":"major"},{"id":"spr2","text":"Over-current protection (fuse, PTC or current limiter) is present on power inputs and outputs","hint":"Check the fuse rating against normal load, inrush I2t and the wiring or connector it protects.","tags":[],"severity":"major"},{"id":"spr3","text":"Reverse polarity protection is implemented where applicable","hint":"Check the protection device's loss at full load and its voltage rating.","tags":[],"severity":"major"},{"id":"spr4","text":"TVS and clamp diode ratings (working voltage, clamping voltage, capacitance) suit each protected signal","hint":"Working voltage must exceed the normal signal level; clamping voltage must be below the protected IC's limits; capacitance must suit high-speed lines.","tags":[],"severity":"major"},{"id":"spr5","text":"Chassis ground and protective earth connections are correctly handled for safety-critical designs","hint":"Check the earth bond path and how chassis is connected to circuit ground (direct, RC or isolated).","tags":[],"severity":"critical"},{"id":"sch-pro-1","text":"Outputs that drive off-board loads survive a short circuit to ground and to supply","hint":"Check output drivers, power outputs and sensor supplies for short-circuit protection.","tags":[],"severity":"major"},{"id":"sch-pro-2","text":"Common-mode chokes or filters are provided on cables that may radiate or receive interference","hint":"Consider footprints for EMC fixes even if fitted as 0 ohm initially.","tags":["regulatory"],"severity":"major"},{"id":"sch-pro-3","text":"Input power filtering meets conducted-emissions targets for switching converters","hint":"Plan for an input pi filter with damping; include footprints for tuning during pre-compliance.","tags":["regulatory"],"severity":"major"},{"id":"sch-pro-4","text":"Automotive supply inputs withstand load dump, reverse battery and transient pulses for the required standard","hint":"Check the protection against the transient levels in the applicable automotive standard (ISO 7637 / ISO 16750 style).","tags":["automotive"],"severity":"critical"},{"id":"sch-pro-5","text":"Surge and EFT protection on long-cable industrial interfaces is rated for the required immunity levels","hint":"Industrial I/O, RS-485 and 24 V inputs typically need surge-rated TVS and series impedance.","tags":["harsh-env"],"severity":"major"},{"id":"sch-pro-6","text":"Inductive loads have flyback or clamp protection","hint":"Relays, solenoids and long cables need a clamp; check its effect on release time.","tags":[],"severity":"major"}]},{"id":"s-bat","title":"Battery & Charging","tags":["battery"],"items":[{"id":"sch-bat-1","text":"Battery protection (over-charge, over-discharge, over-current, short circuit) is provided in the pack or on the board","hint":"Confirm which protections the pack provides and which the board must add; do not assume.","tags":[],"severity":"critical"},{"id":"sch-bat-2","text":"Charge voltage and current settings match the cell chemistry and manufacturer limits","hint":"Check the charge termination voltage, charge current and pre-charge current against the cell datasheet.","tags":[],"severity":"critical"},{"id":"sch-bat-3","text":"Charging is inhibited outside the cell's allowed temperature range","hint":"Check the thermistor type and the charger's temperature thresholds match the cell datasheet.","tags":[],"severity":"critical"},{"id":"sch-bat-4","text":"Battery connector is keyed and polarity-protected against incorrect insertion","hint":"Consider what happens if a user forces a reversed connector or a wrong pack.","tags":[],"severity":"major"},{"id":"sch-bat-5","text":"Fuel gauging or voltage monitoring is accurate enough for the state-of-charge requirement","hint":"Voltage-only estimates are poor for flat discharge curves; consider a fuel gauge IC.","tags":[],"severity":"major"},{"id":"sch-bat-6","text":"Deep-discharge and shelf-life behavior (ship mode, leakage) is defined","hint":"Leakage through dividers and always-on parts can flatten a battery in storage; consider ship mode.","tags":[],"severity":"major"},{"id":"sch-bat-7","text":"Load sharing / power-path handles a dead or missing battery while external power is present","hint":"Check the system can boot from external power with a deeply discharged battery.","tags":[],"severity":"major"},{"id":"sch-bat-8","text":"Coin cell or backup battery circuits prevent reverse charging of primary cells","hint":"Primary lithium cells must not be charged; check diode or series resistor protection per cell datasheet.","tags":[],"severity":"major"}]},{"id":"s-mot","title":"Motor & Power Stages","tags":["motor","high-current"],"items":[{"id":"sch-mot-1","text":"Power MOSFETs / IGBTs have voltage, current and SOA margin for the worst-case operating point","hint":"Check SOA for linear operation during switching, start-up and fault conditions.","tags":[],"severity":"critical"},{"id":"sch-mot-2","text":"Gate drive voltage, current and gate resistors suit the switches and the target switching speed","hint":"Check gate charge against driver capability and the bootstrap supply capacity at low duty cycle.","tags":[],"severity":"major"},{"id":"sch-mot-3","text":"Dead time and shoot-through protection are defined for half-bridges","hint":"Set dead time in hardware or document the firmware requirement and the driver's minimum.","tags":[],"severity":"critical"},{"id":"sch-mot-4","text":"Regenerative energy from motor braking is handled (clamp, brake resistor, or supply absorption)","hint":"Regeneration can pump the DC bus above component ratings, especially when the supply cannot sink current.","tags":["motor"],"severity":"major"},{"id":"sch-mot-5","text":"Motor current sensing covers the full range with adequate bandwidth for control and protection","hint":"Check amplifier common-mode range for high-side or in-phase sensing and blanking at switching edges.","tags":[],"severity":"major"},{"id":"sch-mot-6","text":"Hardware over-current or short-circuit shutdown responds faster than the switch can be damaged","hint":"Firmware-only protection is usually too slow for a shorted output.","tags":[],"severity":"critical"},{"id":"sch-mot-7","text":"DC-bus capacitance and ripple-current rating are adequate for the switching current","hint":"Check capacitor RMS ripple current at maximum load and temperature.","tags":[],"severity":"major"},{"id":"sch-mot-8","text":"Snubbers or clamps limit switching overshoot to within device ratings","hint":"Leave footprints for RC snubbers if the layout parasitics are not yet known.","tags":[],"severity":"major"},{"id":"sch-mot-9","text":"Motor outputs are in a safe state at power-up, reset and fault","hint":"Driver enables should be pulled to the disabled state independently of firmware.","tags":["motor"],"severity":"major"},{"id":"sch-mot-10","text":"Encoder, Hall and position-sensor inputs have filtering and protection suitable for motor noise","hint":"Motor cables carry large common-mode noise; check pull-ups, filtering and ESD on sensor inputs.","tags":["motor"],"severity":"major"}]},{"id":"s-iso","title":"Mains, Isolation & Safety","tags":["mains","medical"],"items":[{"id":"sch-iso-1","text":"Insulation class and isolation barriers are identified on the schematic","hint":"Mark the primary/secondary boundary and the required insulation level (basic, supplementary, reinforced) on each barrier.","tags":[],"severity":"critical"},{"id":"sch-iso-2","text":"Parts bridging the isolation barrier (transformers, optocouplers, Y-capacitors, isolators) carry the required safety ratings","hint":"Check each part's certification and rated insulation voltage against the applicable safety standard.","tags":[],"severity":"critical"},{"id":"sch-iso-3","text":"Creepage and clearance requirements are recorded for layout per the applicable safety standard","hint":"Write the required distances into layout notes or rules; the schematic is where the requirement originates.","tags":[],"severity":"critical"},{"id":"sch-iso-4","text":"Mains input has a correctly rated fuse in the line conductor","hint":"Check breaking capacity and voltage rating as well as current; position per the safety standard.","tags":["mains"],"severity":"critical"},{"id":"sch-iso-5","text":"Mains input has surge protection (MOV or similar) rated for the product's mains range","hint":"Check MOV rating for the highest mains voltage and its failure mode protection.","tags":["mains"],"severity":"major"},{"id":"sch-iso-6","text":"Mains inrush current is limited to suit the fuse, switch and upstream supply","hint":"Use an NTC, active inrush limiter or the converter's soft-start; check behavior on a hot restart when an NTC is still warm.","tags":["mains"],"severity":"major"},{"id":"sch-iso-7","text":"X and Y capacitors are safety-rated parts of the correct class","hint":"Check the X/Y subclass and certification marks against the position and working voltage.","tags":[],"severity":"major"},{"id":"sch-iso-8","text":"Total Y-capacitance and other leakage paths keep touch and patient leakage current within the allowed limit","hint":"Leakage limits for medical equipment are much stricter than for IT equipment; calculate at maximum mains voltage and frequency.","tags":[],"severity":"critical"},{"id":"sch-iso-9","text":"Bleed resistors discharge X capacitors and high-voltage bulk capacitors to a safe level in the required time","hint":"Check the resistor voltage rating; use series resistors to share voltage.","tags":[],"severity":"major"},{"id":"sch-iso-10","text":"Medical applied parts have the required means of patient protection and isolation","hint":"Confirm the applied-part classification and the number of means of protection with the regulatory lead.","tags":["medical"],"severity":"critical"},{"id":"sch-iso-11","text":"Single-fault conditions have been considered for safety-critical circuits","hint":"Short or open each critical component in turn and confirm the product remains safe.","tags":[],"severity":"major"}]},{"id":"s-therm","title":"Thermal","tags":[],"items":[{"id":"sch-therm-1","text":"Power dissipation is estimated for every significant part at worst-case load and ambient","hint":"List each part over a few hundred milliwatts with its estimated junction temperature (rule of thumb threshold; adjust per project).","tags":[],"severity":"major"},{"id":"sch-therm-2","text":"Parts relying on copper area or heatsinks have thermal requirements noted for layout","hint":"Note the required copper area, thermal vias or heatsink so the assumption survives into layout.","tags":[],"severity":"major"},{"id":"sch-therm-3","text":"Thermal shutdown or temperature monitoring is provided where overheating is possible","hint":"A thermistor or temperature sensor near hot parts allows firmware derating.","tags":["high-current","motor","battery"],"severity":"major"},{"id":"sch-therm-4","text":"Temperature-sensitive parts (references, crystals, sensors, electrolytics) are noted to be kept away from heat sources","hint":"Add placement notes so layout keeps them away from regulators and power stages.","tags":[],"severity":"minor"},{"id":"sch-therm-5","text":"Touch-temperature limits for accessible surfaces are considered in the dissipation budget","hint":"Enclosure surface temperature can limit allowable dissipation more than component ratings.","tags":[],"severity":"major"}]},{"id":"s-fab","title":"Design for Test, Debug & Manufacture","tags":[],"items":[{"id":"sf1","text":"Test points are provided on all critical nets (power rails, key signals)","hint":"Include every rail, reset, clocks, boot straps and key communication buses.","tags":[],"severity":"major"},{"id":"sd7","text":"JTAG / SWD / debug header is present with the correct pinout","hint":"Check against the debug probe's pinout, including reference voltage and reset pins.","tags":[],"severity":"critical"},{"id":"sf2","text":"Reference designators are unique and follow the naming convention","hint":"Re-annotation after copy-paste often creates gaps or duplicates.","tags":[],"severity":"minor"},{"id":"sf3","text":"BOM is generated and cross-checked against the schematic","hint":"Check quantities, DNP fields and manufacturer part numbers against the schematic values.","tags":[],"severity":"major"},{"id":"sf4","text":"Footprint assignments are reviewed for every component - correct package selected","hint":"Check package variants of the same part number (e.g. QFN vs SOIC) and pin-1 orientation.","tags":[],"severity":"critical"},{"id":"sf5","text":"Board-level notes and assembly instructions are included on the schematic","hint":"Include special processes such as selective solder, conformal coat masks or press-fit parts.","tags":[],"severity":"minor"},{"id":"sf6","text":"Schematic PDF and netlist are exported at the final revision, with file names reflecting the revision","hint":"Check the PDF is searchable and the revision in the file name matches the title block.","tags":[],"severity":"minor"},{"id":"sch-fab-1","text":"Programming and debug access works in production as well as development","hint":"Production programming may use pogo pins or a fixture rather than a header; check the access plan.","tags":["production"],"severity":"major"},{"id":"sch-fab-2","text":"A debug UART or log output is available","hint":"A spare UART on test pads is invaluable during bring-up and field returns.","tags":[],"severity":"minor"},{"id":"sch-fab-3","text":"Power rails can be isolated for bring-up (0 ohm links, jumpers or current-measure points)","hint":"Being able to bring up rails one at a time and measure current saves boards during first power-on.","tags":[],"severity":"major"},{"id":"sch-fab-4","text":"Production test coverage is defined and test access exists for each tested function","hint":"Agree the test strategy (ICT, flying probe, functional test) with the manufacturer.","tags":["production"],"severity":"major"},{"id":"sch-fab-5","text":"Unique serialization, calibration storage and MAC/ID provisioning are planned","hint":"Decide where calibration constants and unique IDs live and how production writes them.","tags":["production"],"severity":"major"}]},{"id":"s-life","title":"Lifecycle & Sourcing","tags":[],"items":[{"id":"sc5","text":"All components are from the approved vendor list or justified exceptions are documented","hint":"New vendors need a quality and supply review before production.","tags":[],"severity":"major"},{"id":"sc6","text":"Obsolete or end-of-life parts are flagged and replaced","hint":"Check lifecycle status with the distributor or a lifecycle tool, including NRND (not recommended for new design) status.","tags":[],"severity":"major"},{"id":"sch-life-1","text":"Single-source parts are identified and have a mitigation plan or approved alternative","hint":"List alternates for passives and common parts; flag single-source ICs to the project lead.","tags":[],"severity":"major"},{"id":"sch-life-2","text":"Stock and lead time are checked for every part needed for the next build","hint":"Check availability at the build quantity, not just whether one is in stock.","tags":[],"severity":"major"},{"id":"sch-life-3","text":"Environmental compliance (RoHS, REACH and any customer-specific substance lists) is confirmed for all parts","hint":"Check part compliance data, not just the family claim.","tags":["production","regulatory"],"severity":"major"},{"id":"sch-life-4","text":"Parts with moisture sensitivity or special handling are identified for the assembler","hint":"MSL ratings and special handling notes help prevent assembly defects.","tags":["production"],"severity":"major"}]}]},{"id":"interfaces","title":"Interface Review","short":"Interfaces","version":2,"description":"Per-interface checks for the board's buses and I/O; the reviewer marks whole sections N/A for interfaces the board does not use.","sections":[{"id":"if-adc","title":"ADC (Analog-to-Digital Converter)","tags":[],"items":[{"id":"adc1","text":"Differential input voltage is within the PGA gain range for all expected signals","hint":"Check the worst-case signal including offsets and overrange at the chosen gain; clipping at the PGA output is silent in firmware.","tags":[],"severity":"major"},{"id":"adc2","text":"Common-mode voltage at the PGA inputs is within the specified input common-mode range","hint":"Many PGAs restrict common-mode range at high gain. Check against the datasheet's CM-vs-gain plot, not just the supply rails.","tags":[],"severity":"critical"},{"id":"adc3","text":"Ratiometric measurement is used where appropriate (reference derived from the excitation voltage)","hint":"Bridges, potentiometers and RTDs cancel excitation drift when the ADC reference tracks the excitation.","tags":[],"severity":"major"},{"id":"adc4","text":"Thermocouple inputs: cold-junction compensation sensor is placed close to the connector junction","hint":"The CJC sensor must be isothermal with the point where thermocouple wire meets copper. Keep heat sources away from that area.","tags":["precision-analog"],"severity":"major"},{"id":"adc5","text":"RTD / bridge excitation current source value and direction are verified","hint":"Confirm the compliance voltage is not exceeded at maximum sensor resistance and that self-heating is acceptable.","tags":["precision-analog"],"severity":"major"},{"id":"adc6","text":"Anti-aliasing filter cutoff is well below Nyquist for the chosen sample rate","hint":"Check the attenuation reached at Fs/2, not just the -3 dB point. Delta-sigma ADCs relax this but still alias around multiples of the modulator rate.","tags":[],"severity":"major"},{"id":"adc7","text":"ADC input impedance is high enough relative to source impedance, or a buffer is added","hint":"For SAR ADCs, check the sample-capacitor kickback and acquisition time against the source resistance plus the RC filter, per datasheet.","tags":[],"severity":"major"},{"id":"adc8","text":"Reference voltage source meets the stability and noise budget for the required accuracy","hint":"Compare reference tempco, initial accuracy and noise against the error budget. An internal MCU reference is often the limiting factor.","tags":[],"severity":"major"},{"id":"ifc-adc-1","text":"Reference pin is decoupled with the capacitance and placement the datasheet specifies","hint":"Some references go unstable with the wrong capacitor value or ESR. Place the reference cap at the pin, not at the regulator.","tags":[],"severity":"major"},{"id":"adc9","text":"Input overvoltage protection / clamping is present on all ADC inputs that can see out-of-range voltages","hint":"Use series resistance plus clamps to the rails or TVS. Check that clamp leakage does not create an error at the input impedance used.","tags":[],"severity":"critical"},{"id":"adc10","text":"Input mux settling time is budgeted when multiplexed channels are used","hint":"Switching between channels at very different voltages needs settling time for the RC filter and the sample capacitor.","tags":[],"severity":"major"},{"id":"adc11","text":"Grounding scheme near the ADC follows the datasheet (typically a solid ground with AGND/DGND joined at the converter)","hint":"Most modern guidance is one unbroken ground plane with careful partitioning, rather than split planes. Confirm digital return currents do not cross the analog area.","tags":[],"severity":"major"}]},{"id":"if-dac","title":"DAC (Digital-to-Analog Converter)","tags":[],"items":[{"id":"dac1","text":"Output voltage range covers the required span for the load","hint":"Include headroom for the output buffer swing near the rails.","tags":[],"severity":"major"},{"id":"dac2","text":"DAC output buffer / op-amp drive capability is verified for the load impedance","hint":"Check current drive and stability with the load capacitance, including cable capacitance if the output leaves the board.","tags":[],"severity":"major"},{"id":"dac3","text":"Reference voltage accuracy and noise meet the output accuracy requirement","hint":"Reference error passes straight to the output. Check its initial accuracy, tempco and noise against the error budget.","tags":[],"severity":"major"},{"id":"dac4","text":"Output reconstruction filter is present where the application needs it and its cutoff is correct","hint":"Required for waveform / audio generation; usually unnecessary for slow setpoint DACs.","tags":[],"severity":"major"},{"id":"dac5","text":"Settling time meets the system update-rate requirement","hint":"Use full-scale step settling to the required accuracy, including any buffer and filter.","tags":[],"severity":"major"},{"id":"dac6","text":"DAC output short-circuit / overload protection is considered for outputs that leave the board","hint":"Series resistance or a protected buffer prevents damage when an external output is shorted.","tags":[],"severity":"major"},{"id":"ifc-dac-1","text":"DAC output state at power-up and reset is safe for the driven load","hint":"Many DACs power up at zero-scale or mid-scale. Check what the load does before firmware writes the first code.","tags":[],"severity":"major"}]},{"id":"if-uart","title":"UART / USART","tags":[],"items":[{"id":"uart1","text":"Baud rate, stop bits and parity match between both ends of the link","hint":"Also check that the clock source gives an acceptable baud-rate error, per the MCU datasheet.","tags":[],"severity":"major"},{"id":"uart2","text":"Logic levels are compatible at both ends, with level translation where supply voltages differ","hint":"A 5 V TX into a non-5 V-tolerant 3.3 V RX can back-power or damage the receiver.","tags":[],"severity":"critical"},{"id":"uart3","text":"RS-232: a transceiver is present and its supply arrangement is per datasheet","hint":"Modern RS-232 transceivers generate their own bipolar levels with a charge pump; check the pump capacitor values. See also the RS-232 / RS-485 / RS-422 section.","tags":[],"severity":"major"},{"id":"uart4","text":"RS-485: termination (typically 120 Ω) is fitted at each physical cable end only","hint":"Intermediate nodes must not terminate. See the RS-232 / RS-485 / RS-422 section for further checks.","tags":[],"severity":"critical"},{"id":"ifc-uart-1","text":"RS-485: failsafe biasing holds the bus in a defined idle state","hint":"Either bias resistors at one node or a transceiver with built-in failsafe. Check the bias still meets the receiver threshold with both terminations fitted.","tags":[],"severity":"major"},{"id":"uart5","text":"RS-485: half-duplex DE/RE control is verified so no bus contention is possible","hint":"Check DE timing releases after the last stop bit and the default state at MCU reset is receive.","tags":[],"severity":"critical"},{"id":"uart6","text":"Flow control (RTS/CTS) is wired if the data rate or latency requires it","hint":"Without flow control, the receiver must empty its FIFO fast enough at the worst-case interrupt latency.","tags":[],"severity":"minor"},{"id":"uart7","text":"ESD protection is fitted on connector pins of externally routed UART lines","hint":"Choose a TVS whose working voltage clears the signal swing. RS-232 levels need a higher-voltage part than logic-level UART.","tags":[],"severity":"major"},{"id":"ifc-uart-2","text":"No back-powering occurs through UART lines when one side is unpowered","hint":"A driven TX into an unpowered device's RX can power it through ESD diodes. Use series resistors, power-off-tolerant buffers or sequencing.","tags":[],"severity":"major"},{"id":"ifc-uart-3","text":"TX/RX crossover at the connector is documented and matches the cable / mating device","hint":"TX-to-TX swaps are among the most common respins; label the net names from the MCU's perspective.","tags":[],"severity":"minor"}]},{"id":"if-spi","title":"SPI","tags":[],"items":[{"id":"spi1","text":"CPOL and CPHA mode is supported by every device on the bus","hint":"Devices that support different modes on a shared bus force a mode change per transaction. Confirm the firmware handles it.","tags":[],"severity":"critical"},{"id":"spi2","text":"CS polarity and setup / hold timing are verified against each device datasheet","hint":"Some devices need CS toggled between words or a minimum CS-high time between transactions.","tags":[],"severity":"major"},{"id":"spi3","text":"Each device has its own dedicated CS line with no shared-CS conflicts","hint":"Two devices sharing a CS will contend on MISO. Daisy-chain only where the devices explicitly support it.","tags":[],"severity":"critical"},{"id":"spi4","text":"Maximum SPI clock does not exceed any device's rated limit","hint":"Include the round-trip delay (clock out, data back) for reads at high clock rates.","tags":[],"severity":"major"},{"id":"spi5","text":"Every device tri-states MISO when its CS is de-asserted","hint":"Some devices (and some ADCs) keep driving MISO; they need a buffer or a separate bus.","tags":[],"severity":"critical"},{"id":"spi6","text":"Series source-termination resistors are fitted on long or fast SPI traces to limit ringing","hint":"Place them at the driver: on SCK/MOSI at the controller, on MISO at each peripheral.","tags":[],"severity":"minor"},{"id":"ifc-spi-1","text":"CS lines have pull-ups so devices stay deselected while the MCU is in reset or unprogrammed","hint":"A floating CS during boot can let a device clock in noise or drive MISO against another device.","tags":[],"severity":"major"}]},{"id":"if-i2c","title":"I2C","tags":[],"items":[{"id":"i2c1","text":"Pull-up resistor values suit the bus capacitance and clock speed (100 kHz / 400 kHz / 1 MHz)","hint":"Check rise time against the I2C specification limit for the mode and the sink-current limit at the lowest value.","tags":[],"severity":"major"},{"id":"i2c2","text":"Pull-ups are not duplicated across modules or breakout boards in parallel","hint":"When each module adds its own pull-ups, the effective resistance drops and can exceed the sink-current limit.","tags":[],"severity":"major"},{"id":"i2c3","text":"All device addresses on each bus are unique","hint":"Include reserved addresses and any devices that respond to several addresses.","tags":[],"severity":"critical"},{"id":"i2c4","text":"Address configuration pins are tied to defined levels, not floating","hint":"A floating address pin can read differently between units or across temperature.","tags":[],"severity":"major"},{"id":"i2c5","text":"Bus capacitance is within budget for the cable / trace length and number of devices","hint":"Long cables or many devices may need a bus buffer or a slower mode.","tags":[],"severity":"major"},{"id":"i2c6","text":"Level shifting is used where devices on the bus run at different supply voltages","hint":"Use a dedicated I2C level translator or a MOSFET-based shifter. Generic push-pull translators break the open-drain bus.","tags":[],"severity":"critical"},{"id":"i2c7","text":"A bus-lockup recovery mechanism exists (GPIO to toggle SCL, or a device / bus reset)","hint":"A device reset mid-transfer can hold SDA low. Firmware recovery clocks SCL until SDA is released.","tags":[],"severity":"major"},{"id":"ifc-i2c-1","text":"No device holds the bus low when it is unpowered while the rest of the bus is powered","hint":"Devices without power-off-tolerant I/O clamp SDA/SCL through ESD diodes and kill the bus. Check this for every switched rail.","tags":[],"severity":"major"},{"id":"ifc-i2c-2","text":"Externally routed I2C (off-board cable) has ESD protection and is within its capacitance budget","hint":"I2C is not designed for long cables. Consider a differential extender or a buffer for cable runs.","tags":[],"severity":"major"}]},{"id":"if-i2s","title":"I2S / PCM Audio","tags":["audio"],"items":[{"id":"i2s1","text":"Clock roles are assigned so exactly one device drives BCLK and LRCK","hint":"With two masters the clock lines contend. With no master the codec stays silent.","tags":[],"severity":"critical"},{"id":"i2s2","text":"BCLK frequency equals sample rate × slot width × number of slots, as verified by calculation","hint":"Slot width is not always the sample bit depth: 24-bit data in 32-bit slots is common.","tags":[],"severity":"major"},{"id":"i2s3","text":"Word-select (WS/LRCK) polarity matches both devices","hint":"A swapped WS polarity swaps the left and right channels, which is easy to miss in mono testing.","tags":[],"severity":"major"},{"id":"i2s4","text":"Data format matches at both ends (I2S, left-justified, right-justified or TDM)","hint":"A one-bit offset between I2S and left-justified formats halves the amplitude or adds distortion.","tags":[],"severity":"major"},{"id":"i2s5","text":"MCLK is provided if the codec requires it and its ratio to the sample rate is supported (e.g. 256 × Fs)","hint":"Check the codec's supported MCLK/Fs ratios for every sample rate the product uses.","tags":[],"severity":"major"},{"id":"i2s6","text":"Codec power-up and mute sequencing avoids audible pops","hint":"Mute the amplifier until the codec reference has settled, and reverse the order at power-down.","tags":[],"severity":"major"},{"id":"i2s7","text":"Series termination resistors are fitted on long I2S traces to reduce ringing","hint":"Place the resistor at the driver end of each clock line.","tags":[],"severity":"minor"}]},{"id":"if-usb","title":"USB","tags":[],"items":[{"id":"usb1","text":"D+ and D− are routed as a length-matched differential pair at 90 Ω differential impedance","hint":"Matters most at High Speed; Full Speed is tolerant. Use the fab's stack-up to set trace geometry.","tags":[],"severity":"major"},{"id":"usb2","text":"A low-capacitance ESD protection device is fitted on D+ and D− at the connector","hint":"Choose a part rated for USB data lines (e.g. PRTR5V0U2X class); capacitance limits are tighter at High Speed.","tags":[],"severity":"major"},{"id":"usb3","text":"Pull-up / pull-down on D+ or D− is correct for USB speed and role (host / device / OTG)","hint":"Many MCUs have integrated pull-ups; an extra external one will break enumeration.","tags":[],"severity":"critical"},{"id":"usb4","text":"VBUS has bulk and local decoupling within the limits allowed by the USB specification","hint":"Device-side VBUS capacitance is limited to control inrush; a host port needs enough bulk to ride through hot-plug events.","tags":[],"severity":"major"},{"id":"ifc-usb-1","text":"Host / source ports have VBUS current limiting (load switch or polyfuse)","hint":"Protects the system rail from a shorted cable or a faulty device.","tags":[],"severity":"critical"},{"id":"usb5","text":"USB-C CC pins have the correct termination for the role (Rd 5.1 kΩ to GND for sink, Rp for source) or a CC / PD controller for DRP","hint":"Each CC pin needs its own resistor; sharing one resistor between CC1 and CC2 is a classic failure with e-marked cables.","tags":[],"severity":"critical"},{"id":"usb6","text":"Ground reference plane is unbroken beneath the USB differential pair","hint":"A split or slot under the pair breaks the return path, causing reflections and radiated emissions.","tags":[],"severity":"major"},{"id":"usb7","text":"Connector shield is connected to chassis / GND according to the product's shielding strategy","hint":"Options include a direct bond, an RC network (e.g. a resistor and capacitor in parallel) or a ferrite. Choose deliberately for EMC and ESD.","tags":[],"severity":"major"},{"id":"usb8","text":"Clock source meets the USB clock tolerance for the chosen speed, per the USB spec and MCU datasheet","hint":"Crystal-less operation is only valid where the MCU supports clock recovery from SOF packets.","tags":[],"severity":"critical"},{"id":"ifc-usb-2","text":"Device VBUS sensing exists where required and is divided / protected to suit the MCU pin","hint":"Self-powered devices must not drive D+ pull-up without VBUS present. VBUS pins can see transients above 5 V.","tags":[],"severity":"critical"},{"id":"ifc-usb-3","text":"USB PD: the controller's policy (voltages, currents, dead-battery behavior) is defined and its strapping / firmware matches","hint":"Dead-battery operation needs the sink to present Rd with no firmware running. Check that the controller supports it.","tags":[],"severity":"major"},{"id":"ifc-usb-4","text":"USB-C SuperSpeed or alternate-mode lanes have the required AC-coupling capacitors and mux / orientation handling","hint":"Check capacitor placement and value per the USB spec and the redriver / mux datasheet.","tags":["high-speed"],"severity":"major"},{"id":"ifc-usb-5","text":"Suspend current of the bus-powered device is within the USB specification limit","hint":"Count all leakage paths, LEDs and regulators that stay on in suspend.","tags":["low-power"],"severity":"major"}]},{"id":"if-disp","title":"Display Interfaces (MIPI / LVDS / RGB)","tags":["display"],"items":[{"id":"disp1","text":"MIPI DSI lane count and data rate match the display module specification","hint":"Also check the processor's DSI host supports the panel's video or command mode.","tags":[],"severity":"critical"},{"id":"disp2","text":"MIPI DSI differential pairs are routed at the specified impedance (typically 100 Ω differential)","hint":"Set the trace geometry from the fab's stack-up and keep each pair on one reference plane.","tags":[],"severity":"major"},{"id":"disp3","text":"LVDS pairs are length-matched within each pair and between pairs to meet the skew budget","hint":"Take the skew limit from the LVDS transmitter and panel datasheets.","tags":[],"severity":"major"},{"id":"disp4","text":"Parallel RGB: data, HSYNC, VSYNC and DE are length-matched to PCLK within the timing budget","hint":"Check setup and hold at the panel against the PCLK edge polarity.","tags":[],"severity":"major"},{"id":"disp5","text":"Display power sequencing (e.g. VDDIO → VDD → backlight) matches the panel datasheet","hint":"Wrong sequencing can latch up the panel driver IC or show visible artifacts at power-on.","tags":[],"severity":"critical"},{"id":"disp6","text":"Backlight PWM dimming frequency avoids visible flicker","hint":"Rule of thumb: keep it well above a few hundred hertz, and outside the audio band if the inductor or ceramic caps could sing.","tags":[],"severity":"minor"},{"id":"disp7","text":"Touch controller bus and interrupt lines are routed with the pull-ups they need","hint":"See the Touch section for further checks.","tags":[],"severity":"major"},{"id":"disp8","text":"ESD protection is fitted on display connector lines that are user-accessible","hint":"Keep the ESD device capacitance low enough for the interface speed.","tags":[],"severity":"major"},{"id":"ifc-disp-1","text":"FPC connector pin-1 orientation, pitch and contact side (top / bottom) match the panel tail","hint":"A mirrored FPC pinout is a very common respin; check against the panel drawing, not just the netlist.","tags":[],"severity":"major"},{"id":"ifc-disp-2","text":"Backlight driver has open-LED overvoltage protection","hint":"If the LED string opens, a boost driver without OVP can exceed its output capacitor and switch ratings.","tags":[],"severity":"major"}]},{"id":"if-tmr","title":"Timers & PWM","tags":[],"items":[{"id":"tmr1","text":"Complementary timer outputs have dead time configured to prevent shoot-through","hint":"Size the dead time from the gate driver and FET switching times, with margin over temperature. See also the Motor Driver Interfaces section.","tags":[],"severity":"critical"},{"id":"tmr2","text":"Break input (BRK/BRK2) fault wiring is verified for polarity and source","hint":"The break input should disable the outputs in hardware without needing firmware.","tags":[],"severity":"critical"},{"id":"tmr3","text":"PWM frequency and resolution meet the application requirement (motor, LED, etc.)","hint":"Check the timer clock gives the required resolution at the chosen PWM frequency.","tags":[],"severity":"major"},{"id":"tmr4","text":"Capture / compare input filters are configured for noise immunity","hint":"Digital input filters reject short glitches on noisy encoder or capture lines.","tags":[],"severity":"minor"},{"id":"tmr5","text":"Encoder interface quadrature inputs and index pulse are wired to timer-capable pins","hint":"Both quadrature channels must land on the same timer's encoder-capable inputs.","tags":[],"severity":"major"},{"id":"tmr6","text":"Timer clock source and prescaler values give the required resolution and range","hint":"Confirm low-power modes or clock-tree changes in firmware do not alter the timer clock unexpectedly.","tags":[],"severity":"major"}]},{"id":"if-can","title":"CAN Bus","tags":[],"items":[{"id":"can1","text":"Termination (typically 120 Ω) is present at each physical end of the bus only","hint":"With power off and both ends fitted, CANH to CANL should measure about half the termination value.","tags":[],"severity":"critical"},{"id":"can2","text":"A CAN transceiver sits between the controller TX/RX and the bus CANH/CANL","hint":"Check the transceiver matches the bus type (high-speed CAN, CAN FD or fault-tolerant).","tags":[],"severity":"critical"},{"id":"can3","text":"Bit rate and sample-point configuration are consistent across all nodes","hint":"A sample-point mismatch between nodes causes errors on long buses even when the bit rates match.","tags":[],"severity":"critical"},{"id":"can4","text":"Split termination (two half-value resistors with a center-tap capacitor) is used where noise is a concern","hint":"The center-tap capacitor to ground filters common-mode noise.","tags":[],"severity":"minor"},{"id":"can5","text":"A common-mode choke is fitted on CANH/CANL for EMC-sensitive designs","hint":"Some chokes can ring with the bus under fault conditions. Follow the transceiver vendor's recommendation.","tags":[],"severity":"minor"},{"id":"can6","text":"ESD / surge protection (TVS) rated for CAN is fitted on CANH and CANL at exposed connectors","hint":"Use a low-capacitance TVS rated for the CAN bus voltage range.","tags":[],"severity":"major"},{"id":"ifc-can-1","text":"Transceiver supports the required data rate (classic CAN or CAN FD) and loop delay","hint":"Not every transceiver is rated for CAN FD data-phase bit rates.","tags":[],"severity":"major"},{"id":"ifc-can-2","text":"Transceiver standby / silent pin has a defined state during MCU reset","hint":"A floating standby pin can leave the transceiver disabled, or let it disturb the bus during boot.","tags":[],"severity":"major"},{"id":"ifc-can-3","text":"Ground reference between nodes is defined (shared ground wire or isolated transceiver)","hint":"Common-mode range of the transceiver must cover ground offsets between nodes.","tags":[],"severity":"major"}]},{"id":"if-eth","title":"Ethernet","tags":[],"items":[{"id":"eth1","text":"Magnetics (integrated or discrete) are present between PHY and connector","hint":"Unless the design deliberately uses a capacitively coupled board-to-board link per the PHY application note.","tags":[],"severity":"critical"},{"id":"eth2","text":"Magnetics center-tap connection matches the PHY type (voltage-mode or current-mode) per datasheet","hint":"Current-mode PHYs need the center tap biased to a supply; voltage-mode PHYs typically want it AC-coupled only. Getting this wrong kills the link.","tags":[],"severity":"critical"},{"id":"eth3","text":"PHY reference clock (typically 25 MHz or 50 MHz) meets the PHY's frequency tolerance and jitter spec","hint":"Check the frequency tolerance and load capacitors. In RMII, the 50 MHz clock may come from the PHY or the MAC.","tags":[],"severity":"major"},{"id":"eth4","text":"MDI pairs are routed at 100 Ω differential impedance and length-matched","hint":"Keep the pairs away from board edges and over an unbroken reference plane.","tags":[],"severity":"major"},{"id":"eth5","text":"Link / activity LEDs are planned (in the jack or discrete) and their PHY strap interaction is understood","hint":"LED pins often double as straps, so the LED circuit can set the strap level.","tags":[],"severity":"minor"},{"id":"eth6","text":"PHY address strapping and MDIO/MDC wiring are correct","hint":"MDIO needs a pull-up per the PHY datasheet.","tags":[],"severity":"major"},{"id":"ifc-eth-1","text":"All PHY strap pins are at the intended level at reset, accounting for LED and other loads on shared pins","hint":"Straps often share LED or MAC pins; an LED or MCU pull can flip a strap. Check the strap thresholds in the datasheet.","tags":[],"severity":"critical"},{"id":"ifc-eth-2","text":"MAC-PHY interface mode (MII / RMII / RGMII) matches on both sides, including RGMII internal delays","hint":"RGMII needs a clock delay inserted by the PHY, the MAC or the PCB, and by exactly one of them.","tags":[],"severity":"major"},{"id":"ifc-eth-3","text":"Isolation rating of the magnetics and the creepage from MDI to logic meet the product's requirement","hint":"Check the magnetics' rated isolation voltage and keep logic copper clear of the MDI side.","tags":[],"severity":"major"},{"id":"ifc-eth-4","text":"PoE: PD controller classification and isolated converter are sized for the required power class","hint":"Size the isolated DC-DC for the full class power, including efficiency and hold-up.","tags":[],"severity":"major"},{"id":"ifc-eth-5","text":"PoE: input TVS and bridge rectification are present per the PD controller datasheet","hint":"A PoE PD must accept either polarity on either pair set. Check the bridge and TVS ratings per datasheet.","tags":[],"severity":"major"}]},{"id":"if-rf","title":"RF / Wireless (if applicable)","tags":["rf"],"items":[{"id":"rf1","text":"Antenna is matched to the module / PA output (typically 50 Ω) with a Pi or L network footprint","hint":"Fit a Pi footprint even if only a 0 Ω is populated initially, so matching can be tuned on the final enclosure.","tags":[],"severity":"major"},{"id":"rf2","text":"RF traces are impedance-controlled (e.g. 50 Ω microstrip or grounded coplanar waveguide)","hint":"Calculate the geometry from the actual stack-up, and stitch the coplanar ground with vias.","tags":[],"severity":"critical"},{"id":"rf3","text":"The antenna keep-out zone is free of copper on all layers","hint":"Follow the antenna or module vendor's keep-out drawing. Copper and components in the keep-out detune the antenna.","tags":[],"severity":"critical"},{"id":"rf4","text":"Crystal load capacitors for the RF device match the datasheet specification","hint":"Frequency error directly affects radio link margin. Account for stray capacitance.","tags":[],"severity":"major"},{"id":"rf5","text":"Regulatory certification route (modular approval or full certification) is decided for the end product","hint":"A pre-certified module keeps its grant only if its conditions (antenna type, layout) are followed.","tags":["regulatory"],"severity":"major"},{"id":"rf6","text":"Antenna diversity or an external antenna connector option is provided if needed","hint":"Decide this before enclosure design, since connector placement drives the mechanical layout.","tags":[],"severity":"minor"},{"id":"ifc-rf-1","text":"Test point or U.FL-style connector is provided for conducted RF measurements","hint":"A switched test connector or RF test pad allows conducted power and sensitivity measurements during certification.","tags":[],"severity":"major"}]},{"id":"if-gpio","title":"GPIO, Buttons & LEDs","tags":[],"items":[{"id":"ifc-gpio-1","text":"Every GPIO has a defined state during reset and before firmware configures it","hint":"Pins float or default to pulled states that may enable loads. Add pull resistors where a floating pin is unsafe.","tags":[],"severity":"critical"},{"id":"ifc-gpio-2","text":"Boot-mode / strap pins are at the intended level and not disturbed by attached circuits","hint":"Check boot pins against the MCU datasheet. An external load can override the internal pull.","tags":[],"severity":"major"},{"id":"ifc-gpio-3","text":"GPIO current per pin and per port is within MCU absolute limits","hint":"Sum the LED and other load currents on each port against the MCU's total I/O current limit.","tags":[],"severity":"major"},{"id":"ifc-gpio-4","text":"No input is driven above its rated voltage (5 V tolerance checked, including when the MCU is unpowered)","hint":"5 V-tolerant pins are often tolerant only while VDD is present.","tags":[],"severity":"critical"},{"id":"ifc-gpio-5","text":"Buttons have debounce (hardware RC or firmware) and ESD protection where user-accessible","hint":"Use series resistance plus a TVS or ESD diode on buttons reachable through the enclosure.","tags":[],"severity":"major"},{"id":"ifc-gpio-6","text":"Wake-capable pins are used for buttons / interrupts that must wake the device from sleep","hint":"Not every pin can wake the MCU from its deepest sleep mode. Check the datasheet's wake-pin list.","tags":[],"severity":"major"},{"id":"ifc-gpio-7","text":"Unused pins are configured or terminated as the MCU datasheet recommends","hint":"Floating inputs increase supply current and can oscillate.","tags":[],"severity":"major"}]},{"id":"if-debug","title":"JTAG / SWD / Debug","tags":[],"items":[{"id":"ifc-dbg-1","text":"Debug connector pinout matches the standard probe / cable to be used","hint":"Check pin 1 orientation and keying against the probe vendor's pinout, not just the MCU datasheet.","tags":[],"severity":"critical"},{"id":"ifc-dbg-2","text":"Target voltage reference (VTref) is connected so the probe can sense I/O voltage","hint":"Without VTref, many probes cannot set their output levels.","tags":[],"severity":"major"},{"id":"ifc-dbg-3","text":"Reset line is available on the debug header and has the pull-up / capacitor the MCU requires","hint":"A large reset capacitor can stop the probe from pulling reset low quickly enough.","tags":[],"severity":"major"},{"id":"ifc-dbg-4","text":"Debug pins are not reused for other functions in a way that blocks connection after boot","hint":"If firmware remaps the SWD pins at boot, keep a way back in, such as connect-under-reset.","tags":[],"severity":"major"},{"id":"ifc-dbg-5","text":"JTAG: TRST, TMS and TDI pull resistors follow the device datasheet","hint":"Wrong pull directions can hold the TAP in reset or make the chain unreliable.","tags":[],"severity":"major"},{"id":"ifc-dbg-6","text":"JTAG chain order and TCK fan-out are checked for multi-device chains","hint":"Check TCK signal integrity where it fans out to several devices.","tags":["fpga"],"severity":"major"},{"id":"ifc-dbg-7","text":"Programming access exists in production (pads, pogo-pin pattern or Tag-Connect footprint)","hint":"Plan fixture access early. Pads hidden under components or shields cannot be probed.","tags":["production"],"severity":"major"},{"id":"ifc-dbg-8","text":"Readout / debug lock plan is defined for shipped units","hint":"Locking debug access is often irreversible. Agree the lock level and when it is applied.","tags":["production"],"severity":"major"}]},{"id":"if-flash","title":"QSPI / OSPI Flash & EEPROM","tags":[],"items":[{"id":"ifc-qspi-1","text":"Flash voltage matches the I/O supply of the controller","hint":"Common flash parts come in 1.8 V and 3.3 V variants that share a part-number prefix.","tags":[],"severity":"critical"},{"id":"ifc-qspi-2","text":"CS has a pull-up so the flash is deselected during reset and power-up","hint":"A floating CS can corrupt flash content during power transitions.","tags":[],"severity":"major"},{"id":"ifc-qspi-3","text":"WP# and HOLD#/RESET# pins are pulled to an inactive state or driven when not used as IO2/IO3","hint":"In single or dual mode these pins are control inputs and must not float.","tags":[],"severity":"major"},{"id":"ifc-qspi-4","text":"Quad / octal mode wiring matches the flash pinout and its QE / mode configuration","hint":"Check whether the part ships with quad mode enabled or needs a status-register write.","tags":[],"severity":"major"},{"id":"ifc-qspi-5","text":"Boot ROM supports the chosen flash part, mode and address width if the device boots from it","hint":"Check the boot ROM's supported command set and dummy-cycle defaults.","tags":[],"severity":"critical"},{"id":"ifc-qspi-6","text":"Flash reset is asserted with the processor reset, so the flash is not left in a 4-byte or QPI mode after a warm reset","hint":"A warm reset that does not also reset the flash can leave the boot ROM unable to read it.","tags":[],"severity":"major"},{"id":"ifc-eeprom-1","text":"EEPROM write-protect pin is in the intended state","hint":"Decide whether WP is controlled by firmware or strapped, and check its default level.","tags":[],"severity":"major"}]},{"id":"if-sd","title":"SD / eMMC / SDIO","tags":[],"items":[{"id":"ifc-sd-1","text":"CMD and DAT lines have pull-ups per the SD / eMMC specification and device datasheet","hint":"Take pull-up values from the host datasheet. Do not omit them on unused DAT lines.","tags":[],"severity":"major"},{"id":"ifc-sd-2","text":"CLK has series termination at the host and no pull-up","hint":"Place the series resistor near the host to reduce ringing.","tags":[],"severity":"major"},{"id":"ifc-sd-3","text":"Bus lines are length-matched to CLK for the highest speed mode used","hint":"Faster modes need tighter matching. Check the host datasheet.","tags":[],"severity":"major"},{"id":"ifc-sd-4","text":"UHS-I card voltage switching (3.3 V to 1.8 V signaling) is supported by the I/O supply if UHS modes are used","hint":"Without a switchable I/O supply, the card falls back to slower modes.","tags":[],"severity":"major"},{"id":"ifc-sd-5","text":"SD card power is switched so the card can be power-cycled to recover from errors","hint":"A card stuck in a bad state often recovers only after a full power cycle.","tags":[],"severity":"major"},{"id":"ifc-sd-6","text":"ESD protection is fitted on the user-accessible SD slot lines","hint":"Use low-capacitance protection suited to the bus speed.","tags":[],"severity":"major"},{"id":"ifc-sd-7","text":"eMMC VCC and VCCQ rails and their decoupling match the device datasheet","hint":"VCCQ may be 1.8 V or 3.3 V depending on the device and the bus mode.","tags":[],"severity":"major"}]},{"id":"if-ddr","title":"DDR / External Memory","tags":["ddr"],"items":[{"id":"ifc-ddr-1","text":"DDR type, density and speed grade are supported by the controller and its boot / init software","hint":"Confirm the controller's supported device widths, ranks and densities.","tags":[],"severity":"critical"},{"id":"ifc-ddr-2","text":"Pin and byte-lane mapping follows the controller's allowed swaps","hint":"Many controllers allow bit swaps within a byte lane but not across lanes. Check the vendor rules.","tags":[],"severity":"critical"},{"id":"ifc-ddr-3","text":"Data byte lanes are length-matched to their strobes within the controller vendor's limits","hint":"Use the vendor's limits, including package delays if the design guide requires them.","tags":[],"severity":"major"},{"id":"ifc-ddr-4","text":"Address / command / control group is length-matched to the clock within the controller vendor's limits","hint":"Fly-by and T-branch topologies have different rules. Follow the controller design guide.","tags":[],"severity":"major"},{"id":"ifc-ddr-5","text":"VTT termination regulator can source and sink the required current (fly-by topologies)","hint":"VTT must track VDDQ/2 and handle both sink and source current.","tags":[],"severity":"critical"},{"id":"ifc-ddr-6","text":"VREF generation, filtering and routing follow the controller / memory datasheet","hint":"Keep VREF away from noisy nets and decouple it at each device.","tags":[],"severity":"major"},{"id":"ifc-ddr-7","text":"ZQ calibration resistors are fitted with the specified value and tolerance","hint":"Use a dedicated resistor per device where required; do not share ZQ resistors unless the datasheet allows it.","tags":[],"severity":"major"},{"id":"ifc-ddr-8","text":"Memory power sequencing and RESET_n / CKE behavior follow the JEDEC device datasheet","hint":"Incorrect sequencing can make initialization unreliable.","tags":[],"severity":"major"},{"id":"ifc-ddr-9","text":"Signal-integrity simulation or the vendor's layout check has been completed","hint":"Run the controller vendor's layout or SI checklist before release.","tags":[],"severity":"major"}]},{"id":"if-pcie","title":"PCIe","tags":["high-speed"],"items":[{"id":"ifc-pcie-1","text":"TX/RX lane polarity and lane order are correct or are supported reversals","hint":"PCIe allows polarity inversion within a pair. Lane-reversal support depends on the device.","tags":[],"severity":"critical"},{"id":"ifc-pcie-2","text":"AC-coupling capacitors are on the TX side of each link with the value the spec requires","hint":"Check which end of the link needs the capacitors on each pair.","tags":[],"severity":"critical"},{"id":"ifc-pcie-3","text":"Reference clock source, architecture (common / separate) and jitter meet the endpoint requirement","hint":"Check the clock's jitter against the requirement for the PCIe generation used.","tags":[],"severity":"major"},{"id":"ifc-pcie-4","text":"PERST# is driven with the required timing relative to power-good and refclk","hint":"PERST# must be held asserted until power and refclk are stable.","tags":[],"severity":"critical"},{"id":"ifc-pcie-5","text":"CLKREQ# and WAKE# are wired as open-drain with pull-ups if used","hint":"Check the pull-up voltage domain, since these signals may cross power domains.","tags":[],"severity":"major"},{"id":"ifc-pcie-6","text":"Differential pairs are at the target impedance with intra-pair skew controlled","hint":"Route both signals of a pair together on one reference plane, with skew compensation near the mismatch.","tags":[],"severity":"major"},{"id":"ifc-pcie-7","text":"M.2 / card-edge connector key, pinout and power rails match the module type","hint":"Check the M.2 key, module length and 3.3 V current per the module datasheet.","tags":[],"severity":"major"}]},{"id":"if-csi","title":"MIPI CSI Camera","tags":[],"items":[{"id":"ifc-csi-1","text":"Lane count, data rate and lane mapping are supported by the processor's CSI receiver","hint":"Check the processor supports the sensor's output format and bit depth.","tags":[],"severity":"critical"},{"id":"ifc-csi-2","text":"D-PHY / C-PHY pairs are routed at the target impedance and length-matched to the clock lane","hint":"Keep the clock and data lanes on the same layer and reference plane.","tags":[],"severity":"major"},{"id":"ifc-csi-3","text":"Sensor MCLK frequency and source match the sensor datasheet","hint":"Some sensors need a specific MCLK frequency for their PLL to reach the configured frame rates.","tags":[],"severity":"major"},{"id":"ifc-csi-4","text":"Sensor power rails and sequencing match the sensor datasheet","hint":"Image sensors often need the analog, digital and I/O rails in a specific order.","tags":[],"severity":"critical"},{"id":"ifc-csi-5","text":"Camera control I2C (CCI) address does not clash with other devices","hint":"Some sensors have a fixed address, so two identical cameras may need separate buses or an I2C mux.","tags":[],"severity":"major"},{"id":"ifc-csi-6","text":"Reset / power-down pins have defined states during processor reset","hint":"An undefined power-down pin can leave the sensor drawing current or driving the bus while the host boots.","tags":[],"severity":"major"}]},{"id":"if-hdmi","title":"HDMI / DisplayPort","tags":["high-speed"],"items":[{"id":"ifc-hdmi-1","text":"TMDS / main-link pairs are at the target impedance and length-matched","hint":"Take impedance and skew limits from the transmitter / retimer design guide.","tags":[],"severity":"major"},{"id":"ifc-hdmi-2","text":"Low-capacitance ESD protection rated for the link speed is fitted at the connector","hint":"The protection device's capacitance must suit the link speed.","tags":[],"severity":"major"},{"id":"ifc-hdmi-3","text":"DDC / AUX pull-ups and level shifting are present per the interface specification","hint":"DDC is open-drain at 5 V on the cable side. Most SoCs need a level shifter.","tags":[],"severity":"major"},{"id":"ifc-hdmi-4","text":"Hot-plug detect is wired and level-shifted to the controller","hint":"Hot-plug detect is often at 5 V on the cable side and needs a divider or shifter.","tags":[],"severity":"major"},{"id":"ifc-hdmi-5","text":"HDMI 5 V output has current limiting (source) or is not back-driven (sink)","hint":"A source must limit its 5 V output; a sink must not back-drive the source through it.","tags":[],"severity":"major"},{"id":"ifc-hdmi-6","text":"DisplayPort AC-coupling capacitors are present on the main link","hint":"Check the capacitor value and placement per the transmitter datasheet.","tags":[],"severity":"major"}]},{"id":"if-serial","title":"RS-232 / RS-485 / RS-422","tags":[],"items":[{"id":"ifc-ser-1","text":"Transceiver ESD / surge rating suits the cable environment","hint":"Add TVS rated for the transceiver's bus voltage range if the built-in protection is not enough. Complements the RS-232 / RS-485 checks in the UART section.","tags":[],"severity":"major"},{"id":"ifc-ser-2","text":"RS-485 common-mode range covers the expected ground offset between nodes, or the link is isolated","hint":"Ground offsets between buildings or equipment can exceed the transceiver's common-mode range.","tags":[],"severity":"major"},{"id":"ifc-ser-3","text":"RS-485 unit load and node count are within the transceiver's rating","hint":"Fractional unit-load transceivers allow more nodes on one segment.","tags":[],"severity":"major"},{"id":"ifc-ser-4","text":"Data rate and cable length are within the transceiver's slew-rate capability","hint":"Slew-limited transceivers reduce EMI but cap the data rate.","tags":[],"severity":"major"},{"id":"ifc-ser-5","text":"Isolated transceivers have an isolated supply sized and laid out per datasheet","hint":"Check the isolated supply delivers enough current for the transceiver at the maximum data rate.","tags":[],"severity":"major"},{"id":"ifc-ser-6","text":"RS-422 receivers are terminated and the driver remains enabled (point-to-multipoint)","hint":"RS-422 drivers are normally always enabled. Termination sits at the far receiver.","tags":[],"severity":"major"}]},{"id":"if-lin","title":"LIN","tags":[],"items":[{"id":"ifc-lin-1","text":"LIN transceiver battery-pin rating covers the transients expected on the supply line","hint":"LIN nodes connect directly to the battery line, so the transceiver sees battery transients.","tags":[],"severity":"critical"},{"id":"ifc-lin-2","text":"Commander node has the commander pull-up and series diode per the transceiver datasheet","hint":"Only the commander node fits the pull-up.","tags":[],"severity":"major"},{"id":"ifc-lin-3","text":"Bus capacitance on the node is within the transceiver / LIN spec allowance","hint":"Excess node capacitance slows edges and can cause bit errors.","tags":[],"severity":"major"},{"id":"ifc-lin-4","text":"LIN wake-up and sleep modes are wired so the node meets its quiescent-current budget","hint":"Check the node's sleep current with the transceiver in sleep mode.","tags":["low-power"],"severity":"major"},{"id":"ifc-lin-5","text":"ESD protection on the LIN pin is suitable for automotive-level ESD","hint":"Choose a TVS rated for LIN bus voltages, or rely on the transceiver's rating if it is sufficient.","tags":["automotive"],"severity":"major"},{"id":"ifc-lin-6","text":"Transceiver INH / EN pins are wired to control the node's regulator as intended","hint":"INH can switch the node's regulator so the node fully powers down in sleep.","tags":[],"severity":"major"}]},{"id":"if-1wire","title":"1-Wire","tags":[],"items":[{"id":"ifc-1w-1","text":"Pull-up resistor value suits the bus length and number of devices","hint":"Long buses or many devices may need a lower pull-up value. Check the device datasheet.","tags":[],"severity":"major"},{"id":"ifc-1w-2","text":"Strong pull-up (or external supply) is provided for devices that need it during conversion / write","hint":"Parasitically powered devices draw extra current during temperature conversion or EEPROM writes.","tags":[],"severity":"major"},{"id":"ifc-1w-3","text":"Bus driver is open-drain with timing generated by a peripheral or tolerant firmware","hint":"Bit-banged timing must survive the worst-case interrupt latency.","tags":[],"severity":"major"},{"id":"ifc-1w-4","text":"ESD protection is fitted where the bus leaves the board","hint":"Use protection that does not add enough capacitance to break the bus timing.","tags":[],"severity":"major"},{"id":"ifc-1w-5","text":"Device discovery (ROM search) or fixed addressing is planned","hint":"Plan how ROM codes are discovered or stored when there are several devices.","tags":[],"severity":"minor"},{"id":"ifc-1w-6","text":"Long cable runs use a dedicated 1-Wire driver if needed","hint":"A dedicated 1-Wire master IC handles long cable runs better than a GPIO.","tags":[],"severity":"major"}]},{"id":"if-sensor","title":"Analog Sensor Inputs","tags":["precision-analog"],"items":[{"id":"ifc-sens-1","text":"4–20 mA input: burden resistor value, tolerance and power rating suit the full current range","hint":"Include fault currents above 20 mA and below 4 mA so faults can be detected.","tags":[],"severity":"major"},{"id":"ifc-sens-2","text":"4–20 mA input: burden resistor and ADC input are protected against miswiring to the loop supply","hint":"A field wiring error can put the loop supply directly across the burden resistor or the ADC input.","tags":[],"severity":"critical"},{"id":"ifc-sens-3","text":"4–20 mA loop supply compliance voltage is enough for the transmitter plus burden and cable drop","hint":"Calculate the minimum loop supply needed at full-scale current with the worst-case cable resistance.","tags":[],"severity":"major"},{"id":"ifc-sens-4","text":"Thermocouple input has open-thermocouple detection (bias / burnout current)","hint":"Without it, a broken thermocouple can read as a plausible temperature. Complements the CJC check in the ADC section.","tags":[],"severity":"major"},{"id":"ifc-sens-5","text":"RTD wiring (2, 3 or 4 wire) matches the lead-resistance error budget","hint":"Two-wire RTDs add lead resistance directly to the reading; three- and four-wire connections cancel it. Complements the excitation check in the ADC section.","tags":[],"severity":"major"},{"id":"ifc-sens-6","text":"Bridge sensors: excitation, gain and offset are budgeted for full-scale range","hint":"Check the bridge output range against the ADC input range at the chosen gain.","tags":[],"severity":"major"},{"id":"ifc-sens-7","text":"Sensor inputs have EMI filtering suited to cable length and the environment","hint":"Use RC filtering on each input, plus differential filtering where the inputs are differential.","tags":[],"severity":"major"}]},{"id":"if-audio","title":"Audio Codec & Amplifier","tags":["audio"],"items":[{"id":"ifc-aud-1","text":"Codec analog supply is low-noise and decoupled per datasheet","hint":"Analog supply noise appears directly in the audio output.","tags":[],"severity":"major"},{"id":"ifc-aud-2","text":"Microphone bias and input coupling capacitors are correct for the mic type","hint":"Electret mics need a bias supply; analog MEMS mics need supply and coupling per datasheet.","tags":[],"severity":"major"},{"id":"ifc-aud-3","text":"Class-D amplifier output filter / ferrite choice suits the EMC requirement","hint":"Filterless class-D outputs can radiate on long speaker wires.","tags":[],"severity":"major"},{"id":"ifc-aud-4","text":"Amplifier power and speaker impedance are compatible and the supply can deliver the peak current","hint":"Peak current at low speaker impedance can sag the supply and cause resets.","tags":[],"severity":"critical"},{"id":"ifc-aud-5","text":"Headphone output has coupling capacitors or is ground-centered (cap-less) per datasheet","hint":"Coupling-capacitor value sets the low-frequency cutoff with the headphone impedance.","tags":[],"severity":"major"},{"id":"ifc-aud-6","text":"ESD protection is fitted on audio jacks without degrading audio quality","hint":"Low-capacitance protection avoids degrading the audio quality.","tags":[],"severity":"major"}]},{"id":"if-touch","title":"Touch","tags":["display"],"items":[{"id":"ifc-touch-1","text":"Touch controller supports the sensor size and channel count","hint":"Check the channel count and the sensor pattern against the controller vendor's guidance.","tags":[],"severity":"major"},{"id":"ifc-touch-2","text":"Touch controller reset line is connected and defined during processor reset","hint":"Without reset control, a hung controller needs a full power cycle to recover.","tags":[],"severity":"major"},{"id":"ifc-touch-3","text":"Interrupt line is wake-capable if touch must wake the system","hint":"Check that the interrupt pin can wake the processor from its sleep mode.","tags":[],"severity":"major"},{"id":"ifc-touch-4","text":"Touch supply is clean and away from display / backlight switching noise","hint":"Display and backlight noise is a common cause of false touches.","tags":[],"severity":"major"},{"id":"ifc-touch-5","text":"Ground and shield connections between touch panel, display and chassis follow the vendor guidance","hint":"Follow the touch vendor's grounding guidance; poor grounding gives false or missed touches.","tags":[],"severity":"major"},{"id":"ifc-touch-6","text":"Firmware / configuration file loading for the touch controller is planned","hint":"Some controllers need a configuration or firmware file loaded at every boot.","tags":[],"severity":"minor"}]},{"id":"if-wireless","title":"Wireless Modules (BLE / Wi-Fi / Cellular / GNSS)","tags":["rf"],"items":[{"id":"ifc-wl-1","text":"Module footprint and keep-out follow the module vendor's reference design","hint":"Deviating from the reference layout can affect RF performance and the module's certification.","tags":[],"severity":"major"},{"id":"ifc-wl-2","text":"Module supply can deliver the peak transmit current without dropping below its minimum voltage","hint":"Cellular modules draw large current bursts; size bulk capacitance per vendor guidance.","tags":[],"severity":"critical"},{"id":"ifc-wl-3","text":"Module reset / power-key / boot pins are controllable by the host","hint":"Host control lets firmware recover a hung module without a full power cycle.","tags":[],"severity":"major"},{"id":"ifc-wl-4","text":"Host interface (UART / SPI / SDIO / USB) and its flow control are wired per the module datasheet","hint":"Hardware flow control is usually needed at high UART rates.","tags":[],"severity":"major"},{"id":"ifc-wl-5","text":"Cellular: SIM / eSIM circuit has ESD protection and the required decoupling","hint":"Check the SIM interface follows the module vendor's reference design.","tags":[],"severity":"major"},{"id":"ifc-wl-6","text":"GNSS: active antenna bias and LNA supply are provided if needed","hint":"Active GNSS antennas need a DC bias on the RF feed, with a current limit to protect against a shorted cable.","tags":[],"severity":"major"},{"id":"ifc-wl-7","text":"Module certifications cover the chosen antenna type and gain","hint":"Using a different antenna type or a higher gain can invalidate the module's certification.","tags":["regulatory"],"severity":"major"}]},{"id":"if-motor","title":"Motor Driver Interfaces","tags":["motor"],"items":[{"id":"ifc-mot-1","text":"Driver enable / PWM inputs are pulled to a safe (off) state during MCU reset","hint":"Use pull resistors on driver inputs so the bridge stays off before firmware runs. Complements the dead-time and break-input checks in Timers & PWM.","tags":[],"severity":"critical"},{"id":"ifc-mot-2","text":"Current sense feedback scaling and filtering suit the ADC range and the control loop","hint":"Check the sense amplifier's bandwidth and the filter delay against the control loop requirement.","tags":[],"severity":"major"},{"id":"ifc-mot-3","text":"Driver fault output is wired to an interrupt or the timer break input","hint":"Route the fault to the timer break input so the outputs shut down in hardware.","tags":[],"severity":"major"},{"id":"ifc-mot-4","text":"Hall / encoder inputs have filtering and pull-ups for the cable length","hint":"Long cables near motor wiring pick up noise; add filtering and pull-ups at the receiver.","tags":[],"severity":"major"},{"id":"ifc-mot-5","text":"Driver SPI / configuration interface is at a compatible logic level","hint":"Some drivers have 5 V logic levels that need translation to 3.3 V MCUs.","tags":[],"severity":"major"},{"id":"ifc-mot-6","text":"Logic ground and power ground are joined so that motor currents do not flow in the logic reference","hint":"Motor current through the logic ground shifts logic references and causes false readings.","tags":[],"severity":"major"}]},{"id":"if-indio","title":"Industrial I/O (24 V Digital)","tags":["harsh-env"],"items":[{"id":"ifc-io-1","text":"24 V digital inputs tolerate reverse polarity and the overvoltage expected in the installation","hint":"Field wiring errors and surges are common in industrial installations.","tags":[],"severity":"critical"},{"id":"ifc-io-2","text":"Input thresholds and current match the relevant input type (e.g. IEC 61131-2 type 1 / 3) where required","hint":"Industrial input types define switching thresholds and minimum currents for compatibility with sensors.","tags":[],"severity":"major"},{"id":"ifc-io-3","text":"Inputs are isolated or filtered so field noise does not reach logic","hint":"Optocouplers or digital isolators keep field noise and ground offsets out of the logic.","tags":[],"severity":"major"},{"id":"ifc-io-4","text":"High-side outputs have short-circuit and thermal protection","hint":"Use smart high-side switches with built-in protection, or discrete current limiting.","tags":[],"severity":"critical"},{"id":"ifc-io-5","text":"Inductive loads on outputs have a demagnetization / clamp path","hint":"Turning off an inductive load without a clamp path can destroy the output switch.","tags":[],"severity":"critical"},{"id":"ifc-io-6","text":"Surge and EFT protection on field terminals suits the target immunity level","hint":"Choose TVS and filtering suited to the expected surge and EFT levels.","tags":[],"severity":"major"},{"id":"ifc-io-7","text":"Field-side supply is protected and fused","hint":"Protect the field supply with a fuse or electronic current limit so a field short does not take down the board.","tags":[],"severity":"major"}]}]},{"id":"pcb","title":"PCB Layout Review","short":"Layout","version":2,"description":"Layout review covering stackup, rules, mechanical fit, placement, power integrity, routing, specialized interfaces, safety spacing, EMC, test access and manufacturability.","sections":[{"id":"p-gen","title":"Board Setup, Stackup & Impedance","tags":[],"items":[{"id":"pg1","text":"Board outline matches the mechanical drawing, including dimensions and tolerances","hint":"Overlay the DXF/STEP outline on the board outline layer and compare key dimensions. A wrong outline usually means a respin or a board that won't fit the enclosure.","tags":[],"severity":"critical"},{"id":"pg2","text":"Design rule check (DRC) runs with zero errors or every waived error is documented","hint":"Run full online and batch DRC on the final database. Any waiver should name the rule, the location and why it's acceptable.","tags":[],"severity":"critical"},{"id":"pg3","text":"Layer stackup matches the fabricator's confirmed stackup (copper weights, dielectric thicknesses, materials)","hint":"Get the stackup confirmed by the fab before routing impedance-controlled nets. Check the copper weight and dielectric thickness of every layer against the CAD layer setup.","tags":[],"severity":"critical"},{"id":"pg4","text":"Controlled-impedance trace widths and spacings match the stackup calculation","hint":"Recalculate with the fab's dielectric constants or use their impedance report. Check every impedance class on every layer it's routed on.","tags":[],"severity":"critical"},{"id":"pg5","text":"Board material (FR-4 grade, Rogers, etc.) meets the electrical and thermal requirements","hint":"Check Tg and Td against the reflow profile and operating temperature, and Dk/Df against the signal frequencies. Specify high-Tg material for lead-free reflow of thick or many-layer boards.","tags":[],"severity":"major"},{"id":"pcb-stk-1","text":"Stackup is symmetric about the board center","hint":"Asymmetric copper or dielectric causes bow and twist after reflow. Mirror copper weights and dielectric thicknesses top to bottom wherever possible.","tags":[],"severity":"major"},{"id":"pcb-stk-2","text":"Every signal layer is adjacent to a solid reference plane","hint":"A signal layer between two signal layers with no plane has no defined impedance or return path. If unavoidable, route those layers orthogonally and only with slow signals.","tags":[],"severity":"major"},{"id":"pcb-stk-3","text":"Power and ground planes that act as plane capacitance are on adjacent layers with thin dielectric","hint":"Close-spaced power/ground pairs give low-inductance high-frequency decoupling. Confirm the intended pairs are adjacent in the stackup.","tags":[],"severity":"major"},{"id":"pcb-stk-4","text":"Impedance requirements and tolerances are stated on the fab drawing with layer and reference planes","hint":"List each controlled-impedance class (e.g. 50 ohm SE, 90/100 ohm diff), the layer, the reference layers and the tolerance, so the fab can tune and test coupons.","tags":[],"severity":"major"},{"id":"pcb-stk-5","text":"Finished board thickness and tolerance match connector, card-edge and enclosure requirements","hint":"Card-edge connectors, press-fit parts and slot guides need a specific thickness. Check the stackup total including plating and mask.","tags":[],"severity":"major"},{"id":"pcb-stk-6","text":"Outer-layer copper weight suits both the current and the finest pitch on that layer","hint":"Heavy outer copper limits minimum trace/space and fine-pitch etching. Confirm with the fab's capability table for the chosen weight, e.g. 35 µm (1 oz) vs 70 µm (2 oz).","tags":[],"severity":"major"},{"id":"pcb-stk-7","text":"Surface finish (ENIG, HASL, OSP, ENEPIG, immersion silver) is specified and suits the parts","hint":"Fine-pitch and BGA parts need a flat finish such as ENIG or OSP. Wire bonding and gold-finger contacts need specific finishes.","tags":[],"severity":"minor"}]},{"id":"p-rules","title":"Design Rules & Constraints","tags":[],"items":[{"id":"pcb-rule-1","text":"Design rules are set to the chosen fabricator's capability, not the CAD tool defaults","hint":"Enter minimum track, space, drill, annular ring and mask rules from the fab's capability sheet for the selected class/price tier.","tags":[],"severity":"major"},{"id":"pcb-rule-2","text":"Net classes are defined for power, high-voltage, impedance-controlled and sensitive nets","hint":"Net classes drive width, clearance and via rules automatically. Check that every special net is assigned to its class.","tags":[],"severity":"major"},{"id":"pcb-rule-3","text":"Clearance rules between net classes reflect the voltages present","hint":"High-voltage nets need larger clearance to everything else. Set class-to-class rules so DRC catches violations instead of relying on visual checks.","tags":[],"severity":"major"},{"id":"pcb-rule-4","text":"Width rules for power nets are set from the current requirement","hint":"Set minimum width per power net class from an IPC-2152 style calculation so thin necks are caught by DRC.","tags":[],"severity":"major"},{"id":"pcb-rule-5","text":"Differential pair rules (width, gap, uncoupled length) are defined for every pair class","hint":"Without pair rules the router and DRC can't enforce coupling. Check the rules match the impedance calculation.","tags":[],"severity":"major"},{"id":"pcb-rule-6","text":"Length and match constraints are entered for timing-critical nets","hint":"Enter match groups and tolerances from the interface spec or datasheet, then confirm the length report passes.","tags":[],"severity":"major"},{"id":"pcb-rule-7","text":"Schematic and layout are in sync, with no unresolved ECO differences","hint":"Run a forward or back-annotation compare. Any difference means the board won't match the schematic that was reviewed.","tags":[],"severity":"major"}]},{"id":"p-mech","title":"Mechanical, Outline & Enclosure Fit","tags":[],"items":[{"id":"pcb-mech-1","text":"Mounting holes are in the right positions with the right diameters for the fasteners","hint":"Check hole positions and diameters against the mechanical drawing or enclosure CAD. Include tolerance on position.","tags":[],"severity":"critical"},{"id":"pcb-mech-2","text":"Mounting holes are plated and grounded, or unplated and isolated, as the design intends","hint":"Grounded mounting holes are often part of the EMC or ESD strategy. Isolated holes need copper keepout around the fastener and washer.","tags":[],"severity":"major"},{"id":"pcb-mech-3","text":"Copper keepout around mounting holes covers the fastener head, washer and standoff","hint":"A screw head or metal standoff touching copper can short a net to chassis. Size the keepout to the largest hardware plus tolerance.","tags":[],"severity":"major"},{"id":"pcb-mech-4","text":"A 3D model check against the enclosure shows no collisions","hint":"Export STEP with accurate component models and check it in the enclosure assembly, including lids, ribs, bosses and cables.","tags":[],"severity":"critical"},{"id":"pcb-mech-5","text":"Component height limits are respected in every height-restricted zone","hint":"Check tall parts (electrolytics, inductors, connectors) against the enclosure. Include the board-to-lid gap and any tolerance stack.","tags":[],"severity":"major"},{"id":"pcb-mech-6","text":"Connectors line up with the enclosure openings, including position and height tolerance","hint":"Check the mating face against the panel cut-outs. A connector that is off by a fraction of a mm may not mate through the opening.","tags":[],"severity":"major"},{"id":"pcb-mech-7","text":"LEDs, buttons, light pipes and displays line up with their enclosure features","hint":"Check positions in the 3D assembly. Light pipes need the LED centered under them, and buttons need the right actuator height.","tags":[],"severity":"major"},{"id":"pcb-mech-8","text":"Board-edge clearance suits the routing, V-score or breakout method","hint":"Copper and parts too close to a V-score or tab can crack or get damaged. Use the fab and assembler's edge-clearance rules.","tags":[],"severity":"major"},{"id":"pcb-mech-9","text":"Keepouts for heatsinks, shields, clips and enclosure ribs are drawn and respected","hint":"Mechanical parts that are not in the BOM are easy to forget. Add them as keepout regions so DRC catches conflicts.","tags":[],"severity":"major"},{"id":"pcb-mech-10","text":"Mechanical layers carry the fab and assembly drawings with dimensions, notes and datums","hint":"The fab needs a dimensioned outline with a datum. Check that the drawing on the mechanical layer matches the current outline.","tags":[],"severity":"major"}]},{"id":"p-pla","title":"Component Placement","tags":[],"items":[{"id":"pp1","text":"All components are inside the board outline with adequate clearance to the edge","hint":"Use the assembler's edge clearance, especially if the board travels on conveyor rails. Parts too close to a breakout tab can crack when depaneled.","tags":[],"severity":"major"},{"id":"pp2","text":"Bypass capacitors are placed as close as possible to the IC power pins they serve","hint":"Put the smallest-value capacitor nearest the pin with the shortest possible loop to ground. Check in the layout, not just by reference designator.","tags":[],"severity":"major"},{"id":"pp3","text":"High-dissipation components have enough copper area to spread their heat","hint":"Compare the copper area under and around each hot part with the datasheet's recommended thermal layout.","tags":[],"severity":"major"},{"id":"pp4","text":"Sensitive analog parts are physically separated from noisy digital and switching circuits","hint":"Group by function and keep switching nodes, clocks and fast digital away from high-impedance analog inputs.","tags":[],"severity":"major"},{"id":"pp5","text":"Connectors face the right way for their mating direction and assembly","hint":"Check pin 1 and the mating face in 3D against the cable or mating board. A mirrored connector is a respin.","tags":[],"severity":"critical"},{"id":"pp6","text":"Mechanical constraints (keepouts, mounting holes, standoffs) are respected","hint":"Check every placed part against the keepout regions on the mechanical layers.","tags":[],"severity":"critical"},{"id":"pp7","text":"Polarized parts and ICs are in a consistent, verified orientation","hint":"Keep the same orientation for like parts where possible to make inspection easier. Check every diode, electrolytic and IC pin 1 against the footprint.","tags":[],"severity":"major"},{"id":"pcb-pl-1","text":"Every footprint matches the datasheet land pattern for the exact orderable part","hint":"Check pad size, pitch, pin numbering and package variant. Use IPC-7351 style land patterns or the manufacturer's recommendation.","tags":[],"severity":"critical"},{"id":"pcb-pl-2","text":"Components are placed in functional groups that follow the signal flow","hint":"Grouping by function shortens critical routes and keeps noisy and quiet circuits apart.","tags":[],"severity":"major"},{"id":"pcb-pl-3","text":"Crystals and oscillators are next to their IC, away from board edges and noisy circuits","hint":"Keep crystal traces short with ground beneath and no signals routed under the crystal. Follow the IC's layout guidance for load capacitors.","tags":[],"severity":"major"},{"id":"pcb-pl-4","text":"Switching regulators are placed per the datasheet layout example","hint":"The datasheet layout keeps the hot loop small. Moving the input capacitor or inductor away from it can cause noise and instability.","tags":[],"severity":"major"},{"id":"pcb-pl-5","text":"Parts are placed to allow rework access, with room around BGAs and fine-pitch parts","hint":"Rework nozzles and soldering irons need clearance. Tall parts right next to a BGA block rework.","tags":[],"severity":"major"},{"id":"pcb-pl-6","text":"Bottom-side parts suit the assembly process","hint":"Heavy or tall parts on the bottom may fall off during second-side reflow or need glue. Confirm with the assembler which parts can go on the bottom.","tags":[],"severity":"major"},{"id":"pcb-pl-7","text":"Through-hole parts are placed for the chosen soldering method (wave, selective or hand)","hint":"Selective solder nozzles need clearance around pins. Wave soldering needs SMD parts on the bottom oriented and spaced for the wave.","tags":[],"severity":"major"},{"id":"pcb-pl-8","text":"Heat-sensitive parts are kept away from hot components","hint":"Electrolytic capacitors, crystals, batteries and sensors drift or age faster near regulators and power resistors.","tags":[],"severity":"major"},{"id":"pcb-pl-9","text":"Parts near board edges or V-score lines are oriented to reduce flex cracking","hint":"Ceramic capacitors near edges or depanel lines can crack. Orient them parallel to the break line and keep them back from it.","tags":[],"severity":"major"}]},{"id":"p-pdn","title":"Decoupling & Power Integrity","tags":[],"items":[{"id":"pcb-pdn-1","text":"Each decoupling capacitor connects to the power and ground planes through short, wide paths","hint":"Mounting inductance dominates at high frequency. Use short traces from pad to via, and vias placed beside or inside the pad.","tags":[],"severity":"major"},{"id":"pcb-pdn-2","text":"Decoupling capacitors have their own vias rather than sharing vias with the IC pin","hint":"Shared vias increase the current loop. As a rule of thumb, give each capacitor its own via pair where space allows.","tags":[],"severity":"major"},{"id":"pcb-pdn-3","text":"Bulk capacitance is placed where each rail enters a region or a high-current load","hint":"Bulk capacitors handle lower-frequency load steps. Put them at the regulator output and near large loads.","tags":[],"severity":"major"},{"id":"pcb-pdn-4","text":"Voltage drop from regulator to load is within the load's tolerance at maximum current","hint":"Estimate IR drop through traces, planes and vias, or run a DC drop analysis for high-current rails.","tags":[],"severity":"major"},{"id":"pcb-pdn-5","text":"Remote sense lines take a Kelvin connection at the load point","hint":"Route the sense pair together, away from the high-current path and switching nodes.","tags":[],"severity":"major"},{"id":"pcb-pdn-6","text":"Regulator feedback traces are short and kept away from the switch node and inductor","hint":"Noise coupled into the feedback node causes jitter and instability. Route it on the quiet side of the circuit with a ground reference.","tags":[],"severity":"major"},{"id":"pcb-pdn-7","text":"Switching regulator hot loops (input capacitor, switch, return) are as small as possible","hint":"The input loop carries the fastest current edges. Keep it tight on one layer with the input capacitor close to the switch pins.","tags":[],"severity":"major"},{"id":"pcb-pdn-8","text":"Switch-node copper is no larger than needed to carry the current","hint":"A large switch-node area radiates. Keep it compact and do not route sensitive signals under or next to it.","tags":[],"severity":"major"},{"id":"pcb-pdn-9","text":"Power delivery network impedance meets the target for processor, FPGA or memory rails","hint":"Use the vendor's PDN tool or a simulation to check impedance vs frequency against the target from the datasheet.","tags":["fpga","ddr"],"severity":"major"}]},{"id":"p-pwr","title":"Power & Ground Planes","tags":[],"items":[{"id":"pw1","text":"Power and ground planes are solid, with minimal splits or voids","hint":"Look at each plane layer on its own. Rows of vias with large anti-pads can cut a plane as badly as a deliberate split.","tags":[],"severity":"major"},{"id":"pw2","text":"Plane connections to pads and vias use the intended thermal relief or direct connection","hint":"Thermal relief helps soldering on through-hole and large pads. High-current or thermal paths may need direct connections instead.","tags":[],"severity":"major"},{"id":"pw3","text":"Ground stitching vias tie ground layers together around the board and between layers","hint":"Stitch ground pours to the ground plane so islands don't float, and consider a via fence along the board edge. Spacing is a rule of thumb set by the highest frequency of concern.","tags":[],"severity":"major"},{"id":"pw4","text":"Plane-to-plane capacitance is used where it helps the power delivery network","hint":"Tightly coupled power/ground planes add low-inductance capacitance. Worth checking on dense, fast digital boards.","tags":[],"severity":"minor"},{"id":"pw5","text":"Where split analog and digital grounds are used, they join at a single, deliberate point","hint":"Most modern designs use one solid ground with careful placement instead of split grounds. If grounds are split, check no signal crosses the gap and the tie point is where the datasheet recommends.","tags":["precision-analog","audio"],"severity":"major"},{"id":"pcb-gnd-1","text":"Copper pours have no unconnected islands","hint":"Floating copper can act as an antenna. Remove islands or stitch them to ground with vias.","tags":[],"severity":"major"},{"id":"pcb-gnd-2","text":"Plane necks between regions are wide enough for the current they carry","hint":"Narrow plane necks create hot spots and voltage drop. Check every place a pour narrows between vias or around cut-outs.","tags":[],"severity":"major"},{"id":"pcb-gnd-3","text":"Power planes are pulled back from the board edge relative to ground","hint":"Rule of thumb: pull power planes back from the board edge relative to the ground plane to reduce edge radiation (often called the 20H rule). Treat this as guidance, not a hard limit.","tags":[],"severity":"major"},{"id":"pcb-gnd-4","text":"Each power island is large enough and connected with enough vias for its current","hint":"Count vias at each layer transition of high-current rails. Via current capacity depends on plating thickness and diameter.","tags":[],"severity":"major"}]},{"id":"p-rou","title":"General Routing","tags":[],"items":[{"id":"pr1","text":"All nets are fully routed, with no unrouted connections","hint":"Check the unrouted-net report is empty. Watch for plane connections that DRC treats as connected but are actually cut off.","tags":[],"severity":"critical"},{"id":"pr2","text":"Differential pairs are routed symmetrically with matched lengths","hint":"Keep both traces of a pair together with equal length and the same via transitions. Check the match tolerance against the interface spec.","tags":[],"severity":"major"},{"id":"pr3","text":"Fast signals have a continuous reference plane beneath them","hint":"Check every layer a fast signal uses, including after layer changes. A gap in the reference raises impedance and radiation.","tags":[],"severity":"major"},{"id":"pr4","text":"Return current paths are not interrupted by plane splits or via anti-pads","hint":"Look for anti-pads merging into slots under signal routes, especially in connector and BGA fields.","tags":[],"severity":"major"},{"id":"pr5","text":"Trace widths carry their current with margin for the allowed temperature rise","hint":"Size from IPC-2152 style charts using the actual copper weight and allowed rise. Inner layers run hotter than outer for the same width.","tags":[],"severity":"major"},{"id":"pr6","text":"Crosstalk-sensitive traces have enough spacing from aggressors","hint":"Rule of thumb: 3W spacing (three times the trace width, center to center) for sensitive or fast signals. Use simulation for tight designs.","tags":[],"severity":"major"},{"id":"pr7","text":"Fast signals use as few vias as possible","hint":"Each via adds a discontinuity and stub. Plan layer assignment to reduce layer changes on fast nets.","tags":[],"severity":"major"},{"id":"pr8","text":"Fast signals have no trace stubs","hint":"Stubs from unused branches, test pads or T-junctions cause reflections. Route daisy-chain or fly-by, or keep stubs very short.","tags":[],"severity":"major"},{"id":"pcb-rt-1","text":"Traces have no acute angles","hint":"Acute angles can trap etchant and narrow the trace. Use 45 degree or curved bends.","tags":[],"severity":"major"},{"id":"pcb-rt-2","text":"Clock traces are short, point-to-point and away from board edges and I/O","hint":"Clocks are a common emission source. Route them on inner layers between planes where possible.","tags":[],"severity":"major"},{"id":"pcb-rt-3","text":"Adjacent signal layers are routed orthogonally or with planes between them","hint":"Parallel routing on adjacent layers causes broadside coupling. Check layer pairs with no plane between them.","tags":[],"severity":"major"},{"id":"pcb-rt-4","text":"Traces entering pads leave from the pad end or center, not at an angle across the pad","hint":"Off-center or wide traces into small pads cause tombstoning and uneven solder. Keep entry width at or below the pad width.","tags":[],"severity":"major"},{"id":"pcb-rt-5","text":"Sensitive traces are not routed under noisy parts such as inductors, crystals or switch nodes","hint":"Magnetic and electric fields couple into traces directly underneath. Check the layers beneath every switching part.","tags":[],"severity":"major"},{"id":"pcb-rt-6","text":"Long parallel runs between aggressor and victim nets are avoided","hint":"Coupled length matters as much as spacing. Check long buses and traces that share a channel.","tags":[],"severity":"major"},{"id":"pcb-rt-7","text":"Unused copper fragments and dangling traces are removed","hint":"Leftover stubs act as antennas and confuse later revisions. Run the dangling-track check.","tags":[],"severity":"minor"}]},{"id":"p-hs","title":"High-Speed & Differential Pairs","tags":["high-speed"],"items":[{"id":"pcb-hs-1","text":"High-speed nets are routed on layers with the impedance defined in the stackup","hint":"Check each high-speed net only uses layers with a calculated geometry for its impedance class.","tags":[],"severity":"critical"},{"id":"pcb-hs-2","text":"Intra-pair skew compensation is placed near where the mismatch occurs","hint":"Compensating at the far end leaves the pair skewed along most of its length. Use small serpentines near the bend or pin that causes the mismatch, and check the result against the interface spec.","tags":[],"severity":"major"},{"id":"pcb-hs-3","text":"Pair-to-pair length matching meets the interface spec where required","hint":"Some interfaces (e.g. parallel lanes with a forwarded clock) need lane-to-lane matching. Others tolerate skew. Follow the spec or IC guide.","tags":[],"severity":"major"},{"id":"pcb-hs-4","text":"Differential pairs stay tightly coupled, with uncoupled length kept to a minimum","hint":"Breakouts at pins and around vias are the usual uncoupled sections. Keep them short and symmetric.","tags":[],"severity":"major"},{"id":"pcb-hs-5","text":"Spacing between differential pairs is enough to keep crosstalk acceptable","hint":"Rule of thumb: keep pair-to-pair spacing several times the intra-pair gap. Simulate or follow the IC's layout guide for dense routing.","tags":[],"severity":"major"},{"id":"pcb-hs-6","text":"Each high-speed signal via has a ground return via next to it","hint":"Ground vias beside signal vias keep the return path close at layer changes. For pairs, place them symmetrically.","tags":[],"severity":"major"},{"id":"pcb-hs-7","text":"Via stubs on multi-gigabit links are back-drilled or avoided by layer choice","hint":"Long via stubs cause resonances. Route to layers that leave short stubs, or specify back-drilling on the fab drawing.","tags":[],"severity":"major"},{"id":"pcb-hs-8","text":"AC coupling capacitors are placed per the interface spec, with matched pads and no stubs","hint":"Place both capacitors of a pair side by side. Consider a reference-plane cut-out under large pads to control impedance, per the IC guide.","tags":[],"severity":"major"},{"id":"pcb-hs-9","text":"Pad and connector transitions are designed to keep impedance close to target","hint":"Large SMT pads and connector pins are capacitive. Use anti-pads or plane cut-outs per the connector or IC layout guide.","tags":[],"severity":"major"},{"id":"pcb-hs-10","text":"Serpentine length tuning uses spacing and segment lengths that avoid self-coupling","hint":"Tight serpentines couple to themselves and shorten the effective delay. Rule of thumb: keep serpentine spacing at least a few trace widths.","tags":[],"severity":"major"},{"id":"pcb-hs-11","text":"Fiber weave effect is addressed on long, fast differential pairs","hint":"Pairs running parallel to glass fibers see skew. Route at a slight angle, use spread glass, or follow the fab's advice for the data rate.","tags":[],"severity":"major"},{"id":"pcb-hs-12","text":"Loss budget for each long high-speed channel is within the interface spec","hint":"Long traces on standard FR-4 may exceed the insertion loss budget. Estimate or simulate loss for the longest channels.","tags":[],"severity":"major"}]},{"id":"p-ddr","title":"DDR Routing","tags":["ddr"],"items":[{"id":"pcb-ddr-1","text":"DDR routing follows the memory controller vendor's layout guidelines","hint":"The SoC or FPGA vendor's layout guide sets topology, length rules and stackup. Check every rule against the layout.","tags":[],"severity":"critical"},{"id":"pcb-ddr-2","text":"Data byte lanes are routed on the same layer group as their strobe","hint":"Keep each DQ/DM byte lane and its DQS pair together, with the same number of vias, so they track over temperature.","tags":[],"severity":"major"},{"id":"pcb-ddr-3","text":"Data-to-strobe length matching within each byte lane meets the vendor tolerance","hint":"Check the match group report per byte lane. Include package pin delays if the vendor requires it.","tags":[],"severity":"major"},{"id":"pcb-ddr-4","text":"Address, command and control nets are matched to the clock within the vendor tolerance","hint":"Check the address/command group against CK in the length report.","tags":[],"severity":"major"},{"id":"pcb-ddr-5","text":"Address and command routing uses the specified topology (fly-by or T-branch)","hint":"DDR3 and later normally use fly-by for multiple devices. Check the device order matches the write-leveling setup.","tags":[],"severity":"major"},{"id":"pcb-ddr-6","text":"Fly-by termination resistors are at the end of the chain with short stubs","hint":"Place VTT termination after the last memory device and keep stubs from the main route short.","tags":[],"severity":"major"},{"id":"pcb-ddr-7","text":"VTT and VREF are routed and decoupled per the layout guide","hint":"VREF should be a quiet, well-decoupled trace away from aggressors. VTT needs a low-impedance plane or wide trace with local capacitors.","tags":[],"severity":"major"},{"id":"pcb-ddr-8","text":"Memory signals have a continuous reference plane with no splits beneath them","hint":"Check under the full length of every DDR net, including the breakout regions under the controller and memory.","tags":[],"severity":"major"},{"id":"pcb-ddr-9","text":"Memory clock pairs are routed as controlled-impedance differential pairs","hint":"Check width, gap and intra-pair skew of CK pairs against the vendor's rules.","tags":[],"severity":"major"},{"id":"pcb-ddr-10","text":"Spacing between byte lanes and between data and address groups meets the guide","hint":"Crosstalk between groups closes the timing eye. Follow the vendor's group-to-group spacing.","tags":[],"severity":"major"}]},{"id":"p-rf","title":"RF Layout","tags":["rf"],"items":[{"id":"pcb-rf-1","text":"RF traces are routed as controlled-impedance lines with the geometry from the stackup","hint":"Check width and gap for microstrip or coplanar waveguide against the calculation for the RF layer and its reference.","tags":[],"severity":"critical"},{"id":"pcb-rf-2","text":"Antenna placement and keepout follow the module or antenna datasheet","hint":"Antennas need specific copper-free areas, board-edge position and ground plane size. Copy the reference layout closely.","tags":[],"severity":"critical"},{"id":"pcb-rf-3","text":"No copper, components or traces sit inside the antenna keepout on any layer","hint":"The keepout applies to every layer, including ground pours. Check internal layers as well as the outer ones.","tags":[],"severity":"major"},{"id":"pcb-rf-4","text":"Matching network footprints are placed close to the antenna feed or RF pin","hint":"Leave room for a pi or L network even if parts are not fitted, so the antenna can be tuned on the final board.","tags":[],"severity":"major"},{"id":"pcb-rf-5","text":"RF traces have no sharp bends","hint":"Use curved or mitered bends. Keep RF traces short and avoid vias in the RF path unless designed for it.","tags":[],"severity":"major"},{"id":"pcb-rf-6","text":"Coplanar ground beside RF traces is stitched with a dense row of vias","hint":"Rule of thumb: space stitching vias a small fraction of a wavelength apart along RF lines. Follow the RF IC's layout guide where it gives a value.","tags":[],"severity":"major"},{"id":"pcb-rf-7","text":"RF ground plane under the radio IC and RF path is solid and unbroken","hint":"Do not route other signals through the RF reference layer under the RF section.","tags":[],"severity":"major"},{"id":"pcb-rf-8","text":"Radio IC exposed pad has the recommended number of ground vias","hint":"The exposed pad is often the RF ground and the main thermal path. Follow the datasheet via pattern.","tags":[],"severity":"major"},{"id":"pcb-rf-9","text":"Shield can footprint, if used, is continuous and well grounded","hint":"Shield frames need a solid ground ring with stitching vias. Check that tall parts fit under the can.","tags":[],"severity":"major"},{"id":"pcb-rf-10","text":"Digital and switching circuits are kept away from the RF section and antenna","hint":"Clocks, DC-DC converters and display interfaces can desense the receiver. Keep them physically separate.","tags":[],"severity":"major"},{"id":"pcb-rf-11","text":"RF test connector or test point footprint is provided for conducted measurements","hint":"A switched RF connector or a pad for a pigtail makes conducted power and sensitivity tests possible for certification and debug.","tags":[],"severity":"major"}]},{"id":"p-ana","title":"Analog & Mixed-Signal Layout","tags":["precision-analog","audio"],"items":[{"id":"pcb-ana-1","text":"High-impedance analog inputs are short and kept away from digital and switching traces","hint":"Picoamp or high-gain inputs pick up coupling easily. Route them on the shortest path with ground on either side.","tags":[],"severity":"major"},{"id":"pcb-ana-2","text":"Guard rings surround high-impedance input nodes where leakage matters","hint":"Drive a guard at the same potential as the input to cut surface leakage. Leave it out of the solder mask if the datasheet suggests it.","tags":[],"severity":"major"},{"id":"pcb-ana-3","text":"Current sense resistors use Kelvin connections","hint":"Take sense traces from the inside edges of the resistor pads, routed as a pair, so the measurement excludes the solder joint and trace resistance.","tags":[],"severity":"major"},{"id":"pcb-ana-4","text":"ADC and DAC reference pins are decoupled at the pin with short loops","hint":"Reference noise feeds straight into the conversion result. Place the reference capacitor as close as the datasheet shows.","tags":[],"severity":"major"},{"id":"pcb-ana-5","text":"Analog and digital sections of each ADC/DAC are placed per the datasheet","hint":"Place the converter so analog pins face the analog section and digital pins face the digital section.","tags":[],"severity":"major"},{"id":"pcb-ana-6","text":"Differential analog inputs are routed as a symmetric pair","hint":"Matching length and environment keeps common-mode rejection. Route both traces together over the same reference.","tags":[],"severity":"major"},{"id":"pcb-ana-7","text":"Thermal gradients across precision parts are minimized","hint":"Heat sources near references, thermocouples or matched resistors cause drift. Keep matched parts together and away from hot parts.","tags":[],"severity":"major"},{"id":"pcb-ana-8","text":"Sensitive analog nets are not routed beneath digital buses or switching regulators","hint":"Check every layer beneath the analog path, not only the top layer.","tags":[],"severity":"major"},{"id":"pcb-ana-9","text":"Audio input and output grounds return to the intended point","hint":"Speaker and headphone return currents can modulate the input ground. Route high-current audio returns separately from input references.","tags":[],"severity":"minor"}]},{"id":"p-hc","title":"High-Current & Thermal","tags":["high-current","motor","battery"],"items":[{"id":"pcb-hc-1","text":"High-current paths have enough copper width or area for their current","hint":"Check every high-current path, including through connectors, fuses and switches, against IPC-2152 style data for the copper weight used.","tags":[],"severity":"critical"},{"id":"pcb-hc-2","text":"Vias carrying high current are numerous enough for the load","hint":"Each via carries limited current. Use multiple vias at layer changes and check against plating thickness.","tags":[],"severity":"major"},{"id":"pcb-hc-3","text":"Power stage component placement keeps high di/dt loops small","hint":"Place half-bridge FETs, the DC-link capacitor and gate drivers so the commutation loop is as small as possible.","tags":[],"severity":"major"},{"id":"pcb-hc-4","text":"Gate drive traces are short and routed with their return","hint":"Route gate and source return as a pair to reduce loop inductance and ringing.","tags":[],"severity":"major"},{"id":"pcb-hc-5","text":"Thermal vias are placed under exposed pads and hot components","hint":"Use the datasheet's thermal via pattern. Specify via fill or tenting if solder wicking into open vias is a concern.","tags":[],"severity":"major"},{"id":"pcb-hc-6","text":"Thermal reliefs are not used where a part relies on the copper for heat sinking","hint":"Spokes reduce heat transfer. Hot parts often need solid connections even if soldering takes more heat.","tags":[],"severity":"major"},{"id":"pcb-hc-7","text":"Heatsink and thermal-pad contact areas are free of tall parts and solder mask where needed","hint":"Exposed copper or a flat area may be needed for a thermal pad or clip-on heatsink.","tags":[],"severity":"major"},{"id":"pcb-hc-8","text":"Current shunts and their Kelvin traces are placed away from heat sources","hint":"Shunt resistance changes with temperature. Keep sense traces away from the high-current path.","tags":[],"severity":"major"},{"id":"pcb-hc-9","text":"Connectors and terminal blocks are rated and placed for the current, with wide copper to each pin","hint":"Spread current across all connector pins assigned to the rail. Thin traces to a connector pin are a common hot spot.","tags":[],"severity":"major"},{"id":"pcb-hc-10","text":"Battery connection traces can survive a short circuit until the protection trips","hint":"Battery short-circuit current can be very high. Check the copper and fuse withstand the energy before the protection acts.","tags":["battery"],"severity":"major"}]},{"id":"p-iso","title":"Creepage, Clearance & Isolation","tags":["mains","medical"],"items":[{"id":"pcb-iso-1","text":"Creepage between isolated circuits meets the applicable safety standard on every layer","hint":"Take values from the applicable standard's tables for the working voltage, pollution degree and material group. Measure along the surface, including around slots.","tags":[],"severity":"critical"},{"id":"pcb-iso-2","text":"Clearance through air between isolated circuits meets the applicable safety standard","hint":"Clearance is measured in a straight line through air. Include parts that overhang the board and the enclosure.","tags":[],"severity":"critical"},{"id":"pcb-iso-3","text":"Isolation barrier is clear of all copper, vias and pours on every layer","hint":"Check internal layers. A pour or via inside the barrier on any layer defeats the isolation.","tags":[],"severity":"critical"},{"id":"pcb-iso-4","text":"Isolation slots are used where creepage cannot be met on the surface","hint":"Slots increase creepage distance. Check the slot width and position against the requirement and fab capability.","tags":[],"severity":"major"},{"id":"pcb-iso-5","text":"Isolating components (optocouplers, transformers, isolators) straddle the barrier","hint":"Check that the component's own creepage and the board creepage both meet the requirement.","tags":[],"severity":"major"},{"id":"pcb-iso-6","text":"Primary-side and secondary-side components are clearly grouped on each side of the barrier","hint":"A part from one side placed on the other is an easy error. Mark the barrier on silkscreen or the assembly layer.","tags":[],"severity":"major"},{"id":"pcb-iso-7","text":"Mains input traces, fuses and protection parts have the required spacing to each other and to chassis","hint":"Include spacing between line and neutral as well as to protective earth. Use the applicable standard's tables.","tags":[],"severity":"major"},{"id":"pcb-iso-8","text":"Protective earth connections are sized and fastened as the safety standard requires","hint":"Earth connections often need specific copper area and fastening. Check with the safety engineer.","tags":[],"severity":"major"},{"id":"pcb-iso-9","text":"High-voltage areas are marked on the silkscreen","hint":"A warning symbol or outline around hazardous voltage areas helps during test and service.","tags":[],"severity":"minor"}]},{"id":"p-emc","title":"EMC & ESD Layout","tags":[],"items":[{"id":"pcb-emc-1","text":"ESD protection devices are placed at the connector, before any other component","hint":"The ESD path should go from connector pin to protection device to ground with the shortest possible trace. Route the protected signal through the device pad.","tags":[],"severity":"major"},{"id":"pcb-emc-2","text":"ESD protection has a short, low-inductance connection to ground","hint":"Use multiple vias directly at the ground pad of the protection device.","tags":[],"severity":"major"},{"id":"pcb-emc-3","text":"I/O connector shields connect to chassis or ground as the grounding plan intends","hint":"Check the shield connection: direct, through a capacitor, or through an RC network. Follow the system grounding plan.","tags":[],"severity":"major"},{"id":"pcb-emc-4","text":"Filters on I/O lines are placed at the connector","hint":"Common-mode chokes and ferrites only work if they sit between the noise source and the cable.","tags":[],"severity":"major"},{"id":"pcb-emc-5","text":"Noisy circuits are kept away from I/O connectors and cables","hint":"Cables act as antennas. Keep clocks and switching regulators away from the connector area.","tags":[],"severity":"major"},{"id":"pcb-emc-6","text":"Chassis ground and signal ground are separated or joined as the grounding plan intends","hint":"Check the chassis pour, gap and any bridging capacitors match the plan.","tags":[],"severity":"major"},{"id":"pcb-emc-7","text":"Exposed metal (buttons, connectors, screws) has an ESD discharge path that avoids sensitive circuits","hint":"An ESD strike must flow to ground without passing near sensitive ICs. Check the path from each user touch point.","tags":[],"severity":"major"},{"id":"pcb-emc-8","text":"Reset and other sensitive control lines are kept short and away from board edges","hint":"ESD and fast transients can trigger resets through long traces. Add filtering near the IC pin if they must be long.","tags":[],"severity":"major"},{"id":"pcb-emc-9","text":"Footprints for optional EMC parts (ferrites, capacitors, RC snubbers) are provided on risky nets","hint":"Spare footprints let the team fix EMC problems at pre-compliance testing without a respin.","tags":["regulatory"],"severity":"minor"}]},{"id":"p-flex","title":"Flex & Rigid-Flex","tags":["flex"],"items":[{"id":"pcb-flex-1","text":"Bend regions have no vias, pads or components","hint":"Vias and pads in a bend crack with flexing. Keep them in rigid or stiffened areas.","tags":[],"severity":"critical"},{"id":"pcb-flex-2","text":"Bend radius meets the fab's guidelines for the flex thickness and layer count","hint":"Bend radius depends on flex thickness and whether the bend is static or dynamic. Use the fab's design guide.","tags":[],"severity":"major"},{"id":"pcb-flex-3","text":"Traces in bend regions run perpendicular to the bend line","hint":"Traces at an angle to the bend line take uneven strain. Route straight across the bend.","tags":[],"severity":"major"},{"id":"pcb-flex-4","text":"Traces on adjacent flex layers are staggered, not stacked, through bends","hint":"Stacked traces form an I-beam that stiffens the flex and concentrates stress.","tags":[],"severity":"major"},{"id":"pcb-flex-5","text":"Ground planes in flex areas use hatched copper where flexibility is needed","hint":"Solid copper stiffens the flex. Check that a hatched plane still gives the needed impedance and shielding.","tags":[],"severity":"major"},{"id":"pcb-flex-6","text":"Pad and trace junctions in flex areas use teardrops or fillets","hint":"Teardrops reduce stress at the junction and help coverlay adhesion.","tags":[],"severity":"major"},{"id":"pcb-flex-7","text":"Stiffeners are defined with material, thickness and position on the drawing","hint":"Stiffeners under connectors and components need to be on the fab drawing, with adhesive type.","tags":[],"severity":"major"},{"id":"pcb-flex-8","text":"Rigid-to-flex transitions keep copper features away from the transition line","hint":"The transition zone sees the most stress. Follow the fab's keepout from the rigid edge.","tags":[],"severity":"major"},{"id":"pcb-flex-9","text":"Coverlay openings are sized and positioned per the fab's guidelines","hint":"Coverlay openings are less accurate than solder mask. Check the fab's minimum opening and registration tolerance.","tags":[],"severity":"major"},{"id":"pcb-flex-10","text":"Flex outline has radiused internal corners and tear-stop features","hint":"Sharp internal corners on flex tear easily. Add radii and copper tear-stops at slits.","tags":[],"severity":"minor"}]},{"id":"p-bga","title":"BGA Fanout & HDI","tags":["bga","hdi"],"items":[{"id":"pcb-bga-1","text":"BGA fanout pattern follows the package vendor's recommended via and escape strategy","hint":"Check the vendor's escape routing guide for via size, pad size and number of layers needed.","tags":[],"severity":"major"},{"id":"pcb-bga-2","text":"BGA pad type (solder mask defined or non-solder mask defined) matches the vendor recommendation","hint":"Pad type affects joint reliability. Use the package datasheet.","tags":[],"severity":"major"},{"id":"pcb-bga-3","text":"Dog-bone vias are fully covered or plugged so solder doesn't wick away from the ball","hint":"Open vias next to BGA pads can steal solder. Tent, plug or mask them per the assembler's advice.","tags":[],"severity":"major"},{"id":"pcb-bga-4","text":"Via-in-pad is filled and plated over (capped) where used","hint":"Open via-in-pad wicks solder and causes voids. Specify filled and capped vias on the fab drawing.","tags":["hdi"],"severity":"major"},{"id":"pcb-bga-5","text":"Microvia aspect ratio and stacking are within the fab's capability","hint":"Stacked microvias can be less reliable than staggered ones. Check the fab's rules for stacking and aspect ratio.","tags":["hdi"],"severity":"major"},{"id":"pcb-bga-6","text":"Sequential lamination build-up is described clearly on the fab drawing","hint":"Show which layers each microvia and buried via spans, with drill tables per span.","tags":["hdi"],"severity":"major"},{"id":"pcb-bga-7","text":"Power and ground balls have enough vias to the planes","hint":"Share vias between balls only if the vendor allows it. Check the current per via.","tags":[],"severity":"major"},{"id":"pcb-bga-8","text":"Decoupling capacitors under the BGA are placed and connected per the vendor's guide","hint":"Bottom-side capacitors under a BGA need short via connections to the power balls.","tags":[],"severity":"major"},{"id":"pcb-bga-9","text":"Unused BGA balls are handled as the datasheet requires","hint":"Some unused balls must be tied to ground or left floating. Check the pin list.","tags":[],"severity":"minor"}]},{"id":"p-silk","title":"Silkscreen, Marking & Polarity","tags":[],"items":[{"id":"pcb-silk-1","text":"Pin 1 is marked clearly for every IC and connector","hint":"The mark should be visible after the part is placed, not hidden under the body.","tags":[],"severity":"major"},{"id":"pcb-silk-2","text":"Reference designators are readable and placed next to their parts","hint":"Use a consistent orientation, with at most two reading directions.","tags":[],"severity":"minor"},{"id":"pcb-silk-3","text":"Silkscreen text size meets the fab's minimum line width and height","hint":"Text below the fab's limits smudges. Use the fab's minimum values.","tags":[],"severity":"minor"},{"id":"pcb-silk-4","text":"Board name, part number and revision are on the silkscreen or copper","hint":"Every board should be traceable. Copper text survives harsh processing better than silk.","tags":[],"severity":"major"},{"id":"pcb-silk-5","text":"Space for a serial number or barcode label is provided","hint":"Leave a clear area for a label or laser marking, sized for the label or code.","tags":["production"],"severity":"minor"},{"id":"pcb-silk-6","text":"Connector pin functions and voltage markings are on the silkscreen where users connect cables","hint":"Mark supply inputs with voltage and polarity, and mark user-wired terminals.","tags":[],"severity":"major"},{"id":"pcb-silk-7","text":"Regulatory and safety markings required on the board are present","hint":"Some products need certification marks, UL recognition or warning symbols on the PCB. Confirm with the compliance plan.","tags":["regulatory","mains","medical"],"severity":"minor"},{"id":"pcb-silk-8","text":"Test points, jumpers and debug headers are labeled","hint":"Labels speed bring-up and test. Use net names or short descriptions.","tags":[],"severity":"minor"}]},{"id":"p-tes","title":"Test Points & DFT","tags":[],"items":[{"id":"pt1","text":"Test points are provided for all critical signals and power rails","hint":"Every power rail, reset, clock and key interface should be probe-able on the assembled board.","tags":[],"severity":"major"},{"id":"pt2","text":"JTAG/SWD/debug header is accessible with the board installed","hint":"Check access in the enclosure. A debug port that needs disassembly slows bring-up and field debug.","tags":[],"severity":"major"},{"id":"pt3","text":"In-circuit test (bed-of-nails) access is maintained for all testable nets","hint":"Agree the test strategy with the contract manufacturer. Missing access means untested nets in production.","tags":[],"severity":"major"},{"id":"pt4","text":"Polarity markers are visible on the silkscreen for all polarized components","hint":"Check every diode, LED, electrolytic and tantalum capacitor. The marking must be visible after assembly.","tags":[],"severity":"major"},{"id":"pcb-dft-1","text":"Test points are on one side of the board where the fixture design requires","hint":"Single-sided fixtures are cheaper. Put all test points on the side the fixture probes.","tags":["production"],"severity":"major"},{"id":"pcb-dft-2","text":"Test point size and spacing meet the test fixture's probe requirements","hint":"Use the test house's minimum pad size and pitch. Small pads cause unreliable contact.","tags":["production"],"severity":"major"},{"id":"pcb-dft-3","text":"Test points are kept clear of tall components","hint":"Probes need clear access. Tall parts nearby block probes and fixture plates.","tags":[],"severity":"major"},{"id":"pcb-dft-4","text":"Programming and debug connectors are placed for both bench and production use","hint":"Consider a pogo-pin pad pattern for production programming in addition to a bench header.","tags":[],"severity":"major"},{"id":"pcb-dft-5","text":"Ground test points are near each group of signal test points","hint":"Short ground leads are needed for clean scope measurements.","tags":[],"severity":"major"},{"id":"pcb-dft-6","text":"Zero-ohm links or jumpers are provided to isolate rails for bring-up","hint":"Breaking a rail lets you measure current and isolate faults during bring-up.","tags":[],"severity":"major"}]},{"id":"p-man","title":"Manufacturability (DFM)","tags":[],"items":[{"id":"pm1","text":"Minimum trace width and spacing are within the fabricator's capability","hint":"Compare against the capability sheet for the copper weight on each layer. Finer features usually cost more.","tags":[],"severity":"critical"},{"id":"pm2","text":"Minimum drill size and aspect ratio are within the fabricator's capability","hint":"Aspect ratio is board thickness over drill diameter. Check against the fab limit for through vias and microvias separately.","tags":[],"severity":"critical"},{"id":"pm3","text":"Annular ring is sufficient for all vias and plated through-hole pads","hint":"Set annular ring per fab capability and the IPC-6012 class ordered. Drill wander eats into small rings.","tags":[],"severity":"major"},{"id":"pm4","text":"Solder mask slivers between pads are eliminated","hint":"Slivers below the fab's minimum web flake off. Gang-relieve fine-pitch pads if the web cannot be held.","tags":[],"severity":"major"},{"id":"pm5","text":"Courtyards and silkscreen do not overlap pads or conflict with adjacent parts","hint":"Overlapping courtyards mean parts will collide. Run the courtyard check and the silk-to-pad check.","tags":[],"severity":"minor"},{"id":"pm6","text":"Fiducial marks are present on each populated side for automated assembly","hint":"Use global fiducials on the board or panel, and local fiducials near fine-pitch parts if the assembler asks. Keep a clear mask opening around them.","tags":[],"severity":"major"},{"id":"pm7","text":"Tooling holes are present and correctly sized for panelization","hint":"Use the assembler's tooling hole size and position, usually on the panel rails.","tags":[],"severity":"major"},{"id":"pcb-dfm-1","text":"Solder mask dams between fine-pitch pads meet the fab's minimum","hint":"Mask dams prevent solder bridges. Check the dam width against the fab capability.","tags":[],"severity":"major"},{"id":"pcb-dfm-2","text":"Solder mask expansion is set per fab capability","hint":"Too small and mask may encroach on pads, too large and adjacent pads merge. Use the fab's registration tolerance.","tags":[],"severity":"major"},{"id":"pcb-dfm-3","text":"Via tenting, plugging or filling is specified on the fab drawing","hint":"State which vias are tented, plugged or filled. Partially tented vias can trap chemicals.","tags":[],"severity":"major"},{"id":"pcb-dfm-4","text":"Copper has no acid traps","hint":"Acute angles between traces trap etchant. Most CAD tools have a check for this.","tags":[],"severity":"major"},{"id":"pcb-dfm-5","text":"Copper has no slivers below the fab's minimum width","hint":"Thin copper slivers from pours can lift and short. Set a minimum pour width and remove slivers.","tags":[],"severity":"major"},{"id":"pcb-dfm-6","text":"Copper is balanced across each layer and between layers","hint":"Uneven copper causes warp and plating thickness variation. Add copper thieving in empty areas if the fab agrees.","tags":[],"severity":"major"},{"id":"pcb-dfm-7","text":"Panelization is agreed with the assembler, including rails, breakaway method and panel size","hint":"Check the panel drawing with the assembler. Parts near tabs or V-scores need extra clearance.","tags":["production"],"severity":"major"},{"id":"pcb-dfm-8","text":"Paste layer is correct, including paste reduction on large pads and exposed pads","hint":"Exposed pads usually need a windowed paste pattern to avoid voids and float. Follow the datasheet or assembler's advice.","tags":[],"severity":"major"},{"id":"pcb-dfm-9","text":"Gerber, drill and fab drawing outputs have been checked in a Gerber viewer","hint":"Generate from the final database, then check every output layer. Confirm drill files match the drill table.","tags":[],"severity":"major"},{"id":"pcb-dfm-10","text":"IPC-6012 class and acceptance criteria are stated on the fab drawing","hint":"State Class 2 or Class 3 as the product needs. This drives annular ring, plating and inspection.","tags":[],"severity":"minor"}]}]},{"id":"assembly","title":"Assembly & BOM Review","short":"Assembly","version":2,"description":"Checks that the BOM, footprints, placement data, stencil, soldering process and assembly documentation let an assembler build the board right first time.","sections":[{"id":"a-bom","title":"Bill of Materials","tags":[],"items":[{"id":"ab1","text":"BOM is exported from the schematic at the release revision, with no manual edits","hint":"Hand-edited BOMs drift from the design. Regenerate from the CAD tool and diff against the previous release BOM.","tags":[],"severity":"major"},{"id":"ab2","text":"Every component has a manufacturer part number (MPN) assigned","hint":"Without an MPN the assembler picks a part for you. Generic values like \"10k 0402\" are not enough for a build.","tags":[],"severity":"major"},{"id":"ab3","text":"Every line has at least one approved distributor with stock and lead time checked","hint":"Check at the build quantity, not just a single unit. Record the date the check was made.","tags":[],"severity":"major"},{"id":"ab4","text":"Alternate or equivalent parts are listed where applicable","hint":"Confirm each alternate is a true form-fit-function match: footprint, pinout, voltage rating, tolerance and temperature range.","tags":[],"severity":"minor"},{"id":"ab5","text":"No obsolete, NRND or EOL parts are used without an approved substitute","hint":"Check lifecycle status at the manufacturer or a distributor shortly before release; status changes without notice.","tags":[],"severity":"major"},{"id":"ab6","text":"Per-board quantities match the reference designator count, with DNP items clearly flagged","hint":"Use a dedicated DNP field rather than notes in the description, so the assembler's import picks it up.","tags":[],"severity":"major"},{"id":"ab7","text":"BOM reference designators match the schematic exactly","hint":"Look for missing, duplicated or renamed refdes after back-annotation.","tags":[],"severity":"major"},{"id":"asm-bom-1","text":"Every line has a complete description: value, tolerance, rating, dielectric and package","hint":"\"10 µF 0805\" is ambiguous: X7R vs Y5V and the voltage rating change the effective capacitance under DC bias.","tags":[],"severity":"major"},{"id":"asm-bom-2","text":"The package of every MPN matches the footprint used on the PCB","hint":"An 0402 part ordered for an 0603 footprint, or a QFN ordering code for an SOIC footprint, stops the build.","tags":[],"severity":"critical"},{"id":"asm-bom-3","text":"Each build variant has its own BOM, identified by an assembly part number","hint":"Variants managed by memory get built wrong. Make the variant visible on the BOM, the assembly drawing and ideally the board label.","tags":[],"severity":"major"},{"id":"asm-bom-4","text":"Single-source parts are identified and the supply risk accepted","hint":"Flag them for the project lead; consider a second-source footprint or a buffer stock for critical ones.","tags":[],"severity":"major"},{"id":"asm-bom-5","text":"Long-lead parts are identified and ordered or reserved early","hint":"Treat anything well beyond typical distributor lead time (rule of thumb: over ~12 weeks) as a schedule risk.","tags":[],"severity":"major"},{"id":"asm-bom-6","text":"Consigned (customer-supplied) and turnkey parts are identified line by line","hint":"Assemblers need to know which parts they buy and which arrive in a kit, or lines end up short or double-bought.","tags":[],"severity":"major"},{"id":"asm-bom-7","text":"Mechanical items (fasteners, standoffs, heatsinks, shields, labels) are on the BOM","hint":"Non-electrical parts are often missing because they have no schematic symbol. Add them as BOM-only items.","tags":[],"severity":"major"},{"id":"asm-bom-8","text":"Programmable parts are identified with the firmware image and version to load","hint":"Say whether the assembler programs them pre-placement, in-circuit, or if programming happens at test.","tags":[],"severity":"major"},{"id":"asm-bom-9","text":"Parts in automotive builds are AEC-Q qualified where required","hint":"Check the exact ordering code: the AEC-Q grade is often a suffix, and the standard part is not qualified.","tags":["automotive"],"severity":"major"}]},{"id":"a-pkg","title":"Packages & Footprints","tags":[],"items":[{"id":"ap1","text":"Every footprint is verified against the manufacturer's datasheet land pattern","hint":"Check pad size, pitch, body outline and any exposed pad. Library parts copied from other projects are a common source of error.","tags":[],"severity":"critical"},{"id":"ap2","text":"Component heights are checked against mechanical constraints (lid, heatsink, mating boards)","hint":"Use 3D models or the max-height dimension from the datasheet, not the typical value.","tags":[],"severity":"major"},{"id":"ap3","text":"SMD and through-hole components are clearly distinguished in the BOM and assembly drawing","hint":"The assembler routes each to a different process; mixing them up adds cost and delay.","tags":[],"severity":"minor"},{"id":"ap4","text":"Polarized components (diodes, electrolytics, ICs) have their orientation marked","hint":"Mark polarity on silkscreen and the assembly drawing so it is still visible after the part is placed.","tags":[],"severity":"major"},{"id":"ap5","text":"Fine-pitch and BGA components are reviewed for reflow profile compatibility","hint":"Large BGAs and small passives on the same board may need a compromise profile; check with the assembler.","tags":[],"severity":"major"},{"id":"asm-fp-1","text":"Land patterns follow IPC-7351 with the density level (most, nominal, least) chosen deliberately","hint":"Nominal suits most reflow builds; least for very dense boards; most for hand soldering or wave.","tags":[],"severity":"minor"},{"id":"asm-fp-2","text":"Pin 1 is marked on silkscreen and the assembly layer, outside the part body","hint":"A pin-1 dot hidden under the body cannot be checked after placement.","tags":[],"severity":"major"},{"id":"asm-fp-3","text":"Footprint pad numbers match the schematic symbol pin numbers for every unique part","hint":"Watch SOT-23 transistors and regulators (pinouts vary by vendor), connectors and mirrored headers.","tags":[],"severity":"critical"},{"id":"asm-fp-4","text":"The footprint matches the exact package variant of the ordered MPN","hint":"One IC often comes in QFN, DFN and WSON variants with different pad sizes or exposed pads. Check the ordering code.","tags":[],"severity":"major"},{"id":"asm-fp-5","text":"Thermal vias in exposed pads are tented, plugged or filled to stop solder wicking","hint":"Open vias drain solder away from the joint and cause voids or a lifted part. Agree the treatment with fab and assembler.","tags":[],"severity":"major"},{"id":"asm-fp-6","text":"Connector footprints include mechanical retention features (hold-down pads, bosses, pegs)","hint":"Surface-mount connectors without anchoring tear off under cable load.","tags":[],"severity":"major"},{"id":"asm-fp-7","text":"BGA pads are mask-defined or copper-defined as the package datasheet recommends","hint":"Mixing the two on one package gives uneven joints.","tags":["bga"],"severity":"major"},{"id":"asm-fp-8","text":"Fine-pitch pads have solder mask dams between them, where fab capability allows","hint":"Without a dam, bridges are more likely. If the web is below fab minimum, agree a gang relief instead.","tags":[],"severity":"major"},{"id":"asm-fp-9","text":"No open vias are placed in SMD pads unless filled and capped","hint":"Open via-in-pad wicks solder and gives voids or starved joints.","tags":[],"severity":"major"},{"id":"asm-fp-10","text":"Small passives have balanced copper connections on both pads","hint":"One pad on a plane and the other on a thin trace heats unevenly and tombstones. Use thermal relief on plane connections.","tags":[],"severity":"major"}]},{"id":"a-pnp","title":"Pick-and-Place & Centroid","tags":[],"items":[{"id":"asm-pnp-1","text":"Centroid file lists refdes, X, Y, rotation and side for every placed part","hint":"Generate it from the release PCB file, not an earlier one.","tags":[],"severity":"critical"},{"id":"asm-pnp-2","text":"DNP parts are handled in the centroid file the same way as in the BOM","hint":"Either remove DNP parts or flag them; a mismatch between BOM and centroid causes placement of parts meant to be left off.","tags":[],"severity":"major"},{"id":"asm-pnp-3","text":"Centroid file units and origin are stated and match the board origin on the drawing","hint":"Use mm and a board origin at a defined corner or datum, not an arbitrary CAD origin.","tags":[],"severity":"major"},{"id":"asm-pnp-4","text":"The rotation convention is confirmed with the assembler","hint":"CAD library zero orientation often differs from the IPC-7351 convention. Ask for a first-article check of rotations.","tags":[],"severity":"major"},{"id":"asm-pnp-5","text":"Each part's placement origin is at the body center","hint":"Footprints with the origin at pin 1 or a corner give offset placements unless the assembler corrects them.","tags":[],"severity":"major"},{"id":"asm-pnp-6","text":"The bottom-side coordinate convention (mirrored or viewed from top) is stated","hint":"Bottom-side X and rotation are frequently misinterpreted; say which view the numbers are in.","tags":[],"severity":"major"},{"id":"asm-pnp-7","text":"The board (or panel) has at least three global fiducials, not in a straight line","hint":"Rule of thumb; follow the assembler's preferred fiducial size and position.","tags":[],"severity":"major"},{"id":"asm-pnp-8","text":"Local fiducials are placed near fine-pitch and BGA parts where the assembler asks for them","hint":"Local fiducials correct for board stretch around critical parts.","tags":["bga"],"severity":"minor"},{"id":"asm-pnp-9","text":"Components keep clear of board edges used for conveyor rails, or a panel rail is added","hint":"Clearance needed depends on the assembler's line; ask before layout is frozen.","tags":[],"severity":"major"}]},{"id":"a-stn","title":"Stencil & Paste","tags":[],"items":[{"id":"asm-stn-1","text":"The paste layer has apertures on every pad to be soldered and none on pads that must stay bare","hint":"Remove paste from test points, fiducials, edge fingers and hand-solder pads.","tags":[],"severity":"major"},{"id":"asm-stn-2","text":"Stencil thickness is agreed with the assembler for the finest-pitch part","hint":"Common rule of thumb is 0.10–0.13 mm (4–5 mil); the assembler will confirm for your part mix.","tags":[],"severity":"major"},{"id":"asm-stn-3","text":"Aperture area ratio is acceptable for the smallest apertures","hint":"Rule of thumb: an area ratio of about 0.66 or more for reliable release. Check with the stencil supplier for 0201 and fine-pitch BGA.","tags":[],"severity":"major"},{"id":"asm-stn-4","text":"Exposed-pad apertures are split into a windowpane pattern to limit paste coverage","hint":"Follow the package datasheet; too much paste floats the part and opens the perimeter joints.","tags":[],"severity":"major"},{"id":"asm-stn-5","text":"Paste reductions on fine-pitch and BGA pads follow the assembler's recommendation","hint":"Many assemblers apply their own aperture rules; state whether yours or theirs take priority.","tags":[],"severity":"minor"},{"id":"asm-stn-6","text":"Parts needing extra paste (large connectors, shields) are covered by a step stencil or overprint","hint":"A single thickness rarely suits both 0.4 mm pitch parts and large connector tabs.","tags":[],"severity":"minor"},{"id":"asm-stn-7","text":"Solder paste type is specified: alloy, powder type and flux chemistry","hint":"No-clean vs water-soluble flux affects cleaning and coating. Finer powder types suit finer pitch.","tags":[],"severity":"major"}]},{"id":"a-sol","title":"Soldering Process","tags":[],"items":[{"id":"asm-sol-1","text":"Every part's peak temperature and time-above-liquidus limits suit the planned reflow profile","hint":"Check connectors, crystals, electrolytics, LEDs and plastic switches, which often have lower limits than ICs.","tags":[],"severity":"critical"},{"id":"asm-sol-2","text":"The assembler's dry storage and bake handling is confirmed for MSL 3 and higher parts","hint":"Parts out of the bag beyond floor life crack or delaminate in reflow (popcorning).","tags":[],"severity":"major"},{"id":"asm-sol-3","text":"Bottom-side parts are light enough to stay in place during the second reflow, or are glued","hint":"Check heavy inductors, connectors and large ICs on the first-reflowed side with the assembler.","tags":[],"severity":"major"},{"id":"asm-sol-4","text":"Parts rated for only one reflow cycle are placed on the second-reflowed side","hint":"Some connectors, LEDs and sensors only allow a single reflow; check datasheets.","tags":[],"severity":"major"},{"id":"asm-sol-5","text":"Every through-hole part has a defined soldering process","hint":"Wave, selective, pin-in-paste or hand solder. Each has its own pad and keep-out requirements.","tags":[],"severity":"major"},{"id":"asm-sol-6","text":"Bottom-side keep-outs around through-hole pins suit selective or wave soldering","hint":"Selective nozzles need clearance from nearby SMD parts per assembler capability.","tags":[],"severity":"major"},{"id":"asm-sol-7","text":"Through-hole drill sizes give suitable clearance over the lead diameter","hint":"Too tight and leads won't insert; too loose and the barrel doesn't fill. Clearance is a rule of thumb; check with the assembler.","tags":[],"severity":"major"},{"id":"asm-sol-8","text":"Through-hole pins connected to planes have thermal relief for barrel fill","hint":"Solid plane connections sink heat and leave unfilled barrels, especially on thick or heavy-copper boards.","tags":[],"severity":"major"},{"id":"asm-sol-9","text":"Parts that can't be washed (open microphones, buzzers, MEMS sensors, unsealed switches) are identified","hint":"If a wash step is used, these parts must be fitted after washing or protected.","tags":[],"severity":"major"},{"id":"asm-sol-10","text":"BGA underfill or corner staking is decided for shock and vibration","hint":"Underfill hampers rework; decide deliberately and note it on the assembly drawing.","tags":["bga"],"severity":"major"}]},{"id":"a-asm","title":"Assembly Drawings & Instructions","tags":[],"items":[{"id":"aa1","text":"Assembly drawing (top and bottom views) is current and matches the PCB revision","hint":"Regenerate it from the release PCB file; old drawings with the right title block are a common trap.","tags":[],"severity":"major"},{"id":"aa2","text":"All DNP components are clearly marked on the assembly drawing","hint":"Show them hatched or listed per variant so an operator can see what to leave off.","tags":[],"severity":"major"},{"id":"aa3","text":"Special assembly notes are included (solder type, underfill, torque values)","hint":"Put the notes on the drawing itself, not just in an email to the assembler.","tags":[],"severity":"major"},{"id":"aa4","text":"Conformal coating requirements are specified where applicable","hint":"Say whether the board is coated, which material, and which areas are masked.","tags":[],"severity":"major"},{"id":"aa5","text":"Press-fit and hand-solder-only components are clearly identified","hint":"These need separate process steps; the assembler must plan them up front.","tags":[],"severity":"major"},{"id":"asm-adr-1","text":"The assembly drawing shows a readable reference designator for every part","hint":"Check at print scale. Dense areas may need a magnified detail view.","tags":[],"severity":"minor"},{"id":"asm-adr-2","text":"The board revision and assembly part number appear in the drawing title block","hint":"The assembly number identifies the variant; the PCB revision identifies the bare board.","tags":[],"severity":"major"},{"id":"asm-adr-3","text":"Programming and test steps are called out or a work instruction is referenced","hint":"Include firmware file names and versions, or point to the controlled document that has them.","tags":[],"severity":"minor"},{"id":"asm-adr-4","text":"Any rework wires or modifications are documented with routing and fixing method","hint":"Undocumented bodges are lost on the next build. Give a drawing per mod, with wire type and glue points.","tags":[],"severity":"major"},{"id":"asm-adr-5","text":"The cleaning requirement is specified: no-clean residue allowed, or wash required","hint":"Residue matters for coating adhesion, high-impedance circuits and RF.","tags":[],"severity":"major"},{"id":"asm-adr-6","text":"Label, serial number and marking locations are specified","hint":"Keep labels off vents, heat sources and areas that get coated.","tags":[],"severity":"minor"}]},{"id":"a-cot","title":"Conformal Coating & Potting","tags":["harsh-env","automotive"],"items":[{"id":"asm-cot-1","text":"The coating material type is chosen for the environment and recorded","hint":"Acrylic, silicone, urethane or parylene differ in moisture, chemical and temperature resistance and in reworkability.","tags":[],"severity":"major"},{"id":"asm-cot-2","text":"Coating keep-out areas are defined and masked","hint":"Connectors, test points, switches, sensor openings, heatsink interfaces and grounding contacts usually stay uncoated.","tags":[],"severity":"major"},{"id":"asm-cot-3","text":"Components are compatible with coating","hint":"Vented sensors, relays, trimmers, unsealed switches and some connectors are damaged or disabled by coating.","tags":[],"severity":"major"},{"id":"asm-cot-4","text":"The board is cleaned before coating to a level compatible with the coating","hint":"Flux residue under coating causes poor adhesion and can lead to corrosion or leakage.","tags":[],"severity":"major"},{"id":"asm-cot-5","text":"Potting compound stress and cure heat are checked against the components","hint":"Hard compounds can crack glass diodes and large ceramic capacitors through shrinkage or CTE mismatch.","tags":[],"severity":"major"},{"id":"asm-cot-6","text":"Tall or heavy parts are staked or adhesive-bonded for vibration","hint":"Electrolytics, inductors and large connectors fatigue their joints under vibration.","tags":[],"severity":"major"},{"id":"asm-cot-7","text":"Electrical testing is planned before coating or potting, or test access is kept","hint":"After potting, faults can't be diagnosed or reworked.","tags":[],"severity":"major"}]},{"id":"a-mec","title":"Press-fit & Mechanical Assembly","tags":[],"items":[{"id":"asm-mec-1","text":"Press-fit footprints use the connector manufacturer's finished hole size","hint":"Press-fit needs a tighter tolerance than ordinary plated holes; make sure the fab drawing calls it out.","tags":[],"severity":"critical"},{"id":"asm-mec-2","text":"Press-fit areas keep components out of the press tool and support keep-outs","hint":"Check the connector application spec for top and bottom keep-out zones.","tags":[],"severity":"major"},{"id":"asm-mec-3","text":"The surface finish is compatible with the press-fit pins","hint":"Connector datasheets list approved finishes; some pins aren't qualified on every finish.","tags":[],"severity":"major"},{"id":"asm-mec-4","text":"Fastener holes have keep-outs for screw heads, washers and tools","hint":"Check both sides of the board and the driver access path.","tags":[],"severity":"major"},{"id":"asm-mec-5","text":"Heatsink attachment, thermal interface material and clamping are specified","hint":"Name the TIM, its thickness and the fastener torque or clip part number.","tags":[],"severity":"major"},{"id":"asm-mec-6","text":"Board-to-board connector stack height and mating tolerance are checked","hint":"Add up connector heights, standoffs and tolerances against the datasheet's allowed mating range.","tags":[],"severity":"major"},{"id":"asm-mec-7","text":"Heavy or cable-loaded connectors have mechanical strain relief","hint":"Through-hole anchors, screws or brackets stop cable loads from reaching solder joints.","tags":[],"severity":"major"}]},{"id":"a-ins","title":"Inspection & Test","tags":[],"items":[{"id":"asm-ins-1","text":"AOI is planned and part markings and polarity indicators are visible to it","hint":"Ask the assembler whether AOI runs on every build and what it needs.","tags":["production"],"severity":"minor"},{"id":"asm-ins-2","text":"X-ray inspection is specified for BGAs and bottom-terminated components","hint":"Hidden joints can't be checked optically.","tags":["bga"],"severity":"major"},{"id":"asm-ins-3","text":"Void acceptance criteria for thermal pads and BGA balls are agreed","hint":"Reference IPC-A-610 or state a customer requirement; thermal pads may need a tighter limit for heat flow.","tags":[],"severity":"minor"},{"id":"asm-ins-4","text":"First-article inspection is requested for the first build","hint":"FAI catches rotation, polarity and wrong-part errors before the full batch is built.","tags":[],"severity":"major"},{"id":"asm-ins-5","text":"Test points are reachable after assembly for flying probe or ICT","hint":"Check that tall parts, shields and connectors don't block probe access.","tags":["production"],"severity":"major"},{"id":"asm-ins-6","text":"A functional test procedure or fixture is defined for production","hint":"Say what is tested, with which firmware, and what counts as a pass.","tags":["production"],"severity":"major"},{"id":"asm-ins-7","text":"Traceability is defined: serial number or lot recorded for each board","hint":"Link the serial number to the BOM revision, firmware version and test result.","tags":["production","medical","automotive"],"severity":"minor"}]},{"id":"a-qua","title":"Quality & Compliance","tags":[],"items":[{"id":"aq1","text":"All components meet RoHS / REACH requirements, or exceptions are documented","hint":"Check each MPN's compliance status, including mechanical items and cables.","tags":[],"severity":"major"},{"id":"aq2","text":"Moisture sensitivity level (MSL) is noted for applicable packages","hint":"Record MSL in the BOM so the assembler can plan storage and baking.","tags":[],"severity":"major"},{"id":"aq3","text":"ESD-sensitive components are identified and handling requirements noted","hint":"Especially important for RF front ends, unprotected MOSFET gates and lasers.","tags":[],"severity":"minor"},{"id":"aq4","text":"The IPC-A-610 acceptability class is specified for inspection","hint":"Class 2 for most products; Class 3 for high-reliability.","tags":[],"severity":"major"},{"id":"asm-qua-1","text":"The IPC-A-610 assembly class matches the IPC-6012 class on the fab drawing","hint":"A Class 3 assembly on a Class 2 bare board, or vice versa, is usually a mistake.","tags":[],"severity":"major"},{"id":"asm-qua-2","text":"Material declarations (RoHS, REACH SVHC) are collected for the compliance file","hint":"Distributor and manufacturer sites usually provide them per MPN.","tags":[],"severity":"minor"},{"id":"asm-qua-3","text":"The assembler holds the certification the product needs","hint":"For example ISO 13485 for medical or IATF 16949 for automotive.","tags":["medical","automotive"],"severity":"major"},{"id":"asm-qua-4","text":"All parts are bought from authorized distributors or with documented traceability","hint":"Broker parts carry counterfeit risk; record and approve any exceptions.","tags":[],"severity":"major"}]},{"id":"a-cst","title":"Cost & Volume","tags":["production"],"items":[{"id":"asm-cst-1","text":"The BOM is costed at the target volume, with price breaks and MOQs","hint":"Include reel minimums and assembler attrition allowance.","tags":[],"severity":"major"},{"id":"asm-cst-2","text":"Parts are placed on one side where the design allows","hint":"A single reflow pass saves a stencil, a setup and a process step.","tags":[],"severity":"minor"},{"id":"asm-cst-3","text":"Through-hole parts are minimized or grouped for one soldering process","hint":"Each manual or selective solder step adds cost per board.","tags":[],"severity":"minor"},{"id":"asm-cst-4","text":"Passive values and packages are consolidated to reduce unique BOM lines","hint":"Fewer feeders and lines cut setup cost and inventory.","tags":[],"severity":"minor"},{"id":"asm-cst-5","text":"Very small packages (0201, 01005) are used only where needed","hint":"They raise assembly cost and limit which assemblers can build the board.","tags":[],"severity":"minor"},{"id":"asm-cst-6","text":"Assembler NRE (stencils, programs, fixtures) is quoted and accepted","hint":"Include test fixture and programming fixture costs.","tags":[],"severity":"minor"}]}]},{"id":"fab","title":"Fabrication & Release Review","short":"Fab & Release","version":2,"description":"Checks that the fabrication package, drawing, stackup, panel and release records are complete and match the fabricator's capability before the board is ordered.","sections":[{"id":"g-fil","title":"Fab Package & Gerber Files","tags":[],"items":[{"id":"gf1","text":"All required layers are exported: copper (top, bottom, inner), silkscreen, solder mask and paste","hint":"Compare the layer list against the stackup; a missing inner layer is easy to miss in a zip.","tags":[],"severity":"critical"},{"id":"gf2","text":"The board outline (Edge.Cuts / mechanical layer) is exported correctly","hint":"Include internal cutouts and slots, and make the outline a closed contour.","tags":[],"severity":"critical"},{"id":"gf3","text":"The drill file (Excellon / NC drill) is exported with correct units and zero suppression","hint":"Overlay the drill file on copper in a CAM viewer; a units or format mismatch shows up as offset or scaled holes.","tags":[],"severity":"critical"},{"id":"gf4","text":"Gerber files are opened in a CAM viewer and visually checked before submission","hint":"Use an independent viewer, not the CAD tool that made them.","tags":[],"severity":"major"},{"id":"gf5","text":"File names follow the fabricator's requirements (no spaces, correct extensions)","tags":[],"severity":"minor"},{"id":"gf6","text":"The revision identifier is included in the file names or fab notes","hint":"Every file and the zip itself should carry the revision so mixed-revision packages are obvious.","tags":[],"severity":"major"},{"id":"fab-pkg-1","text":"Gerber X2, ODB++ or IPC-2581 is used, as agreed with the fabricator","hint":"Intelligent formats carry layer function and stackup, reducing interpretation errors.","tags":[],"severity":"minor"},{"id":"fab-pkg-2","text":"Plated and non-plated holes are in separate drill files or clearly attributed","hint":"Mixing them leads to plated mounting holes or unplated vias.","tags":[],"severity":"major"},{"id":"fab-pkg-3","text":"An IPC-D-356 netlist is included for the fabricator's electrical test","hint":"Without it the fab tests against a netlist extracted from the Gerbers, which won't catch design-to-Gerber errors.","tags":[],"severity":"major"},{"id":"fab-pkg-4","text":"A drill drawing or drill table lists every hole size, symbol, quantity and plating","hint":"Check the totals against the drill file.","tags":[],"severity":"major"},{"id":"fab-pkg-5","text":"A readme lists every file in the package and its function","hint":"Include layer order, contact name and the revision.","tags":[],"severity":"minor"},{"id":"fab-pkg-6","text":"The copper layer order is unambiguous and matches the stackup","hint":"Name files by layer number (L1…Ln) or use X2 attributes, so inner layers can't be swapped.","tags":[],"severity":"critical"},{"id":"fab-pkg-7","text":"The fabrication drawing is included as a PDF in the package","tags":[],"severity":"major"},{"id":"fab-pkg-8","text":"Each blind, buried or backdrill span has its own drill file","hint":"Name the start and end layer of each span.","tags":["hdi","high-speed"],"severity":"major"}]},{"id":"g-fab","title":"Fabrication Drawing & Notes","tags":[],"items":[{"id":"gn1","text":"Controlled impedance requirements are specified with reference to the stackup","hint":"Point to the impedance table rather than repeating values in several places.","tags":[],"severity":"critical"},{"id":"gn2","text":"Surface finish is specified (ENIG, HASL, OSP, etc.) and matches design requirements","tags":[],"severity":"major"},{"id":"gn3","text":"Copper weight is specified per layer (e.g. 1 oz outer, 0.5 oz inner)","hint":"State whether outer weights are base or finished after plating.","tags":[],"severity":"major"},{"id":"gn4","text":"Solder mask and silkscreen colors are specified","tags":[],"severity":"minor"},{"id":"gn5","text":"Via fill / tenting requirements are specified (tented, plugged, filled)","hint":"Name the via type and treatment, ideally using IPC-4761 types, and which vias it applies to.","tags":[],"severity":"major"},{"id":"gn6","text":"The IPC-6012 performance class (Class 2 or Class 3) is specified on the fab drawing","hint":"Class 3 costs more and limits fab choice; specify it only where needed.","tags":[],"severity":"major"},{"id":"fab-not-1","text":"The base material is specified by type and key properties, or by IPC-4101 slash sheet","hint":"\"FR-4\" alone covers a wide range of materials; name Tg and, if needed, Td and Dk.","tags":[],"severity":"major"},{"id":"fab-not-2","text":"Material Tg and Td suit lead-free assembly and the operating temperature","hint":"Mid- or high-Tg material is typical for lead-free, thick or high-layer-count boards; confirm per fab capability.","tags":[],"severity":"major"},{"id":"fab-not-3","text":"Finished board thickness and tolerance are specified","hint":"Say where it is measured (over copper, over mask); it matters for edge connectors and card guides.","tags":[],"severity":"major"},{"id":"fab-not-4","text":"Finished hole size tolerances are specified for plated and non-plated holes","hint":"Tolerances tighter than standard (press-fit, locating pins) must be called out explicitly.","tags":[],"severity":"major"},{"id":"fab-not-5","text":"Flammability rating is specified where the product needs it (e.g. UL 94 V-0)","hint":"Check the safety standard for the product; the fab must use a recognized material and process.","tags":["mains","regulatory"],"severity":"major"},{"id":"fab-not-6","text":"Plated edges and castellated holes are called out on the drawing","hint":"Both need special process steps; the fab will not add them unprompted.","tags":[],"severity":"major"},{"id":"fab-not-7","text":"Edge connector bevel angle and depth are specified","hint":"Card-edge fingers need a bevel to mate cleanly; follow the connector spec.","tags":[],"severity":"minor"}]},{"id":"f-stk","title":"Stackup & Impedance","tags":[],"items":[{"id":"fab-stk-1","text":"The fab drawing has a stackup with layer order, copper weights, dielectric thicknesses and materials","tags":[],"severity":"critical"},{"id":"fab-stk-2","text":"The stackup is confirmed by the fabricator with their actual materials before release","hint":"A stackup built from catalog values can't always be made. Get the fab's stackup back in writing.","tags":[],"severity":"major"},{"id":"fab-stk-3","text":"The stackup is symmetric about its center","hint":"Asymmetric copper or dielectric causes bow and twist after lamination and reflow.","tags":[],"severity":"major"},{"id":"fab-stk-4","text":"The impedance table lists each target, tolerance, layer, reference planes and trace geometry","hint":"Include differential pairs with both width and spacing.","tags":["high-speed","rf","ddr"],"severity":"critical"},{"id":"fab-stk-5","text":"Dk and loss tangent used in design are at the relevant frequency and confirmed by the fab","hint":"Datasheet Dk is often quoted at a lower frequency than the signal of interest.","tags":["rf","high-speed"],"severity":"major"},{"id":"fab-stk-6","text":"Dielectric thicknesses in the CAD stackup match the fab-confirmed stackup","hint":"Re-run impedance calculations if the fab changed any thickness or material.","tags":[],"severity":"major"},{"id":"fab-stk-7","text":"The fab may adjust trace widths to hit impedance, within stated limits","hint":"State the maximum adjustment allowed so the fab can tune without breaking spacing rules.","tags":["high-speed","rf","ddr"],"severity":"major"},{"id":"fab-stk-8","text":"Heavy-copper layers meet the fab's minimum spacing and resin-fill capability","hint":"Heavy copper needs wider spacing and thicker prepreg to fill between features.","tags":["high-current"],"severity":"major"},{"id":"fab-stk-9","text":"Dielectric thickness between isolated layers meets the insulation requirement","hint":"Check against the safety standard's requirement for insulation through the board.","tags":["mains"],"severity":"critical"}]},{"id":"f-drl","title":"Drill, Vias & Plating","tags":[],"items":[{"id":"fab-drl-1","text":"The smallest plated drill and board thickness are within the fab's aspect-ratio capability","hint":"Rule of thumb: through-hole aspect ratio around 8:1 to 10:1 for standard processes; confirm with the fab.","tags":[],"severity":"critical"},{"id":"fab-drl-2","text":"Annular rings meet the fab's capability for the specified IPC class","tags":[],"severity":"major"},{"id":"fab-drl-3","text":"Hole wall plating thickness is specified, or set by the IPC-6012 class","hint":"Thicker plating improves via reliability under thermal cycling.","tags":[],"severity":"major"},{"id":"fab-drl-4","text":"Microvia aspect ratio and size are within the fab's capability","hint":"Rule of thumb: microvia depth no more than about its diameter; confirm with the fab.","tags":["hdi"],"severity":"critical"},{"id":"fab-drl-5","text":"Stacked versus staggered microvias are agreed with the fab","hint":"Stacked microvias need filled vias and cost more; some fabs advise staggering for reliability.","tags":["hdi"],"severity":"major"},{"id":"fab-drl-6","text":"Via-in-pad vias are filled and plated over (capped)","hint":"Usually IPC-4761 Type VII. Unfilled via-in-pad wicks solder away from BGA and QFN joints.","tags":["hdi","bga"],"severity":"critical"},{"id":"fab-drl-7","text":"Backdrill depth, maximum stub length and must-not-cut layers are specified","hint":"Give it per net or per drill span, matched to the backdrill file.","tags":["high-speed"],"severity":"major"},{"id":"fab-drl-8","text":"Slots and non-round holes are defined in the drill or rout file and on the drawing","hint":"Plated slots in particular are often lost or made as round holes.","tags":[],"severity":"major"},{"id":"fab-drl-9","text":"Press-fit holes are listed in the drill table with their finished size and tolerance","hint":"Use the connector manufacturer's hole specification; plating thickness affects the finished size.","tags":[],"severity":"critical"}]},{"id":"f-msk","title":"Solder Mask & Silkscreen","tags":[],"items":[{"id":"fab-msk-1","text":"Solder mask expansion around pads meets the fab's registration capability","tags":[],"severity":"major"},{"id":"fab-msk-2","text":"Solder mask web between fine-pitch pads meets the fab's minimum","hint":"Below the minimum, the fab will remove the web silently. Decide whether that is acceptable.","tags":[],"severity":"major"},{"id":"fab-msk-3","text":"Mask openings exist for test points, fiducials and intentionally exposed copper","tags":[],"severity":"major"},{"id":"fab-msk-4","text":"There is no unintended exposed copper near pads or traces","hint":"Look for mask openings on vias or traces that could short to parts or chassis.","tags":[],"severity":"major"},{"id":"fab-msk-5","text":"Silkscreen is clipped clear of pads and exposed copper","tags":[],"severity":"minor"},{"id":"fab-msk-6","text":"Silkscreen text height and line width meet the fab's minimum","hint":"Rule of thumb: around 0.15 mm (6 mil) line width and 0.8–1.0 mm text height for legibility.","tags":[],"severity":"minor"},{"id":"fab-msk-7","text":"Safety markings (high-voltage warnings, isolation boundaries) are on the silkscreen","hint":"Check the product's safety standard for required symbols.","tags":["mains"],"severity":"major"}]},{"id":"f-fin","title":"Surface Finish","tags":[],"items":[{"id":"fab-fin-1","text":"The surface finish suits the finest-pitch parts and their flatness needs","hint":"HASL is uneven and generally a poor fit for fine pitch and BGA; ENIG, OSP or immersion finishes are flatter.","tags":[],"severity":"major"},{"id":"fab-fin-2","text":"The finish suits any wire bonding, press-fit or contact areas","hint":"Check connector and bonding requirements; ENEPIG or hard gold may be needed.","tags":[],"severity":"major"},{"id":"fab-fin-3","text":"The finish's shelf life suits the build schedule","hint":"OSP and immersion silver or tin degrade with storage time; plan build dates accordingly.","tags":[],"severity":"minor"},{"id":"fab-fin-4","text":"The finish is lead-free where RoHS compliance is required","hint":"Specify lead-free HASL rather than plain HASL if HASL is used.","tags":[],"severity":"major"},{"id":"fab-fin-5","text":"Hard gold areas (edge fingers, contact pads) have a specified thickness","hint":"Thickness depends on mating cycles; follow the connector or contact spec.","tags":[],"severity":"major"}]},{"id":"g-pan","title":"Panelization","tags":[],"items":[{"id":"gp1","text":"Panel size and array configuration are agreed with the fabricator","hint":"Also confirm them with the assembler: the panel is their unit of work.","tags":[],"severity":"major"},{"id":"gp2","text":"V-score or tab-route breakaway method is specified and consistent","hint":"V-score only works for straight edges that run the full panel width.","tags":[],"severity":"major"},{"id":"gp3","text":"Rails, tooling holes and fiducials are included in the panel design","hint":"Follow the assembler's preferred rail width and tooling hole size.","tags":[],"severity":"major"},{"id":"gp4","text":"Copper balance across the panel is checked to minimize warpage","hint":"Add copper thieving on rails and empty areas if layers are unbalanced.","tags":[],"severity":"minor"},{"id":"fab-pnl-1","text":"Panel dimensions fit the assembler's line limits","hint":"Check both minimum and maximum conveyor sizes and the maximum panel weight.","tags":[],"severity":"major"},{"id":"fab-pnl-2","text":"Components near break lines keep a safe distance and MLCCs run parallel to the break line","hint":"Break stress cracks ceramic capacitors. Keep clearance per assembler guidance.","tags":[],"severity":"major"},{"id":"fab-pnl-3","text":"Parts that overhang the board edge have clearance cutouts in the panel","tags":[],"severity":"major"},{"id":"fab-pnl-4","text":"A panel drawing is included in the release package","hint":"Dimension the array, rails, tooling holes, fiducials and break features.","tags":[],"severity":"major"},{"id":"fab-pnl-5","text":"V-score depth, angle and residual web are specified per fab capability","tags":[],"severity":"minor"},{"id":"fab-pnl-6","text":"The depanelization method won't overstress nearby components","hint":"Hand breaking and pizza-cutter separation flex the board; routing is gentler for sensitive parts.","tags":[],"severity":"major"},{"id":"fab-pnl-7","text":"The policy for scrapped boards in a panel (X-outs) is agreed","hint":"Some assemblers reject panels containing X-outs, or charge extra for them.","tags":["production"],"severity":"minor"}]},{"id":"f-tst","title":"Electrical Test & Coupons","tags":[],"items":[{"id":"fab-tst-1","text":"100% bare-board electrical test is required","hint":"Flying probe for prototypes, fixture test for volume.","tags":[],"severity":"major"},{"id":"fab-tst-2","text":"Electrical test uses the CAD netlist (IPC-D-356), not one extracted from the Gerbers","tags":[],"severity":"major"},{"id":"fab-tst-3","text":"Impedance coupons are required with a TDR test report","hint":"Make sure the coupon matches the actual trace geometry and reference planes.","tags":["high-speed","rf","ddr"],"severity":"major"},{"id":"fab-tst-4","text":"Microsection (cross-section) reports are requested","hint":"Show plating thickness, registration and laminate quality.","tags":["medical","automotive","harsh-env"],"severity":"minor"},{"id":"fab-tst-5","text":"A certificate of conformance is requested with each lot","tags":[],"severity":"minor"},{"id":"fab-tst-6","text":"Insulation or hipot testing between isolated nets is specified for the bare board","hint":"Define the test voltage, duration and which nets are tested.","tags":["mains"],"severity":"major"},{"id":"fab-tst-7","text":"Bare-board ionic cleanliness testing is specified","hint":"Residues on the bare board can cause leakage and corrosion under coating.","tags":["harsh-env","medical"],"severity":"minor"}]},{"id":"g-drc","title":"Final DRC & DFM","tags":[],"items":[{"id":"gd1","text":"Final DRC is run on the production-ready files with zero errors","hint":"Re-run after the last edit, including silkscreen and fill updates.","tags":[],"severity":"critical"},{"id":"gd2","text":"The design is compared with the previous revision for unintended changes","hint":"Use a Gerber or CAD diff; check that only the ECO's changes appear.","tags":[],"severity":"major"},{"id":"gd3","text":"The fabricator's DFM check has passed, or all flagged issues are resolved","hint":"Record the decision on each flagged item.","tags":[],"severity":"major"},{"id":"gd4","text":"The Gerber zip includes all required files and nothing extraneous","tags":[],"severity":"minor"},{"id":"gd5","text":"A checksum (e.g. MD5 or SHA-256) of the final package is recorded","hint":"Lets you prove later which exact files were ordered.","tags":[],"severity":"minor"},{"id":"fab-drc-1","text":"DRC rules match the chosen fabricator's capability, not tool defaults","tags":[],"severity":"major"},{"id":"fab-drc-2","text":"There are no unrouted connections","hint":"Check the ratsnest is empty, including after copper pours are refilled.","tags":[],"severity":"critical"},{"id":"fab-drc-3","text":"Copper-to-edge clearance meets the fab's capability for the chosen edge process","hint":"V-score and routed edges need different clearances; inner-layer planes need pullback too.","tags":[],"severity":"major"},{"id":"fab-drc-4","text":"Gerbers are compared to the CAD netlist after export","hint":"A CAM netlist compare catches export errors such as missing pours or flashed pads.","tags":[],"severity":"major"},{"id":"fab-drc-5","text":"Creepage and clearance are checked against the safety requirement","hint":"Check on every layer, including inner layers and between pad edges.","tags":["mains"],"severity":"critical"},{"id":"fab-drc-6","text":"Drill-to-copper clearance on inner layers meets fab capability","hint":"Drill wander causes shorts to inner planes if clearance is too small.","tags":[],"severity":"major"},{"id":"fab-drc-7","text":"Any DRC waivers are documented with a reason","tags":[],"severity":"minor"}]},{"id":"g-rel","title":"Release & Version Control","tags":[],"items":[{"id":"gr1","text":"The Gerber package is committed to version control at the correct tag or revision","tags":[],"severity":"major"},{"id":"gr2","text":"The fab order confirmation number is recorded and linked to the design revision","tags":[],"severity":"minor"},{"id":"gr3","text":"Any deviations from the standard process are documented and approved","tags":[],"severity":"major"},{"id":"gr4","text":"Design files are locked and archived at the release revision","hint":"Include schematic, PCB, libraries and output settings, so the release can be regenerated.","tags":[],"severity":"major"},{"id":"fab-rel-1","text":"The revision marked on the board (copper or silkscreen) matches the release revision","tags":[],"severity":"major"},{"id":"fab-rel-2","text":"Fab, assembly, BOM and centroid outputs are all from the same release revision","hint":"Release them together as one package to avoid mixing revisions.","tags":[],"severity":"major"},{"id":"fab-rel-3","text":"An ECO or change list records what changed from the previous revision","tags":[],"severity":"major"},{"id":"fab-rel-4","text":"Design review sign-offs are recorded before release","hint":"Include schematic, layout and this fab review, with reviewer names and dates.","tags":[],"severity":"major"},{"id":"fab-rel-5","text":"Open issues and errata from the previous revision are resolved or carried forward","tags":[],"severity":"major"}]},{"id":"f-flx","title":"Flex & Rigid-Flex","tags":["flex"],"items":[{"id":"fab-flx-1","text":"Bend areas are defined on the drawing with bend radius and static or dynamic use","tags":[],"severity":"critical"},{"id":"fab-flx-2","text":"Bend radius meets the fab's minimum for the flex thickness","hint":"Rule of thumb: about 10× thickness for static bends and much more for dynamic flexing; confirm with the fab.","tags":[],"severity":"major"},{"id":"fab-flx-3","text":"No vias or pads are placed in bend areas","tags":[],"severity":"major"},{"id":"fab-flx-4","text":"Traces in bend areas run perpendicular to the bend line and are staggered between layers","hint":"Stacked traces on adjacent layers raise strain and crack sooner.","tags":[],"severity":"major"},{"id":"fab-flx-5","text":"Coverlay openings meet fab capability, and coverlay versus flexible mask is chosen","tags":[],"severity":"minor"},{"id":"fab-flx-6","text":"Stiffeners are specified with material, thickness, location and adhesive","tags":[],"severity":"major"},{"id":"fab-flx-7","text":"Rigid-to-flex transition zones keep vias and pads at a safe distance","hint":"Distance per fab capability; components close to the transition stress the flex.","tags":[],"severity":"major"},{"id":"fab-flx-8","text":"Rolled-annealed copper is specified for dynamic flex areas","hint":"Electrodeposited copper cracks sooner under repeated flexing.","tags":[],"severity":"major"},{"id":"fab-flx-9","text":"ZIF tail thickness, including stiffener, matches the connector specification","hint":"Too thin and the contacts don't grip; too thick and the tail won't insert.","tags":[],"severity":"critical"}]}]},{"id":"bringup","title":"Bring-up & Validation","short":"Bring-up","version":1,"description":"Checks for first boards back, from receiving inspection through power-on, functional bring-up and design validation before releasing the next revision.","sections":[{"id":"b-receiving","title":"Receiving Inspection","tags":[],"items":[{"id":"bu-rcv-1","text":"Received boards match the ordered revision, quantity and assembly variant","hint":"Check the silkscreen revision, fab date code and assembly variant label against the purchase order and release package. Mixed revisions in one batch cause confusing bring-up results.","tags":[],"severity":"major"},{"id":"bu-rcv-2","text":"Each board has a unique serial number or label recorded in the bring-up log","hint":"Results, rework and failures must be traceable to a specific unit. Label boards before anyone starts probing.","tags":[],"severity":"major"},{"id":"bu-rcv-3","text":"Visual inspection shows no solder bridges, tombstones, missing or misplaced parts","hint":"Inspect under magnification against the assembly drawing; use IPC-A-610 as the acceptance reference. Pay particular attention to fine-pitch leads and QFN edges.","tags":[],"severity":"major"},{"id":"bu-rcv-4","text":"Polarized parts (diodes, electrolytic and tantalum capacitors, LEDs) are fitted in the correct orientation","hint":"Compare each polarity mark to the assembly drawing, not just the silkscreen, since silkscreen marks are sometimes wrong. A reversed tantalum can fail short on first power.","tags":[],"severity":"critical"},{"id":"bu-rcv-5","text":"Pin-1 orientation of every IC and connector matches the assembly drawing","hint":"Check ICs, regulators, crystals with polarity and keyed connectors. A rotated regulator or MCU usually damages itself or the rail on power-up.","tags":[],"severity":"critical"},{"id":"bu-rcv-6","text":"Do-not-fit (DNF) positions are unpopulated and fitted options match the build variant","hint":"Walk the BOM's DNF list and variant table. A fitted DNF strap or resistor can short rails or select the wrong mode.","tags":[],"severity":"major"},{"id":"bu-rcv-7","text":"Bare-board dimensions, hole positions and mounting features match the fabrication drawing","hint":"Measure board outline and key mounting holes with calipers, and trial-fit into the enclosure or mechanical fixture if available.","tags":[],"severity":"major"},{"id":"bu-rcv-8","text":"X-ray inspection report for BGA and bottom-terminated parts shows acceptable voiding and no bridges or opens","hint":"Request X-ray images for every BGA/LGA/QFN thermal pad. Compare voiding to the assembler's acceptance criteria; open balls often show as missing joints in the image.","tags":["bga"],"severity":"critical"},{"id":"bu-rcv-9","text":"Flex sections are free of cracks, delamination and coverlay damage at the bend regions","hint":"Inspect stiffener edges and the rigid-flex transition under magnification. Do not flex the board beyond its specified bend radius during handling.","tags":["flex"],"severity":"major"},{"id":"bu-rcv-10","text":"Conformal coating (if applied) covers the intended areas and keep-out areas such as connectors and test points are clean","hint":"Inspect under UV light if the coating has a tracer. Coating on connector contacts or test pads causes intermittent contact.","tags":["harsh-env"],"severity":"major"}]},{"id":"b-prepower","title":"Pre-Power Checks","tags":[],"items":[{"id":"bu-pre-1","text":"Resistance from each power rail to ground is measured and recorded on an unpowered board","hint":"Measure every rail at a test point or capacitor with a DMM, observing meter polarity. Compare across boards; an outlier points to a short or a missing part.","tags":[],"severity":"critical"},{"id":"bu-pre-2","text":"No rail measures a hard short (near 0 Ω) to ground or to another rail","hint":"Large-capacitance or low-voltage core rails can read low ohms legitimately; compare against a known-good board or the expected load. Locate shorts with a thermal camera at very low current limit or a milliohm meter.","tags":[],"severity":"critical"},{"id":"bu-pre-3","text":"Input power connector polarity and pinout are verified against the schematic","hint":"Check with a continuity meter from connector pins to the input protection and ground. A mirrored connector footprint is a common first-article error.","tags":[],"severity":"critical"},{"id":"bu-pre-4","text":"Jumpers, straps, DIP switches and boot-mode resistors are set to the bring-up configuration","hint":"Document the configuration used in the bring-up log. Default boot from an unprogrammed external flash may need a strap change to enter the debugger or ROM bootloader.","tags":[],"severity":"major"},{"id":"bu-pre-5","text":"Rail-to-rail resistance shows no unexpected low-impedance paths between rails","hint":"Check pairs of adjacent rails, especially those sharing a regulator or a level translator. Back-feeding through I/O protection diodes can show up here as a diode drop in diode-test mode.","tags":[],"severity":"major"},{"id":"bu-pre-6","text":"High-voltage and isolation barriers show no continuity across the barrier","hint":"Measure resistance from primary to secondary side; use an insulation resistance tester at a voltage appropriate to the design and per the safety requirement.","tags":["mains"],"severity":"critical"},{"id":"bu-pre-7","text":"Bring-up power plan lists each rail's expected voltage and current and the current limit to use","hint":"Prepare this before power-on from the power tree. It gives every check below a pass/fail reference.","tags":[],"severity":"major"},{"id":"bu-pre-8","text":"Battery is not connected for first power-up; a current-limited supply or battery simulator is used instead","hint":"A battery can deliver very high fault current into a short. Connect the real battery only after the protection and charge paths are verified.","tags":["battery"],"severity":"critical"}]},{"id":"b-poweron","title":"First Power-On","tags":[],"items":[{"id":"bu-on-1","text":"First power-up uses a bench supply with current limit set just above the expected input current","hint":"Rule of thumb: start at a limit modestly above the calculated quiescent current, then raise it in steps. Watch for the supply going into current limit.","tags":[],"severity":"critical"},{"id":"bu-on-2","text":"Input voltage is ramped slowly from zero while input current is monitored","hint":"Watch for current rising abnormally before regulators should be active, which indicates a short or reversed part. Stop and investigate any unexpected step.","tags":[],"severity":"major"},{"id":"bu-on-3","text":"Thermal camera or touch check shows no unexpected hot spots within the first seconds of power","hint":"A thermal camera finds shorted capacitors and back-driven ICs quickly. Compare against expected hot parts (regulators, processors).","tags":[],"severity":"critical"},{"id":"bu-on-4","text":"Input current at idle is within the expected range from the power budget","hint":"Record the value for each board. Large board-to-board spread usually indicates an assembly defect.","tags":[],"severity":"major"},{"id":"bu-on-5","text":"Every rail measures within its specified tolerance at the regulator output and at the far-end load","hint":"Measure at the load pins as well as the regulator to catch distribution drop. Compare to datasheet tolerance of the load ICs.","tags":[],"severity":"critical"},{"id":"bu-on-6","text":"Power-good, status and indicator signals report the expected state","hint":"Check PGOOD outputs, reset supervisors and status LEDs. A missing power-good often explains a processor that never leaves reset.","tags":[],"severity":"major"},{"id":"bu-on-7","text":"Mains-connected boards are first powered through an isolation transformer with suitable safety precautions","hint":"Use an isolation transformer, a variac for slow ramp and differential or isolated probes. Follow the lab's high-voltage work procedure.","tags":["mains"],"severity":"critical"}]},{"id":"b-rails","title":"Power Rail Validation","tags":[],"items":[{"id":"bu-rail-1","text":"Ripple and noise on each rail is within the load ICs' requirements","hint":"Measure with a short ground spring at the probe tip, bandwidth limit noted, at the load. Long ground leads add pickup and give misleading results.","tags":[],"severity":"major"},{"id":"bu-rail-2","text":"Load-step response keeps each rail within tolerance during transients","hint":"Use an electronic load or a switched resistor at realistic slew rates, or exercise the real firmware load. Check overshoot, undershoot and settling against load IC limits.","tags":[],"severity":"major"},{"id":"bu-rail-3","text":"Switching regulator loop stability is acceptable (bode measurement or load-step ringing)","hint":"Measure phase margin with a loop injection transformer if a test point exists; otherwise judge from load-step ringing. Low margin causes intermittent faults across temperature.","tags":["high-current"],"severity":"major"},{"id":"bu-rail-4","text":"Power-up sequencing order and timing match the requirements of the sequenced devices","hint":"Capture all relevant rails and resets on a multi-channel scope at power-on. Compare to processor, FPGA or DDR datasheet sequencing requirements.","tags":[],"severity":"critical"},{"id":"bu-rail-5","text":"Power-down sequencing does not violate device requirements or back-power any rail","hint":"Capture rails at power removal. Look for rails held up through I/O pins or slow-discharging outputs.","tags":[],"severity":"major"},{"id":"bu-rail-6","text":"Board starts reliably at minimum specified input voltage","hint":"Test with the worst-case source impedance (cable, battery) where possible. Include inrush current interacting with the source.","tags":[],"severity":"critical"},{"id":"bu-rail-7","text":"Board starts and operates at maximum specified input voltage","hint":"Verify no component exceeds its rating and that protection does not trip falsely. Measure peak stress on switching nodes.","tags":[],"severity":"critical"},{"id":"bu-rail-8","text":"Inrush current at power-on is within source, connector and fuse limits","hint":"Capture input current with a current probe at the worst-case input voltage. Hot-plugging can produce higher inrush and input voltage spikes than a slow bench ramp.","tags":[],"severity":"major"},{"id":"bu-rail-9","text":"Converter efficiency at typical and full load meets the power budget","hint":"Measure input and output power with accurate meters. Low efficiency points to inductor saturation, wrong frequency or layout problems.","tags":[],"severity":"major"},{"id":"bu-rail-10","text":"Over-current, over-voltage and thermal protection trip at the designed thresholds","hint":"Test each protection feature at limited energy where possible. Confirm recovery behavior (latch-off vs hiccup) matches the design intent.","tags":[],"severity":"major"},{"id":"bu-rail-11","text":"Motor or actuator supply holds within limits during start-up, stall and regenerative braking","hint":"Capture bus voltage while starting, stalling and decelerating the load. Regenerated energy can pump the bus above component ratings.","tags":["motor"],"severity":"critical"},{"id":"bu-rail-12","text":"Rail and connector temperature rise at full load is acceptable","hint":"Run at maximum current until temperatures settle and measure copper, connectors and fuses with a thermal camera or thermocouples.","tags":["high-current"],"severity":"major"}]},{"id":"b-clocks","title":"Clocks & Reset","tags":[],"items":[{"id":"bu-clk-1","text":"Every crystal and oscillator starts reliably and runs at the expected frequency","hint":"Measure with a frequency counter or scope through a buffered output where possible; probing a crystal directly loads it and can stop or pull it.","tags":[],"severity":"critical"},{"id":"bu-clk-2","text":"Crystal frequency accuracy is within the requirement (load capacitance trimmed)","hint":"Measure ppm error against a reference. Adjust load capacitors if the offset is systematic; timing-critical radios and RTCs are most sensitive.","tags":[],"severity":"major"},{"id":"bu-clk-3","text":"Crystal oscillators start reliably at cold and at minimum supply","hint":"Check oscillator margin per the MCU vendor's guidance (negative resistance test or start-up over temperature). Marginal crystals fail in the field, not on the bench.","tags":[],"severity":"major"},{"id":"bu-clk-4","text":"Clock signal integrity (amplitude, edge rate, jitter) meets the receiver requirements","hint":"Measure at the receiving device with adequate scope bandwidth. Check jitter for SerDes, ADC and high-speed reference clocks against datasheet limits.","tags":["high-speed"],"severity":"major"},{"id":"bu-clk-5","text":"PLLs lock and report lock status as expected","hint":"Read lock bits through the debugger or test firmware. Intermittent lock loss is often a supply-noise issue.","tags":["fpga"],"severity":"major"},{"id":"bu-clk-6","text":"Reset is held until all required rails are stable and released cleanly","hint":"Scope reset against supplies at power-on and with a slow input ramp. Check for glitches on reset during brown-out.","tags":[],"severity":"critical"},{"id":"bu-clk-7","text":"Brown-out produces a clean reset and recovery without lock-up","hint":"Dip input voltage slowly below threshold and back. The board must reset and restart, not hang in a partial state.","tags":[],"severity":"major"},{"id":"bu-clk-8","text":"Real-time clock keeps time on backup supply for the required duration","hint":"Remove main power and confirm the RTC retains time. Measure backup current against the budget.","tags":["low-power"],"severity":"major"}]},{"id":"b-debug","title":"Programming & Debug Access","tags":[],"items":[{"id":"bu-dbg-1","text":"Debugger connects to each programmable device through the debug header","hint":"Confirm the JTAG/SWD chain is detected and IDs read correctly. Failure here is usually a pinout, pull-up or reset strap problem.","tags":[],"severity":"critical"},{"id":"bu-dbg-2","text":"Each device can be programmed and verified through the intended programming path","hint":"Program and verify readback for MCUs, flash, CPLDs and FPGAs. Note programming time for production planning.","tags":[],"severity":"critical"},{"id":"bu-dbg-3","text":"FPGA configures from its boot flash and reports DONE / configuration status","hint":"Check the configuration mode straps and that the image boots after a power cycle, not only from JTAG.","tags":["fpga"],"severity":"critical"},{"id":"bu-dbg-4","text":"Boot ROM recovery or bootloader path works on a blank or corrupted device","hint":"Confirm a bricked unit can be recovered in the field or factory without rework.","tags":[],"severity":"major"},{"id":"bu-dbg-5","text":"Debug console (UART or equivalent) outputs readable text at the configured baud rate","hint":"A console that works early is the fastest bring-up tool; garbled output usually means a clock or baud configuration error.","tags":[],"severity":"major"},{"id":"bu-dbg-6","text":"Debug and programming interfaces can be locked or disabled as required for production security","hint":"Verify the readout protection or debug lock procedure on a sacrificial unit before it is applied to production.","tags":["production"],"severity":"major"}]},{"id":"b-periph","title":"Peripheral & Interface Bring-up","tags":[],"items":[{"id":"bu-per-1","text":"Every I2C, SPI and UART device responds at its expected address or ID","hint":"Run a bus scan and read ID registers. Missing devices point to address straps, pull-ups or assembly faults.","tags":[],"severity":"major"},{"id":"bu-per-2","text":"All GPIO, LED, button and control signals toggle and read correctly","hint":"Use a test firmware to exercise each pin and confirm against the pinout. This catches schematic-to-firmware pin mapping errors early.","tags":[],"severity":"major"},{"id":"bu-per-3","text":"External memory passes a full read/write memory test at rated speed","hint":"Run a pattern-based memory test (walking ones, address-in-address, random) across the full array, including at temperature corners later.","tags":["ddr"],"severity":"critical"},{"id":"bu-per-4","text":"DDR training or calibration completes with adequate margin","hint":"Review read/write eye or training margin reports from the controller or vendor tool. Low margin predicts failures over temperature and production spread.","tags":["ddr"],"severity":"critical"},{"id":"bu-per-5","text":"High-speed serial links train at the target rate with error-free BER test","hint":"Run PRBS or vendor link tests for a duration long enough to support the BER target. Capture eye diagrams where tools permit.","tags":["high-speed"],"severity":"critical"},{"id":"bu-per-6","text":"USB enumerates at the intended speed and passes basic transfer tests","hint":"Check enumeration on several hosts and cables. Verify VBUS behavior and current limits.","tags":[],"severity":"major"},{"id":"bu-per-7","text":"Ethernet link establishes at all supported speeds and passes traffic without errors","hint":"Check link at each negotiated speed and run a sustained traffic test, watching error counters.","tags":[],"severity":"major"},{"id":"bu-per-8","text":"Display initializes and shows correct image without artifacts, and touch reports accurate coordinates","hint":"Check color order, orientation, backlight dimming and touch across the full panel area.","tags":["display"],"severity":"major"},{"id":"bu-per-9","text":"Audio input and output paths work with expected level and no audible noise or distortion","hint":"Check with a test tone and an audio analyzer if available. Listen at minimum volume for hum and digital whine.","tags":["audio"],"severity":"major"},{"id":"bu-per-10","text":"Motor driver commutates correctly in both directions and current sensing reads accurately","hint":"Start at reduced supply and current limit. Compare measured phase current against the sensed value.","tags":["motor"],"severity":"critical"},{"id":"bu-per-11","text":"Motor driver fault protection (over-current, stall, shoot-through) trips as designed","hint":"Test with a locked rotor or controlled overload at reduced energy. Confirm the driver recovers as intended.","tags":["motor"],"severity":"major"},{"id":"bu-per-12","text":"External connectors pass signals with correct pinout to mating cables and boards","hint":"Test with the actual mating harness or board rather than a bench lead. Mirror-image pinouts are a common first-article error.","tags":[],"severity":"critical"},{"id":"bu-per-13","text":"Sensors return plausible readings that respond correctly to stimulus","hint":"Compare against a reference instrument or known stimulus. Check axis orientation and sign for IMUs and similar sensors.","tags":[],"severity":"major"}]},{"id":"b-analog","title":"Analog Performance","tags":["precision-analog","audio"],"items":[{"id":"bu-ana-1","text":"Noise floor of each analog channel is measured and meets the requirement","hint":"Capture with inputs shorted or terminated and compute RMS noise or noise density. Compare to the noise budget.","tags":[],"severity":"major"},{"id":"bu-ana-2","text":"Offset and gain errors are measured and within the requirement or calibration range","hint":"Apply known reference inputs at multiple points. Errors beyond the calibration range indicate a design or part issue.","tags":[],"severity":"major"},{"id":"bu-ana-3","text":"Linearity across the full input range meets the requirement","hint":"Sweep the input with a precision source and plot error vs input. Look for clipping near the rails.","tags":["precision-analog"],"severity":"major"},{"id":"bu-ana-4","text":"Voltage reference output is within tolerance and stable over warm-up","hint":"Measure with a meter of better accuracy than the reference. Record drift during warm-up and over temperature later.","tags":["precision-analog"],"severity":"major"},{"id":"bu-ana-5","text":"Digital and switching activity does not couple into analog channels","hint":"Compare noise with processors, radios and switchers active vs idle. Look for spurs at known clock or switching frequencies.","tags":[],"severity":"major"},{"id":"bu-ana-6","text":"Amplifier stages are stable with no oscillation under all load conditions","hint":"Check with step inputs and capacitive loads such as cables. Oscillation may appear only as excess noise or offset on a DMM.","tags":[],"severity":"major"},{"id":"bu-ana-7","text":"Sensor front-ends meet accuracy with the actual sensor connected","hint":"Test with the production sensor and cable rather than a simulator; cable capacitance and leakage affect high-impedance inputs.","tags":["precision-analog"],"severity":"major"}]},{"id":"b-rf","title":"RF Bring-up","tags":["rf"],"items":[{"id":"bu-rf-1","text":"Conducted transmit power at each channel and band is within the requirement","hint":"Measure at the RF test connector or with a coax pigtail into a spectrum analyzer or power meter, accounting for cable loss.","tags":[],"severity":"critical"},{"id":"bu-rf-2","text":"Receiver sensitivity meets the requirement at the specified error rate","hint":"Use a signal generator or radio tester through calibrated attenuation. Compare against the radio vendor's reference figures.","tags":[],"severity":"critical"},{"id":"bu-rf-3","text":"Antenna match (return loss / VSWR) is acceptable across the band in the final enclosure","hint":"Measure with a VNA at the antenna feed with the enclosure, battery and nearby cables in place. Tune the matching network as needed and record final values.","tags":[],"severity":"major"},{"id":"bu-rf-4","text":"Harmonics and spurious emissions at the conducted port are within the regulatory limits","hint":"Sweep a wide span on a spectrum analyzer while transmitting at max power. Fix filtering before radiated testing.","tags":["regulatory"],"severity":"major"},{"id":"bu-rf-5","text":"Frequency error of the transmitter is within the radio standard's tolerance","hint":"Measure carrier frequency offset with a radio tester; trim the crystal load if needed.","tags":[],"severity":"major"},{"id":"bu-rf-6","text":"Board-generated noise does not desense the receiver","hint":"Compare sensitivity with all other subsystems active vs idle. Display, switching regulators and memory clocks are common culprits.","tags":[],"severity":"major"},{"id":"bu-rf-7","text":"Radiated performance (TRP/TIS or range test) is acceptable in the final enclosure","hint":"Run an over-the-air test in a chamber if available, or a documented range test against a reference device.","tags":[],"severity":"major"}]},{"id":"b-thermal","title":"Thermal Validation","tags":[],"items":[{"id":"bu-thm-1","text":"Component temperatures at worst-case load and maximum ambient are within ratings with margin","hint":"Measure at room temperature and extrapolate, or test in a chamber at maximum ambient. Use thermocouples on critical parts for accuracy.","tags":[],"severity":"critical"},{"id":"bu-thm-2","text":"Thermal testing is done in the final enclosure or a representative airflow condition","hint":"An open bench board runs much cooler than an enclosed product. Note the enclosure state in the results.","tags":[],"severity":"major"},{"id":"bu-thm-3","text":"Thermal shutdown and throttling behave as designed","hint":"Heat the hot parts deliberately and confirm firmware throttling or hardware shutdown and recovery.","tags":[],"severity":"major"},{"id":"bu-thm-4","text":"Touch-accessible surfaces stay within the product's touch-temperature requirement","hint":"Measure external enclosure surfaces at maximum load and ambient against the applicable safety standard's limits.","tags":["medical","mains"],"severity":"major"},{"id":"bu-thm-5","text":"Battery temperature during charge and peak discharge stays within the cell's specified window","hint":"Place a thermocouple on the cell; nearby heat sources can push the cell out of its charge range.","tags":["battery"],"severity":"critical"}]},{"id":"b-environment","title":"Environmental & Margin Testing","tags":[],"items":[{"id":"bu-env-1","text":"Board operates correctly at the minimum and maximum rated ambient temperature","hint":"Run the functional test in a chamber at each extreme with soak time for thermal equilibrium.","tags":[],"severity":"critical"},{"id":"bu-env-2","text":"Board operates at the four corners of supply voltage and temperature","hint":"Combine minimum and maximum input with cold and hot. Failures often appear only at one corner.","tags":[],"severity":"major"},{"id":"bu-env-3","text":"Temperature cycling causes no intermittent faults or solder joint failures","hint":"Cycle through the rated range while monitoring function. Inspect suspect joints afterward.","tags":["harsh-env","automotive"],"severity":"major"},{"id":"bu-env-4","text":"Board survives vibration and mechanical shock to the product requirement","hint":"Monitor function during the test where possible. Check heavy parts, connectors and tall capacitors afterward.","tags":["harsh-env","automotive"],"severity":"major"},{"id":"bu-env-5","text":"Humidity or condensation exposure does not cause leakage or corrosion failures","hint":"Test coated and uncoated variants if relevant. High-impedance analog nodes are most sensitive.","tags":["harsh-env"],"severity":"major"},{"id":"bu-env-6","text":"Automotive supply transients (load dump, cold crank, reverse battery) are survived as specified","hint":"Use a transient generator for the pulses required by the requirement specification. Monitor whether the board must keep running or only survive.","tags":["automotive"],"severity":"critical"},{"id":"bu-env-7","text":"Unit-to-unit variation is checked across all bring-up boards","hint":"Run key measurements on every board, not just the golden one, to see the spread before production.","tags":[],"severity":"major"},{"id":"bu-env-8","text":"Long-duration soak test runs without errors, resets or memory leaks","hint":"Run the full system for an extended period (rule of thumb: at least overnight) with logging.","tags":[],"severity":"major"}]},{"id":"b-emc","title":"Pre-compliance EMC & ESD","tags":["regulatory","medical","automotive"],"items":[{"id":"bu-emc-1","text":"Radiated emissions pre-scan shows margin to the applicable limits","hint":"Scan in a pre-compliance chamber or with near-field probes to identify sources. Margin is needed for lab and unit variation.","tags":[],"severity":"major"},{"id":"bu-emc-2","text":"Conducted emissions on power ports are within the applicable limits with margin","hint":"Measure with a LISN on the power input. Switching regulators and motor drivers are the usual sources.","tags":[],"severity":"major"},{"id":"bu-emc-3","text":"Board survives ESD contact and air discharge at all user-accessible points","hint":"Test with an ESD gun at the levels required by the product's standard. Classify the result (no effect, self-recovery, reset, damage).","tags":[],"severity":"critical"},{"id":"bu-emc-4","text":"Board tolerates fast transients and surges on external cables as required","hint":"Apply EFT and surge to power and long signal cables per the target standard. Confirm protection parts are effective.","tags":[],"severity":"major"},{"id":"bu-emc-5","text":"Radiated and conducted immunity tests cause no unacceptable performance loss","hint":"Pre-test with a field probe or injection clamp. Analog and radio performance are the most commonly affected.","tags":[],"severity":"major"},{"id":"bu-emc-6","text":"Cables, enclosure and grounding used in pre-compliance match the production configuration","hint":"Different cables or shielding can invalidate the results. Record the test setup with photos.","tags":[],"severity":"major"}]},{"id":"b-battery","title":"Battery & Low-Power","tags":["battery","low-power"],"items":[{"id":"bu-bat-1","text":"Sleep current in each low-power mode meets the budget","hint":"Measure with a source meter or power analyzer with sufficient dynamic range; average over several wake cycles. Check every unit, since one leaky part dominates.","tags":[],"severity":"critical"},{"id":"bu-bat-2","text":"Active and wake-up current profile matches the energy budget","hint":"Capture a full duty cycle and integrate charge. Long wake times or peripherals left on are common surprises.","tags":[],"severity":"major"},{"id":"bu-bat-3","text":"No unintended leakage paths through I/O pins, pull-ups or powered-down peripherals","hint":"Isolate subsystems one at a time to find which contributes extra sleep current.","tags":["low-power"],"severity":"major"},{"id":"bu-bat-4","text":"Charge profile (pre-charge, constant current, constant voltage, termination) matches the cell specification","hint":"Log charge current, voltage and temperature over a full charge cycle and compare to the cell datasheet.","tags":["battery"],"severity":"critical"},{"id":"bu-bat-5","text":"Charging stops or derates outside the cell's allowed temperature window","hint":"Test with the NTC simulated cold and hot. Charging a lithium cell out of its temperature range is a safety hazard.","tags":["battery"],"severity":"critical"},{"id":"bu-bat-6","text":"Battery protection trips correctly for over-charge, over-discharge and over-current","hint":"Test using a battery simulator or controlled source. Confirm recovery behavior after each trip.","tags":["battery"],"severity":"critical"},{"id":"bu-bat-7","text":"Fuel gauge or battery voltage reporting is accurate across the discharge curve","hint":"Compare reported state of charge against coulomb-counted reference during a full discharge.","tags":["battery"],"severity":"major"},{"id":"bu-bat-8","text":"Device behaves correctly at low battery: warnings, graceful shutdown, no brown-out loops","hint":"Discharge slowly to cutoff and confirm the system shuts down cleanly and does not repeatedly reboot.","tags":["battery"],"severity":"major"},{"id":"bu-bat-9","text":"Shipping or storage mode current meets the shelf-life requirement","hint":"Measure current in ship mode and confirm the device wakes only by the intended method.","tags":["battery"],"severity":"major"}]},{"id":"b-production","title":"Production Test Readiness","tags":["production"],"items":[{"id":"bu-prd-1","text":"Test points needed for production test are accessible on the assembled board","hint":"Check every test point in the test plan is reachable by pogo pins with parts fitted and not covered by coating or labels.","tags":[],"severity":"major"},{"id":"bu-prd-2","text":"Production test procedure has been run on the bring-up boards","hint":"Run a draft of the test procedure on every unit to confirm pass limits and coverage.","tags":[],"severity":"major"},{"id":"bu-prd-3","text":"Pass/fail limits for production tests are set from measured spread, not single units","hint":"Use the data from all bring-up boards plus design margin to set limits.","tags":[],"severity":"major"},{"id":"bu-prd-4","text":"Test fixture design requirements (board outline, tooling holes, keep-outs) are confirmed","hint":"Share the confirmed requirements with the fixture vendor or contract manufacturer.","tags":[],"severity":"major"},{"id":"bu-prd-5","text":"Serialization and traceability (labels, unique IDs, MAC addresses) work end to end","hint":"Program and read back a unique ID on test units and confirm it reaches the test log.","tags":[],"severity":"major"},{"id":"bu-prd-6","text":"Functional test coverage catches the assembly defects seen during bring-up","hint":"Check each defect found in this build would be detected by the production test.","tags":[],"severity":"major"}]},{"id":"b-nextrev","title":"Rework Log & Next-Revision Notes","tags":[],"items":[{"id":"bu-rev-1","text":"Every rework, bodge wire and part change is logged with board serial, description and reason","hint":"Photograph bodges. Unlogged rework makes later measurements meaningless.","tags":[],"severity":"major"},{"id":"bu-rev-2","text":"Each fix is captured as a schematic or layout change request for the next revision","hint":"Link each rework entry to an ECO or issue so it is not lost when the next revision is started.","tags":[],"severity":"critical"},{"id":"bu-rev-3","text":"Footprint, silkscreen and assembly drawing errors found during bring-up are recorded","hint":"Include wrong polarity marks, unclear reference designators and mis-sized pads.","tags":[],"severity":"major"},{"id":"bu-rev-4","text":"BOM changes (value changes, substitutions, DNF changes) are recorded and fed back to the BOM owner","hint":"Update the BOM for the next build so rework does not need to be repeated.","tags":[],"severity":"major"},{"id":"bu-rev-5","text":"Firmware workarounds for hardware issues are documented as errata","hint":"Note any hardware fault masked by firmware so the next revision fixes it or keeps the workaround.","tags":[],"severity":"major"},{"id":"bu-rev-6","text":"Open issues are triaged by severity with an owner and a decision for the next revision","hint":"Decide fix-now, fix-later or accept for each issue before releasing the next revision.","tags":[],"severity":"major"},{"id":"bu-rev-7","text":"Bring-up report summarizing results, deviations and open issues is written and reviewed","hint":"The report should include measured data against requirements and a recommendation on releasing the next revision.","tags":[],"severity":"major"}]}]}];
